1	import type { ExtensionAPI, ExtensionFactory } from "@earendil-works/pi-coding-agent";
2	import { createCCContext } from "./shared/context.js";
3	import type { ClaudeCodeToolsOptions } from "./shared/types.js";
4	import { registerOutputSpill } from "./output-spill.js";
5	import { registerRead } from "./tools/read.js";
6	import { registerWrite } from "./tools/write.js";
7	import { registerEdit } from "./tools/edit.js";
8	import { registerGrep } from "./tools/grep.js";
9	import { registerGlob } from "./tools/glob.js";
10	import { registerBash } from "./tools/bash.js";
11	import { registerTaskTools } from "./tools/task-tools.js";
12	import { registerNotebookEdit } from "./tools/notebook-edit.js";
13	import { registerTaskStop } from "./tools/task-stop.js";
14	import { registerAskUserQuestion } from "./tools/ask-user-question.js";
15	import { registerToolSearchActivation, withDeferredExposure } from "./deferred-tools.js";
16	import { registerTask, registerUnknownToolErrors } from "./subagent/index.js";
17	
18	export * from "./shared/types.js";
19	export { createClaudeCodeSession, type CreateClaudeCodeSessionOptions } from "./sdk.js";
20	
21	/**
22	 * Build a pi extension factory that installs Claude Code-compatible tools.
23	 * Pair with `createAgentSession({ noTools: "builtin" })` so pi's own read/bash/edit/write are disabled,
24	 * and add pi's `createToolSearchExtension()` if you use `deferredTools`.
25	 */
26	export function createClaudeCodeExtension(options: ClaudeCodeToolsOptions = {}): ExtensionFactory {
27		return (realPi: ExtensionAPI) => {
28			const cc = createCCContext(options, realPi);
29			const pi = withDeferredExposure(realPi, new Set(options.deferredTools ?? []));
30			registerRead(pi, cc);
31			registerWrite(pi, cc);
32			registerEdit(pi, cc);
33			registerGrep(pi, cc);
34			registerGlob(pi, cc);
35			registerBash(pi, cc);
36			registerNotebookEdit(pi, cc);
37			registerTaskTools(pi, cc);
38			registerTaskStop(pi, cc);
39			if (!options.isSubagent) registerAskUserQuestion(pi, cc);
40			if (!options.isSubagent && options.subagents !== false) registerTask(pi, cc);
41			// Claude Code wording for calls to tools that are not available
42			if (!options.isSubagent) registerUnknownToolErrors(realPi);
43			registerToolSearchActivation(realPi);
44			if (options.outputSpill !== false) registerOutputSpill(pi, cc);
45			// after spill, so notifications are never spilled into a file
46			(cc.notifications as { attachToToolResults?: () => void }).attachToToolResults?.();
47		};
48	}
