1	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
2	
3	/**
4	 * Returns a view of `pi` whose registerTool() registers the named tools with pi's native
5	 * `exposure: "deferred"`: they are not declared to the model until pi's built-in `tool_search`
6	 * finds and activates them.
7	 */
8	export function withDeferredExposure(pi: ExtensionAPI, deferred: ReadonlySet<string>): ExtensionAPI {
9		if (deferred.size === 0) return pi;
10		return new Proxy(pi, {
11			get(target, prop, receiver) {
12				if (prop === "registerTool") {
13					return (def: Parameters<ExtensionAPI["registerTool"]>[0]) =>
14						target.registerTool(deferred.has(def.name) ? { ...def, exposure: "deferred" } : def);
15				}
16				const value = Reflect.get(target, prop, receiver);
17				return typeof value === "function" ? value.bind(target) : value;
18			},
19		});
20	}
21	
22	/**
23	 * Activates pi's built-in `tool_search` (registered inactive by createToolSearchExtension())
24	 * whenever any registered tool — ours, the host's, or an MCP server's — has deferred exposure.
25	 */
26	export function registerToolSearchActivation(pi: ExtensionAPI): void {
27		const ensure = () => {
28			const all = pi.getAllTools();
29			if (!all.some((t) => t.name === "tool_search")) return;
30			if (!all.some((t) => t.exposure === "deferred")) return;
31			const active = pi.getActiveTools();
32			if (!active.includes("tool_search")) pi.setActiveTools([...active, "tool_search"]);
33		};
34		pi.on("session_start", ensure);
35		pi.on("before_agent_start", ensure);
36	}
