1	import { randomBytes } from "node:crypto";
2	import { mkdir, writeFile } from "node:fs/promises";
3	import { tmpdir } from "node:os";
4	import { join } from "node:path";
5	import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
6	import type { CCContext } from "./shared/context.js";
7	
8	/**
9	 * Large tool output → file, for every tool in the session (ours, other extensions', SDK
10	 * customTools, Task results). Mirrors Claude Code's tool-result persistence:
11	 *
12	 * - A result is persisted when its text exceeds the tool's threshold: Claude Code uses
13	 *   min(tool.maxResultSizeChars, 50000) — Grep 20000, Bash 30000, everything else 50000;
14	 *   Read is never persisted. `outputSpill.maxChars` overrides the threshold for every tool.
15	 * - Results containing images are never persisted.
16	 * - The inline replacement is `<persisted-output>` + size + path + a 2KB preview cut at a line break.
17	 * - A successful result with no text at all becomes "(<Tool> completed with no output)".
18	 *
19	 * Implemented as a `tool_result` handler. pi chains `tool_result` handlers in extension load order
20	 * (and registration order within an extension); each handler sees the previous handler's patch.
21	 * This handler therefore sees everything earlier handlers did, but extensions loaded AFTER ours
22	 * run after it.
23	 */
24	
25	/** Claude Code's cap on any tool's persistence threshold. */
26	export const SPILL_THRESHOLD_CEILING = 50_000;
27	/** Claude Code's per-tool maxResultSizeChars where it is below the ceiling. */
28	export const TOOL_SPILL_THRESHOLDS: Record<string, number> = { Grep: 20_000, Bash: 30_000 };
29	const DEFAULT_PREVIEW_CHARS = 2_000;
30	/** Never spilled: Read (spilling would make the model Read the spill file forever) and tool_search (schemas must stay inline). */
31	const ALWAYS_EXCLUDED = ["Read", "tool_search"];
32	
33	export const PERSISTED_OUTPUT_OPEN = "<persisted-output>";
34	export const PERSISTED_OUTPUT_CLOSE = "</persisted-output>";
35	
36	/** Claude Code's size formatter (1024-based, trailing ".0" dropped). */
37	export function formatSize(bytes: number): string {
38		const kb = bytes / 1024;
39		if (kb < 1) return `${bytes} bytes`;
40		if (kb < 1024) return `${kb.toFixed(1).replace(/\.0$/, "")}KB`;
41		const mb = kb / 1024;
42		if (mb < 1024) return `${mb.toFixed(1).replace(/\.0$/, "")}MB`;
43		return `${(mb / 1024).toFixed(1).replace(/\.0$/, "")}GB`;
44	}
45	
46	function sanitize(s: string, max = 100): string {
47		const out = s.replace(/[^A-Za-z0-9._-]+/g, "_").replace(/^\.+/, "_").slice(0, max);
48		return out || "unknown";
49	}
50	
51	/** First `max` chars, cut at the last line break when that keeps more than half of the budget. */
52	export function makePreview(text: string, max: number): { preview: string; truncated: boolean } {
53		if (text.length <= max) return { preview: text, truncated: false };
54		const nl = text.slice(0, max).lastIndexOf("\n");
55		return { preview: text.slice(0, nl > max * 0.5 ? nl : max), truncated: true };
56	}
57	
58	/** The `<persisted-output>` message Claude Code puts in place of a large result. */
59	export function formatPersistedOutput(opts: { size: number; path: string; preview: string; truncated: boolean; previewChars?: number }): string {
60		return (
61			`${PERSISTED_OUTPUT_OPEN}\n` +
62			`Output too large (${formatSize(opts.size)}). Full output saved to: ${opts.path}\n\n` +
63			`Preview (first ${formatSize(opts.previewChars ?? DEFAULT_PREVIEW_CHARS)}):\n` +
64			opts.preview +
65			(opts.truncated ? "\n...\n" : "\n") +
66			PERSISTED_OUTPUT_CLOSE
67		);
68	}
69	
70	/** Persistence threshold for a tool (characters of text; results strictly larger are spilled). */
71	export function spillThreshold(toolName: string, maxChars?: number): number {
72		if (maxChars !== undefined) return Math.max(1, maxChars);
73		return Math.min(TOOL_SPILL_THRESHOLDS[toolName] ?? SPILL_THRESHOLD_CEILING, SPILL_THRESHOLD_CEILING);
74	}
75	
76	export function registerOutputSpill(pi: ExtensionAPI, cc: CCContext): void {
77		if (cc.options.outputSpill === false) return;
78		const opts = cc.options.outputSpill;
79		const previewChars = Math.max(0, opts?.previewChars ?? DEFAULT_PREVIEW_CHARS);
80		const excluded = new Set([...ALWAYS_EXCLUDED, ...(opts?.exclude ?? [])]);
81		const fallbackId = randomBytes(8).toString("hex");
82	
83		const spillDir = (ctx: ExtensionContext): string => {
84			if (opts?.dir) return opts.dir;
85			let sessionId: string | undefined;
86			try {
87				sessionId = ctx.sessionManager?.getSessionId?.();
88			} catch {
89				sessionId = undefined;
90			}
91			return join(tmpdir(), "pi-cc-tool-results", sanitize(sessionId || fallbackId));
92		};
93	
94		pi.on("tool_result", async (event, ctx) => {
95			if (event.isError) return undefined;
96			const content = event.content ?? [];
97			const texts = content.filter((b): b is Extract<typeof b, { type: "text" }> => b.type === "text");
98			const hasImage = content.some((b) => b.type !== "text");
99	
100			if (!hasImage && texts.every((b) => typeof b.text !== "string" || b.text.trim() === "")) {
101				return { content: [{ type: "text", text: `(${event.toolName} completed with no output)` }] };
102			}
103			if (excluded.has(event.toolName) || hasImage) return undefined;
104	
105			let total = 0;
106			for (const b of texts) total += b.text.length;
107			if (total <= spillThreshold(event.toolName, opts?.maxChars)) return undefined;
108	
109			// Claude Code persists a single text result as text, a multi-block result as JSON.
110			const isJson = texts.length > 1;
111			const fullText = isJson ? JSON.stringify(texts, null, 2) : texts[0].text;
112			const dir = spillDir(ctx);
113			const path = join(dir, `${sanitize(event.toolCallId)}.${isJson ? "json" : "txt"}`);
114			try {
115				await mkdir(dir, { recursive: true });
116				await writeFile(path, fullText, "utf8");
117			} catch {
118				// Claude Code keeps the original result when it cannot be persisted.
119				return undefined;
120			}
121			const { preview, truncated } = makePreview(fullText, previewChars);
122			const text = formatPersistedOutput({ size: fullText.length, path, preview, truncated, previewChars });
123			cc.emit({ type: "output_spilled", toolName: event.toolName, toolCallId: event.toolCallId, path, totalChars: total });
124			return { content: [{ type: "text", text }] };
125		});
126	}
