1	import { randomBytes } from "node:crypto";
2	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
3	import { BackgroundTaskRegistry } from "./background.js";
4	import { FileStateTracker } from "./file-state.js";
5	import { NotificationQueue } from "./notifications.js";
6	import type { ClaudeCodeHostEvent, ClaudeCodeToolsOptions } from "./types.js";
7	
8	/** Per-session shared state handed to every module's register function. */
9	export interface CCContext {
10		options: ClaudeCodeToolsOptions;
11		fileState: FileStateTracker;
12		/** Background bash commands and agents (TaskStop, notifications). */
13		tasks: BackgroundTaskRegistry;
14		/** Background-task notifications: attached to the next tool result, or start a turn when idle. */
15		notifications: Pick<NotificationQueue, "enqueue" | "discard">;
16		emit(event: ClaudeCodeHostEvent): void;
17		/** The session's task list (set by the task tools; passed to subagents). */
18		taskStore?: import("../tools/task-tools.js").TaskStore;
19	}
20	
21	/** `pi` is needed for notifications; unit tests may omit it (notifications are then dropped). */
22	export function createCCContext(options: ClaudeCodeToolsOptions, pi?: ExtensionAPI): CCContext {
23		const sessionKey = randomBytes(8).toString("hex");
24		return {
25			options,
26			fileState: new FileStateTracker(),
27			tasks: new BackgroundTaskRegistry(() => sessionKey),
28			notifications: pi ? new NotificationQueue(pi) : { enqueue() {}, discard() {} },
29			emit(event) {
30				try {
31					options.onEvent?.(event);
32				} catch {
33					// host errors must never break the agent loop
34				}
35			},
36		};
37	}
