1	import { existsSync, readFileSync, writeFileSync } from "node:fs";
2	import { tmpdir } from "node:os";
3	import { join } from "node:path";
4	import { describe, expect, it } from "vitest";
5	import type { ExtensionAPI, ExtensionFactory } from "@earendil-works/pi-coding-agent";
6	import { formatPersistedOutput, formatSize, makePreview, registerOutputSpill, spillThreshold } from "../src/output-spill.js";
7	import { createCCContext } from "../src/shared/context.js";
8	import type { ClaudeCodeHostEvent } from "../src/shared/types.js";
9	import { createTestSession, fakeCtx, fauxAssistantMessage, fauxToolCall, tempDir } from "./helpers.js";
10	
11	function bigText(lines: number, width = 99): string {
12		const out: string[] = [];
13		for (let i = 1; i <= lines; i++) out.push(`line ${String(i).padStart(5, "0")} ${"x".repeat(width - 11)}`);
14		return out.join("\n");
15	}
16	
17	function tool(pi: ExtensionAPI, name: string, run: (p: any) => any) {
18		pi.registerTool({
19			name,
20			label: name,
21			description: name,
22			parameters: { type: "object", properties: { n: { type: "number" } } } as any,
23			async execute(_id, p: any) {
24				return run(p);
25			},
26		});
27	}
28	
29	const BIG = bigText(600); // 600 lines * 100 chars ≈ 60k (> the 50k default threshold)
30	const tools: ExtensionFactory = (pi) => {
31		tool(pi, "Big", () => ({ content: [{ type: "text", text: BIG }], details: { kept: true } }));
32		tool(pi, "Small", () => ({ content: [{ type: "text", text: "small" }], details: {} }));
33		tool(pi, "Empty", () => ({ content: [{ type: "text", text: "" }], details: {} }));
34		tool(pi, "BigImg", () => ({
35			content: [
36				{ type: "text", text: BIG },
37				{ type: "image", data: "aGVsbG8=", mimeType: "image/png" },
38			],
39			details: {},
40		}));
41		tool(pi, "BigFail", () => {
42			throw new Error(BIG);
43		});
44	};
45	
46	/** Drive the registered tool_result handler directly. */
47	function handlerHarness(options: Parameters<typeof createCCContext>[0]) {
48		const handlers: Function[] = [];
49		const fakePi = new Proxy({}, { get: (_t, p) => (p === "on" ? (ev: string, h: Function) => ev === "tool_result" && handlers.push(h) : () => undefined) });
50		registerOutputSpill(fakePi as any, createCCContext(options));
51		const ctx = fakeCtx(tempDir());
52		return async (toolName: string, content: any[], isError = false) => {
53			let ev: any = { type: "tool_result", toolName, toolCallId: "x", input: {}, content, isError };
54			for (const h of handlers) {
55				const r = await h(ev, ctx);
56				if (r) ev = { ...ev, ...r };
57			}
58			return ev.content as any[];
59		};
60	}
61	
62	describe("output spill", () => {
63		it("spills large output to a file and leaves Claude Code's <persisted-output> preview", async () => {
64			const events: ClaudeCodeHostEvent[] = [];
65			const dir = tempDir("pi-cc-spill-");
66			const t = await createTestSession({
67				claudeCode: { outputSpill: { dir }, onEvent: (e) => events.push(e) },
68				extraExtensions: [tools],
69				responses: [
70					fauxAssistantMessage([fauxToolCall("Big", {}, { id: "call/1" }), fauxToolCall("Small", {})], { stopReason: "toolUse" }),
71					fauxAssistantMessage("done"),
72				],
73			});
74			await t.session.prompt("go");
75			const [big, small] = t.toolResults();
76			const path = join(dir, "call_1.txt");
77			expect(readFileSync(path, "utf8")).toBe(BIG);
78			expect(big!.isError).toBe(false);
79			expect(big!.details).toEqual({ kept: true });
80			const preview = BIG.slice(0, BIG.slice(0, 2000).lastIndexOf("\n"));
81			expect(big!.text).toBe(
82				`<persisted-output>\nOutput too large (58.6KB). Full output saved to: ${path}\n\nPreview (first 2KB):\n${preview}\n...\n</persisted-output>`,
83			);
84			expect(small!.text).toBe("small");
85			expect(events).toContainEqual({ type: "output_spilled", toolName: "Big", toolCallId: "call/1", path, totalChars: BIG.length });
86			t.dispose();
87		});
88	
89		it("never spills results with images or error results; honors exclude/maxChars", async () => {
90			const dir = tempDir("pi-cc-spill-");
91			const t = await createTestSession({
92				claudeCode: { outputSpill: { dir, maxChars: 40000, exclude: ["Small"] } },
93				extraExtensions: [tools],
94				responses: [
95					fauxAssistantMessage([fauxToolCall("BigImg", {}), fauxToolCall("BigFail", {})], { stopReason: "toolUse" }),
96					fauxAssistantMessage("done"),
97				],
98			});
99			await t.session.prompt("go");
100			const msgs = t.session.messages.filter((m: any) => m.role === "toolResult") as any[];
101			const img = msgs.find((m) => m.toolName === "BigImg");
102			expect(img.content.map((c: any) => c.type)).toEqual(["text", "image"]);
103			expect(img.content[0].text).toBe(BIG);
104			const fail = msgs.find((m) => m.toolName === "BigFail");
105			expect(fail.isError).toBe(true);
106			expect(fail.content[0].text).not.toContain("Output too large");
107			t.dispose();
108		});
109	
110		it("does not spill when under the limit, excluded, or disabled", async () => {
111			const dir = tempDir("pi-cc-spill-");
112			const t = await createTestSession({
113				claudeCode: { outputSpill: { dir, exclude: ["Big"] } },
114				extraExtensions: [tools],
115				responses: [fauxAssistantMessage(fauxToolCall("Big", {}), { stopReason: "toolUse" }), fauxAssistantMessage("done")],
116			});
117			await t.session.prompt("go");
118			expect(t.toolResults()[0]!.text).toBe(BIG);
119			t.dispose();
120	
121			const t2 = await createTestSession({
122				claudeCode: { outputSpill: false },
123				extraExtensions: [tools],
124				responses: [fauxAssistantMessage(fauxToolCall("Big", {}), { stopReason: "toolUse" }), fauxAssistantMessage("done")],
125			});
126			await t2.session.prompt("go");
127			expect(t2.toolResults()[0]!.text).toBe(BIG);
128			t2.dispose();
129		});
130	
131		it("defaults the directory to <tmpdir>/pi-cc-tool-results/<sessionId>", async () => {
132			const t = await createTestSession({
133				extraExtensions: [tools],
134				responses: [fauxAssistantMessage(fauxToolCall("Big", {}, { id: "abc" }), { stopReason: "toolUse" }), fauxAssistantMessage("done")],
135			});
136			await t.session.prompt("go");
137			const expected = join(tmpdir(), "pi-cc-tool-results", t.session.sessionManager.getSessionId(), "abc.txt");
138			expect(t.toolResults()[0]!.text).toContain(expected);
139			expect(existsSync(expected)).toBe(true);
140			t.dispose();
141		});
142	
143		it("replaces an empty result with '(<Tool> completed with no output)'", async () => {
144			const t = await createTestSession({
145				extraExtensions: [tools],
146				responses: [fauxAssistantMessage(fauxToolCall("Empty", {}), { stopReason: "toolUse" }), fauxAssistantMessage("done")],
147			});
148			await t.session.prompt("go");
149			expect(t.toolResults()[0]!.text).toBe("(Empty completed with no output)");
150			t.dispose();
151		});
152	
153		it("uses Claude Code's per-tool thresholds: Grep 20000, Bash 30000, others 50000; never Read", async () => {
154			const run = handlerHarness({ outputSpill: { dir: tempDir() } });
155			const text = (n: number) => [{ type: "text", text: "a".repeat(n) }];
156			expect((await run("Grep", text(20000)))[0].text).toHaveLength(20000);
157			expect((await run("Grep", text(20001)))[0].text).toMatch(/^<persisted-output>\nOutput too large \(19.5KB\)/);
158			expect((await run("Bash", text(30000)))[0].text).toHaveLength(30000);
159			expect((await run("Bash", text(30001)))[0].text).toContain("Output too large (29.3KB)");
160			expect((await run("Glob", text(50000)))[0].text).toHaveLength(50000);
161			expect((await run("Glob", text(50001)))[0].text).toContain("Output too large");
162			expect((await run("Read", text(500000)))[0].text).toHaveLength(500000);
163			expect(spillThreshold("Anything")).toBe(50000);
164			expect(spillThreshold("Grep", 10)).toBe(10);
165		});
166	
167		it("persists multi-block text results as JSON", async () => {
168			const dir = tempDir();
169			const run = handlerHarness({ outputSpill: { dir } });
170			const blocks = [
171				{ type: "text", text: "a".repeat(30000) },
172				{ type: "text", text: "b".repeat(30000) },
173			];
174			const out = await run("Multi", blocks);
175			const file = out[0].text.match(/saved to: (.*)\n/)[1];
176			expect(file.endsWith(".json")).toBe(true);
