81	/**
82	 * Directly execute a registered tool without a model, for unit tests.
83	 * Returns the tool definition map captured from the extension factory.
84	 */
85	export function captureTools(factory: ExtensionFactory): { tools: Map<string, ToolDefinition>; handlers: Map<string, Function[]> } {
86		const tools = new Map<string, ToolDefinition>();
87		const handlers = new Map<string, Function[]>();
88		const fakePi = new Proxy(
89			{},
90			{
91				get(_t, prop) {
92					if (prop === "registerTool") return (def: ToolDefinition) => tools.set(def.name, def);
93					if (prop === "on") return (ev: string, h: Function) => handlers.set(ev, [...(handlers.get(ev) ?? []), h]);
94					if (prop === "getAllTools") return () => [...tools.values()].map((t) => ({ name: t.name, description: t.description, parameters: t.parameters, sourceInfo: { source: "extension" } }));
95					if (prop === "getActiveTools") return () => [...tools.keys()];
96					return () => undefined;
97				},
98			},
99		) as ExtensionAPI;
100		factory(fakePi);
101		return { tools, handlers };
102	}
