112	/**
113	 * ModelRuntime (auth file in a temp dir, no network). Pass a faux registration to register the faux
114	 * provider and its models with the runtime (pi 1.x only runs models of providers the runtime knows),
115	 * or a provider id to just give that provider a test key.
116	 */
117	export async function createTestModelRuntime(
118		providerOrFaux: string | ReturnType<typeof registerFauxProvider>,
119		dir = tempDir("pi-cc-auth-"),
120	): Promise<ModelRuntime> {
121		const runtime = await ModelRuntime.create({ authPath: join(dir, "auth.json"), modelsPath: null, refreshOnCreate: false });
122		if (typeof providerOrFaux === "string") {
123			await runtime.setRuntimeApiKey(providerOrFaux, "test-key");
124			return runtime;
125		}
126		const faux = providerOrFaux;
127		const provider = faux.getModel().provider;
128		runtime.registerProvider(provider, {
129			name: "Faux",
130			api: faux.api as any,
131			baseUrl: faux.getModel().baseUrl || "http://faux.invalid",
132			apiKey: "test-key",
133			models: faux.models.map((m) => ({
134				id: m.id,
135				name: m.name,
136				reasoning: m.reasoning,
137				input: m.input,
138				cost: m.cost,
139				contextWindow: m.contextWindow,
140				maxTokens: m.maxTokens,
141			})) as any,
142		});
143		return runtime;
