16	export function sendReminder(pi: ExtensionAPI, text: string, opts: { wake?: boolean; details?: unknown } = {}): void {
17		pi.sendMessage(
18			{ customType: REMINDER_CUSTOM_TYPE, content: wrapReminder(text), display: false, details: opts.details },
19			opts.wake ? { deliverAs: "followUp", triggerTurn: true } : { deliverAs: "steer" },
20		);
21	}
