6	export async function createWorkspace(s: Scenario, harness: string): Promise<string> {
7		const cwd = mkdtempSync(join(tmpdir(), `parity-${s.name}-${harness}-`));
8		for (const [p, content] of Object.entries(s.files ?? {})) {
9			const abs = join(cwd, p);
10			mkdirSync(dirname(abs), { recursive: true });
11			writeFileSync(abs, content);
12		}
13		await s.setup?.(cwd);
14		return cwd;
15	}
