17	/** Snapshot text files in the workspace (skips .git and binaries). */
18	export function snapshot(cwd: string, only?: string[]): Record<string, string> {
19		const out: Record<string, string> = {};
20		const walk = (dir: string) => {
21			for (const name of readdirSync(dir)) {
22				if (name === ".git" || name === "node_modules") continue;
23				const abs = join(dir, name);
24				const st = statSync(abs);
25				if (st.isDirectory()) walk(abs);
26				else {
27					const rel = relative(cwd, abs);
28					if (only && !only.includes(rel)) continue;
29					const buf = readFileSync(abs);
30					out[rel] = buf.includes(0) ? `<binary ${buf.length} bytes>` : buf.toString("utf8");
31				}
32			}
33		};
34		walk(cwd);
35		return out;
36	}
