16	/** Recreate a repository snapshot as a fresh git repo with a deterministic single commit. */
17	export function materializeFixture(f: GitFixture, cwd: string): void {
18		const archive = execFileSync("git", ["-C", f.repo, "archive", f.commit], { maxBuffer: 512 * 1024 * 1024 });
19		execFileSync("tar", ["-x", "-C", cwd], { input: archive });
20		if (f.linkNodeModules !== false && existsSync(join(f.repo, "node_modules"))) symlinkSync(join(f.repo, "node_modules"), join(cwd, "node_modules"));
21		const env = { ...process.env, GIT_AUTHOR_NAME: "parity", GIT_AUTHOR_EMAIL: "parity@example.com", GIT_COMMITTER_NAME: "parity", GIT_COMMITTER_EMAIL: "parity@example.com", GIT_AUTHOR_DATE: FIXED_DATE, GIT_COMMITTER_DATE: FIXED_DATE };
22		const git = (...args: string[]) => execFileSync("git", args, { cwd, env, stdio: "ignore" });
23		git("init", "-q", "-b", "main");
24		git("add", "-A");
25		git("commit", "-q", "-m", `snapshot of ${f.commit}`);
26	}
