5	
6	/**
7	 * Harness-injected reminders that are not part of a tool's own output (context-usage counters,
8	 * "you haven't used the task tools" nudges). Stripped before comparing.
9	 */
10	const NOISE_REMINDERS = [/<total_tokens>/, /tools? (haven't|hasn't) been used recently/i, /Available agent types for the Agent tool/];
11	
12	export function stripNoise(text: string): string {
13		return text
14			.replace(/\n*<system-reminder>[\s\S]*?<\/system-reminder>/g, (block) => (NOISE_REMINDERS.some((re) => re.test(block)) ? "" : block))
15			.replace(/^<tool_use_error>([\s\S]*)<\/tool_use_error>$/, "$1");
16	}
17	
18	/** Remove run-specific noise so equal behavior compares equal. */
19	export function normalize(text: string, cwd: string): string {
20		let out = stripNoise(text);
21		const cwds = new Set([cwd]);
22		try {
23			cwds.add(realpathSync(cwd));
24		} catch {}
25		for (const c of [...cwds].sort((a, b) => b.length - a.length)) out = out.replaceAll(c, "<CWD>");
26		const tmp = tmpdir();
27		out = out
28			.replace(new RegExp(`${tmp.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}/[^\\s"'<>)]*`, "g"), "<TMP>")
29			.replace(/\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?Z/g, "<TS>")
30			.replace(/\b\d+(\.\d+)?\s?(ms|s)\b/g, "<DUR>")
31			.replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/g, "<UUID>")
32			.replace(/\b(agentId|agent_id|task_id|shell_id|bash_id)(["':=\s]+)[\w-]+/gi, "$1$2<ID>")
33			.replace(/(\bID:\s*|\btask:\s*|\bshell:\s*|<task-id>|<tool-use-id>)[\w-]+/g, "$1<ID>")
34			.replace(/\bbash_\d+\b/g, "<ID>")
35			.replace(/\b(duration_ms|durationMs)(["':=\s]+)\d+/g, "$1$2<N>")
36			.replace(/<(duration_ms|subagent_tokens)>\d+<\/\1>/g, "<$1><N></$1>")
37			.replace(/[ \t]+$/gm, "")
38			.replace(/^\n+|\s+$/g, "");
39		return out;
40	}
