42	export type Verdict = "same" | "differs" | "only-claude" | "only-pi" | "both-missing" | "skipped";
43	
44	export interface StepComparison {
45		label: string;
46		claude: StepResult;
47		pi: StepResult;
48		verdict: Verdict;
49		statusDiffers: boolean;
50		diff?: string;
51		claudeText: string;
52		piText: string;
53	}
54	
55	export interface ScenarioComparison {
56		scenario: Scenario;
57		claude: RunOutcome;
58		pi: RunOutcome;
59		steps: StepComparison[];
60		fileDiffs: Array<{ path: string; diff: string }>;
61		toolSetOnlyClaude: string[];
62		toolSetOnlyPi: string[];
63		schemaDiffs: Array<{ tool: string; onlyClaude: string[]; onlyPi: string[] }>;
64		subagentToolDiffs: Array<{ name: string; claude: string[]; pi: string[] }>;
65	}
66	
67	function props(schema: any): string[] {
68		return Object.keys(schema?.properties ?? {}).sort();
69	}
70	
71	export function compare(s: Scenario, claude: RunOutcome, pi: RunOutcome): ScenarioComparison {
72		const steps: StepComparison[] = claude.steps.map((c, i) => {
73			const p = pi.steps[i];
74			const claudeText = normalize(c.text, claude.cwd);
75			const piText = normalize(p.text, pi.cwd);
76			let verdict: Verdict;
77			if (c.status === "skipped" || p.status === "skipped") verdict = "skipped";
78			else if (c.status === "missing" && p.status === "missing") verdict = "both-missing";
79			else if (c.status === "missing") verdict = "only-pi";
80			else if (p.status === "missing") verdict = "only-claude";
81			else verdict = claudeText === piText && c.isError === p.isError ? "same" : "differs";
82			const diff =
83				verdict === "differs" && claudeText !== piText
84					? createTwoFilesPatch("claude", "pi", claudeText + "\n", piText + "\n", "", "", { context: 2 })
85							.split("\n")
86							.slice(2)
87							.join("\n")
88					: undefined;
89			return { label: c.label, claude: c, pi: p, verdict, statusDiffers: c.isError !== p.isError, diff, claudeText, piText };
90		});
