29	const upstream = arg("upstream");
30	const upstreamModel = arg("upstream-model");
31	const apiKey = process.env.ANTHROPIC_API_KEY;
32	if (!apiKey && !upstream) throw new Error("ANTHROPIC_API_KEY is required for recording (or pass --upstream for a proxy that injects credentials)");
33	const model = arg("model") ?? "claude-sonnet-5-5";
34	const repo = resolve(arg("repo") ?? ".");
35	const fixture = { repo, commit: resolveCommit(repo, arg("ref") ?? "HEAD") };
36	
37	const mock = new MockAnthropicServer();
38	const baseUrl = await mock.start();
39	mkdirSync(join(import.meta.dirname, "recordings"), { recursive: true });
40	mock.startRecording({ apiKey, upstream, model: upstreamModel, liveFile: join(import.meta.dirname, "recordings", `${name}.raw.json`) });
41	const scenario = { ...recordingToScenario({ name, description: "", prompt, model, recordedAt: "", fixture, recordedCwd: "", conversations: [{ name: "main", turns: [], toolResults: [] }] }), maxTurns: Number(arg("max-turns") ?? 100) };
42	process.stderr.write(`recording ${name} with ${model} (fixture ${fixture.commit.slice(0, 7)})…\n`);
43	const outcome = await runClaude(scenario, mock, baseUrl, model);
44	await mock.stop();
45	if (outcome.error) process.stderr.write(`claude run ended with: ${outcome.error.slice(0, 500)}\n`);
46	
47	// save the raw capture first, so a post-processing error never loses a (long, paid) recording
48	const dir = join(import.meta.dirname, "recordings");
49	mkdirSync(dir, { recursive: true });
50	writeFileSync(join(dir, `${name}.raw.json`), JSON.stringify({ prompt, model, upstreamModel, fixture, cwd: outcome.cwd, conversations: [...mock.recording.values()] }));
51	
52	// main conversation = the one whose first user message contains the prompt
