54	const main = convs.find((c) => c.firstUser.includes(prompt));
55	if (!main) throw new Error("main conversation not found in recording");
56	const agentPrompts = convs.flatMap((c) => c.turns.flatMap((t) => (t?.content ?? []).filter((b) => b.type === "tool_use" && b.name === "Agent").map((b) => String(b.input?.prompt ?? ""))));
