66	const matches = subs.map((c) => matchFor(c.firstUser)).filter(Boolean);
67	if (unmatched) process.stderr.write(`warning: ${unmatched} subagent conversation(s) have no matching Agent prompt and will not replay\n`);
68	if (new Set(matches).size !== matches.length) process.stderr.write("warning: several subagents share the same Agent prompt; replay routes them to the first\n");
69	const recording: Recording = {
70		name,
71		description: arg("description") ?? `Recorded session: ${prompt.slice(0, 120)}`,
72		prompt,
73		model: upstreamModel ? `${upstreamModel} (via ${upstream})` : model,
74		recordedAt: new Date().toISOString(),
75		fixture,
76		recordedCwd: outcome.cwd,
77		conversations: [
78			{ name: "main", turns: main.turns.map((t) => t ?? null), toolResults: main.toolResults },
79			...subs.map((c, i) => ({ name: `sub${i}`, match: matchFor(c.firstUser), firstUser: c.firstUser.replaceAll(outcome.cwd, "{{cwd}}"), turns: c.turns.map((t) => t ?? null), toolResults: c.toolResults })),
80		],
81	};
82	const file = join(dir, `${name}.json`);
83	writeFileSync(file, JSON.stringify(recording, null, 2));
