8	import { join } from "node:path";
9	import { compare, type ScenarioComparison } from "./compare.js";
10	import { MockAnthropicServer } from "./mock-server.js";
11	import { renderReport } from "./report.js";
12	import { runClaude } from "./runners/claude-sdk.js";
13	import { runPi } from "./runners/pi.js";
