8	export function renderReport(results: ScenarioComparison[], meta: { model: string; date: string }): string {
9		const out: string[] = [];
10		out.push(`# Parity report: Claude Agent SDK vs pi-claude`, "");
11		out.push(`Model output is scripted by a mock Anthropic API, so both harnesses received identical tool calls. Differences below come from the tools/harness. Model id sent: \`${meta.model}\`. Generated ${meta.date}.`, "");
12		out.push(`| Scenario | Steps same | Differ | Missing | File diffs | Extra turns | Errors |`, `|---|---|---|---|---|---|---|`);
13		for (const r of results) {
14			const n = (v: string) => r.steps.filter((s) => s.verdict === v).length;
15			const missing = n("only-claude") + n("only-pi") + n("both-missing");
16			const errs = [r.claude.error && "claude", r.pi.error && "pi"].filter(Boolean).join(", ") || "—";
17			out.push(`| [${r.scenario.name}](#${r.scenario.name}) | ${n("same")}/${r.steps.length - n("skipped")} | ${n("differs")} | ${missing} | ${r.fileDiffs.length} | ${r.claude.extraTurns.length}/${r.pi.extraTurns.length} | ${errs} |`);
18		}
19		out.push("", "_Extra turns = claude/pi model requests beyond the script (e.g. background-task wake-ups)._", "");
20	
21		const first = results[0];
22		if (first) {
23			out.push(`## Tool sets declared to the model`, "");
24			out.push(`- Only in Claude Code: ${first.toolSetOnlyClaude.map((t) => `\`${t}\``).join(", ") || "—"}`);
25			out.push(`- Only in pi-claude: ${first.toolSetOnlyPi.map((t) => `\`${t}\``).join(", ") || "—"}`, "");
26			if (first.schemaDiffs.length) {
27				out.push(`| Tool | Params only in Claude Code | Params only in pi-claude |`, `|---|---|---|`);
28				for (const d of first.schemaDiffs) out.push(`| ${d.tool} | ${d.onlyClaude.join(", ") || "—"} | ${d.onlyPi.join(", ") || "—"} |`);
29				out.push("");
30			}
31		}
32	
33		for (const r of results) {
34			out.push(`## ${r.scenario.name}`, "", r.scenario.description, "");
35			if (r.claude.error) out.push(`**Claude run error:**`, fence(clip(r.claude.error, 800)), "");
36			if (r.pi.error) out.push(`**pi run error:**`, fence(clip(r.pi.error, 800)), "");
37			out.push(`| # | Step | Claude | pi | Verdict |`, `|---|---|---|---|---|`);
38			r.steps.forEach((s, i) => {
39				const tools = s.claude.tool === s.pi.tool ? s.claude.tool : `${s.claude.tool} / ${s.pi.tool}`;
40				out.push(`| ${i + 1} | ${s.label} (\`${tools}\`) | ${status(s.claude)} | ${status(s.pi)} | ${icon[s.verdict]}${s.statusDiffers && s.verdict === "differs" ? " (error flag)" : ""} |`);
41			});
42			out.push("");
43			r.steps.forEach((s, i) => {
44				if (s.verdict === "same" || s.verdict === "skipped" || s.verdict === "both-missing") return;
45				out.push(`<details><summary>${i + 1}. ${s.label}: ${icon[s.verdict]}</summary>`, "");
46				if (s.diff) out.push(fence(clip(s.diff, 3000), "diff"));
47				else {
48					out.push("Claude:", fence(clip(s.claudeText)), "pi:", fence(clip(s.piText)));
49				}
50				out.push("", "</details>", "");
51			});
52			if (r.subagentToolDiffs.length) {
53				out.push(`**Subagent tool sets differ:**`);
54				for (const d of r.subagentToolDiffs) out.push(`- ${d.name}: claude [${d.claude.join(", ")}] vs pi [${d.pi.join(", ")}]`);
55				out.push("");
56			}
57			if (r.fileDiffs.length) {
58				out.push(`**Workspace differences after the run:**`, "");
59				for (const f of r.fileDiffs) out.push(`- \`${f.path}\``, fence(clip(f.diff, 2000), "diff"));
60				out.push("");
61			}
62			for (const [h, o] of [["claude", r.claude], ["pi", r.pi]] as const) {
63				if (o.extraTurns.length) out.push(`**Extra ${h} turns:**`, ...o.extraTurns.map((t) => `- ${t}`), "");
64			}
65		}
66		return out.join("\n");
67	}
