11	export async function runPi(s: Scenario, mock: MockAnthropicServer, baseUrl: string, modelId: string): Promise<RunOutcome> {
12		const cwd = await createWorkspace(s, "pi");
13		mock.load(
14			{
15				main: toMockTurns(s.turns, "pi", cwd),
16				subagents: Object.fromEntries(Object.entries(s.subagents ?? {}).map(([k, v]) => [k, toMockTurns(v, "pi", cwd)])),
17				subagentRoutes: s.subagentRoutes?.map((r) => ({ ...r, match: r.match.replaceAll("{{cwd}}", cwd) })),
18			},
19			"pi",
20		);
21		const t0 = Date.now();
22		let error: string | undefined;
23		const home = mkdtempSync(join(tmpdir(), "parity-pi-home-"));
24		const modelRuntime = await ModelRuntime.create({ authPath: join(home, "auth.json"), modelsPath: null, refreshOnCreate: false });
25		await modelRuntime.setRuntimeApiKey("anthropic", "sk-ant-mock");
26		const base = modelRuntime.getModel("anthropic", modelId);
27		if (!base) throw new Error(`unknown model ${modelId}`);
28		const model = { ...base, baseUrl };
29		const { session } = await createClaudeCodeSession({
30			cwd,
31			agentDir: home,
32			model,
33			modelRuntime,
34			thinkingLevel: "off",
35			sessionManager: SessionManager.inMemory(cwd),
36			settingsManager: SettingsManager.inMemory({ compaction: { enabled: false } } as any),
37			claudeCode: {
38				loadAgentsFromDisk: false,
39				outputSpill: { dir: join(home, "tool-results") },
40				onAskUserQuestion: async (qs) => Object.fromEntries(qs.map((q) => [q.question, q.options[0]?.label ?? ""])),
41			},
42			loader: { noSkills: true, noContextFiles: true, noPromptTemplates: true, noThemes: true, noExtensions: true },
43		});
44		try {
45			await session.bindExtensions({});
46			await session.prompt(s.prompt);
47			// let background notifications (if any) play out
48			await new Promise((r) => setTimeout(r, 300));
49			await session.waitForIdle?.();
50		} catch (e) {
51			error = (e as Error).message;
52		} finally {
53			session.dispose();
54		}
55		return collectOutcome(mock, s, "pi", { files: snapshot(cwd, s.compareFiles), error, durationMs: Date.now() - t0, cwd });
56	}
