437	/** Cut a too-large whole-file read down to what fits the token cap (Claude Code's paged view). */
438	function pageDown(content: string, tokenCount: number, maxTokens: number): { text: string; lines: number; byChars: boolean } {
439		const lines = content.split("\n");
440		const charsPerToken = Math.max(0.5, content.length / Math.max(1, tokenCount));
441		const tokensOf = (s: string) => s.length / charsPerToken;
442		let n = Math.max(1, Math.min(lines.length, Math.floor(((lines.length * maxTokens) / Math.max(1, tokenCount)) * 0.85)));
443		let text = lines.slice(0, n).join("\n");
444		for (let i = 0; i < 6; i++) {
445			if (tokensOf(text) <= maxTokens || n <= 1) break;
446			n = Math.max(1, Math.floor(n * 0.7));
447			text = lines.slice(0, n).join("\n");
448		}
449		if (tokensOf(text) > maxTokens || text.trim() === "") {
450			let chars = Math.max(1, Math.floor(maxTokens * charsPerToken * 0.85));
451			for (let i = 0; i < 6; i++) {
452				text = content.slice(0, chars);
453				if (tokensOf(text) <= maxTokens) break;
454				chars = Math.max(1, Math.floor(chars * 0.7));
455			}
456			const last = text.charCodeAt(text.length - 1);
457			if (last >= 0xd800 && last <= 0xdbff) text = text.slice(0, -1);
458			return { text, lines: text.split("\n").length, byChars: true };
459		}
460		return { text, lines: n, byChars: false };
461	}
