592			};
593			if (signal?.aborted) {
594				if (worktree) finishAgentWorktree(worktree);
595				await disposeSession(session);
596				throw new SubagentAbortedError();
597			}
598			const prompt = fork ? `${forkDirective(params.prompt)}${worktree ? `\n\n${forkWorktreeNotice(ctx.cwd, worktree.path)}` : ""}` : params.prompt;
599			const baseDetails: AgentDetails = {
600				agentId,
601				subagentType: def.name,
602				description: params.description,
603				status: "completed",
604				background,
605				model: modelLabel(run.model),
606				modelNote,
607			};
608			runs.set(agentId, run);
609	
610			if (background) {
611				run.outputFile = cc.tasks.outputPath(agentId);
612				run.task = cc.tasks.add({
613					id: agentId,
614					type: "local_agent",
615					label: params.description,
616					status: "running",
617					outputFile: run.outputFile,
618					toolUseId: toolCallId,
619					stop: () => stopRun(run),
620				});
621				// not tied to the parent's abort signal: the tool call returns immediately
622				run.done = runAgent(run, prompt, undefined).then(
623					(result) => finishBackground(run, { ok: true, result }),
624					(error) => finishBackground(run, { ok: false, error }),
625				);
626				return {
627					content: [{ type: "text", text: asyncLaunchText(agentId, run.outputFile) }],
628					details: { ...baseDetails, status: "async_launched", outputFile: run.outputFile },
629				};
630			}
631	
632			const forwardAbort = () => run.controller.abort();
633			signal?.addEventListener("abort", forwardAbort, { once: true });
634			let worktreeInfo: WorktreeInfo | undefined;
635			try {
636				const result = await runAgent(run, prompt, onUpdate);
637				worktreeInfo = worktree ? finishAgentWorktree(worktree) : undefined;
638				return {
639					content: [
640						{
641							type: "text",
642							text: foregroundResultText({
643								report: result.text,
644								agentId,
645								agentType: def.name,
646								usage: { totalTokens: result.totalTokens, toolUses: result.usage.toolUses, durationMs: result.usage.durationMs },
647								worktree: worktreeInfo,
648							}),
649						},
650					],
651					details: { ...baseDetails, usage: result.usage, worktree: worktreeInfo },
652				};
653			} catch (err) {
654				if (worktree) finishAgentWorktree(worktree);
655				throw err;
656			} finally {
657				signal?.removeEventListener("abort", forwardAbort);
658				runs.delete(agentId);
659				await disposeSession(session);
660			}
661		}
662	
663		pi.registerTool({
664			name: AGENT_TOOL_NAME,
665			label: "Agent",
666			description: AGENT_TOOL_DESCRIPTION,
667			promptSnippet: "Launch a subagent (general-purpose, Explore, Plan, fork, or a custom agent) for complex multi-step work",
668			parameters: AgentParams,
669			// Claude Code's InputValidationError wording (pi's own validation would word it differently)
670			prepareArguments: (args) => {
671				const invalid = validateAgentInput(args);
672				if (invalid) throw new Error(invalid);
673				return args as AgentInput;
674			},
675			execute: (toolCallId, params, signal, onUpdate, ctx) => execute(toolCallId, params as AgentInput, signal, onUpdate, ctx),
676		});
677	
678		if (!isSubagent) registerUnknownToolErrors(pi);
679	
680		// Claude Code lists the agent types in a system reminder (re-sent when the list changes).
681		pi.on("before_agent_start", (_event, ctx) => {
682			let listing: string;
683			try {
684				listing = formatAgentListingReminder(loadDefs(ctx.cwd));
685			} catch {
686				return undefined;
687			}
688			if (listing === lastListing) return undefined;
689			lastListing = listing;
690			return { message: { customType: REMINDER_CUSTOM_TYPE, content: wrapReminder(listing), display: false } };
691		});
692	
693		pi.on("session_shutdown", async () => {
694			shuttingDown = true;
695			await Promise.all(
696				[...runs.values()].map(async (run) => {
697					if (run.running) {
698						run.killedBy ??= "shutdown";
699						run.controller.abort();
700						await run.session.abort().catch(() => {});
701					}
702					if (run.done) await Promise.race([run.done, new Promise((r) => setTimeout(r, 5_000).unref?.())]);
703				}),
704			);
705		});
706	}
