6	/** Background task kinds, as Claude Code reports them in TaskStop results. */
7	export type BackgroundTaskType = "local_bash" | "local_agent";
8	export type BackgroundTaskStatus = "running" | "completed" | "failed" | "killed";
9	
10	export interface BackgroundTask {
11		id: string;
12		type: BackgroundTaskType;
13		/** Command (bash) or description (agent), shown in TaskStop results and notifications. */
14		label: string;
15		status: BackgroundTaskStatus;
16		/** File the task's output is written to (the model reads it with Read). */
17		outputFile?: string;
18		/** tool_use id of the call that started the task. */
19		toolUseId?: string;
20		/** Stop the task. Must resolve once it is stopped (status set to "killed" by the registry). */
21		stop(): void | Promise<void>;
22	}
23	
24	/**
25	 * Claude Code-style ids: bash tasks are "b" + 8 base36 chars, agents "a" + 16 hex chars.
26	 */
27	export function newTaskId(type: BackgroundTaskType): string {
28		if (type === "local_agent") return "a" + randomBytes(8).toString("hex").slice(0, 16);
29		let s = "";
30		const bytes = randomBytes(8);
31		for (const b of bytes) s += (b % 36).toString(36);
32		return "b" + s;
33	}
