35	/** Per-session registry of background tasks (bash commands and agents), used by TaskStop. */
36	export class BackgroundTaskRegistry {
37		private tasks = new Map<string, BackgroundTask>();
38		private dir?: string;
39	
40		constructor(private sessionKey: () => string) {}
41	
42		add(task: BackgroundTask): BackgroundTask {
43			this.tasks.set(task.id, task);
44			return task;
45		}
46	
47		get(id: string): BackgroundTask | undefined {
48			return this.tasks.get(id);
49		}
50	
51		list(): BackgroundTask[] {
52			return [...this.tasks.values()];
53		}
54	
55		/** Directory for task output files: <tmpdir>/pi-cc-tasks/<session>/tasks (created on demand). */
56		outputDir(): string {
57			if (!this.dir) {
58				this.dir = join(tmpdir(), "pi-cc-tasks", this.sessionKey().replace(/[^\w.-]/g, "_"), "tasks");
59				mkdirSync(this.dir, { recursive: true });
60			}
61			return this.dir;
62		}
63	
64		outputPath(id: string): string {
65			return join(this.outputDir(), `${id}.output`);
66		}
67	
68		async stop(id: string): Promise<BackgroundTask> {
69			const task = this.tasks.get(id);
70			if (!task) throw new Error(`No task found with ID: ${id}`);
71			if (task.status !== "running") throw new Error(`Task ${id} is not running (status: ${task.status})`);
72			await task.stop();
73			task.status = "killed";
74			return task;
75		}
76	
77		async stopAll(): Promise<void> {
78			await Promise.all(
79				this.list()
80					.filter((t) => t.status === "running")
81					.map(async (t) => {
82						try {
83							await t.stop();
84						} finally {
85							t.status = "killed";
86						}
87					}),
88			);
89		}
90	}
