5	/** Hard cap on captured output kept in memory per command (characters). Oldest output is dropped. */
6	export const OUTPUT_HARD_CAP = 10 * 1024 * 1024;
7	
8	/**
9	 * Append-only text buffer with a hard cap. When the cap is exceeded the oldest text is dropped,
10	 * but absolute offsets (used by read cursors) keep counting from the very first character.
11	 */
12	export class OutputBuffer {
13		private text = "";
14		/** Number of characters dropped from the front so far. */
15		private dropped = 0;
16	
17		constructor(private readonly cap = OUTPUT_HARD_CAP) {}
18	
19		append(chunk: string): void {
20			if (!chunk) return;
21			this.text += chunk;
22			if (this.text.length > this.cap) {
23				// drop in larger steps to avoid re-slicing on every append
24				const excess = this.text.length - Math.floor(this.cap * 0.9);
25				this.text = this.text.slice(excess);
26				this.dropped += excess;
27			}
28		}
29	
30		/** Absolute offset of the end of the buffer. */
31		get end(): number {
32			return this.dropped + this.text.length;
33		}
34	
35		get droppedChars(): number {
36			return this.dropped;
37		}
38	
39		/** Text from absolute offset `from` to the end. Returns how many requested chars were already dropped. */
40		readFrom(from: number): { text: string; lost: number } {
41			const start = Math.max(0, from - this.dropped);
42			const lost = Math.max(0, this.dropped - from);
43			return { text: this.text.slice(start), lost };
44		}
45	
46		/** Whole retained text. */
47		toString(): string {
48			return this.text;
49		}
50	
51		/** Last `n` characters of retained text. */
52		tail(n: number): string {
53			return this.text.length > n ? this.text.slice(this.text.length - n) : this.text;
54		}
55	}
