57	/** Kill a process and its whole (detached) process group. */
58	export function killProcessTree(pid: number, signal: NodeJS.Signals = "SIGKILL"): void {
59		if (process.platform === "win32") {
60			try {
61				spawn("taskkill", ["/F", "/T", "/PID", String(pid)], { stdio: "ignore", detached: true });
62			} catch {
63				// ignore
64			}
65			return;
66		}
67		try {
68			process.kill(-pid, signal);
69		} catch {
70			try {
71				process.kill(pid, signal);
72			} catch {
73				// already dead
74			}
75		}
76	}
77	
78	// Detached children survive the parent unless killed explicitly; kill them when node exits.
79	const liveDetachedPids = new Set<number>();
80	let exitHookInstalled = false;
81	function trackPid(pid: number): void {
82		liveDetachedPids.add(pid);
83		if (!exitHookInstalled) {
84			exitHookInstalled = true;
85			process.once("exit", () => {
86				for (const p of liveDetachedPids) killProcessTree(p);
87			});
88		}
89	}
90	function untrackPid(pid: number): void {
91		liveDetachedPids.delete(pid);
92	}
