94	/** Single-quote a string for POSIX shells. */
95	export function shellQuote(s: string): string {
96		return `'${s.replace(/'/g, `'\\''`)}'`;
97	}
98	
99	/**
100	 * Build the shell script that runs a user command. Everything is on ONE line so bash reports
101	 * errors in the user's command as "line 1" (like Claude Code, which also runs `eval '<cmd>'` on
102	 * the first line of its script):
103	 * - stderr merged into stdout (preserves interleaving order),
104	 * - stdin from /dev/null (spawned with stdio "ignore"),
105	 * - the user command runs through `eval` so syntax errors are reported as a normal non-zero exit,
106	 * - optional: on success, the final `pwd -P` is written to a side-channel file (Claude Code only
107	 *   updates the working directory when the command succeeds).
108	 */
109	export function buildScript(command: string, cwdFile?: string): string {
110		let script = `exec 2>&1; eval ${shellQuote(command)}`;
111		if (cwdFile) script += ` && pwd -P >| ${shellQuote(cwdFile)}`;
112		return script;
113	}
114	
115	export interface SpawnedShell {
116		child: ChildProcess;
117		pid: number | undefined;
118		/** Resolves when the shell process has exited and its output streams are drained (or abandoned). */
119		done: Promise<{ exitCode: number | null; signal: NodeJS.Signals | null }>;
120		kill(): void;
121	}
122	
123	/** Grace period after the shell exits for descendants still holding the output pipes. */
124	const EXIT_STDIO_GRACE_MS = 100;
125	
126	/** Spawn `script` in the user's shell as a detached process group, streaming decoded output to `onData`. */
127	export function spawnShell(script: string, cwd: string, onData: (text: string) => void): SpawnedShell {
128		const { shell, args } = getShellConfig();
129		const child = spawn(shell, [...args, script], {
130			cwd,
131			detached: process.platform !== "win32",
132			env: { ...process.env },
133			stdio: ["ignore", "pipe", "pipe"],
134			windowsHide: true,
135		});
136		const pid = child.pid;
137		if (pid) trackPid(pid);
138	
139		const outDec = new StringDecoder("utf8");
140		const errDec = new StringDecoder("utf8");
141		child.stdout?.on("data", (b: Buffer) => onData(outDec.write(b)));
142		child.stderr?.on("data", (b: Buffer) => onData(errDec.write(b)));
143	
144		const done = new Promise<{ exitCode: number | null; signal: NodeJS.Signals | null }>((resolve, reject) => {
145			let settled = false;
146			let exited = false;
147			let result: { exitCode: number | null; signal: NodeJS.Signals | null } = { exitCode: null, signal: null };
148			let stdoutEnded = !child.stdout;
149			let stderrEnded = !child.stderr;
150			let graceTimer: NodeJS.Timeout | undefined;
151			const finalize = () => {
152				if (settled) return;
153				settled = true;
154				if (graceTimer) clearTimeout(graceTimer);
155				const restOut = outDec.end();
156				const restErr = errDec.end();
157				if (restOut) onData(restOut);
158				if (restErr) onData(restErr);
159				child.stdout?.destroy();
160				child.stderr?.destroy();
161				if (pid) untrackPid(pid);
162				resolve(result);
163			};
164			const maybeFinalize = () => {
165				if (exited && stdoutEnded && stderrEnded) finalize();
166			};
167			child.stdout?.once("end", () => {
168				stdoutEnded = true;
169				maybeFinalize();
170			});
171			child.stderr?.once("end", () => {
172				stderrEnded = true;
173				maybeFinalize();
174			});
175			child.once("exit", (code, signal) => {
176				exited = true;
177				result = { exitCode: code, signal };
178				maybeFinalize();
179				if (!settled) graceTimer = setTimeout(finalize, EXIT_STDIO_GRACE_MS);
180			});
181			child.once("close", (code, signal) => {
182				if (!exited) result = { exitCode: code, signal };
183				exited = true;
184				finalize();
185			});
186			child.once("error", (err) => {
187				if (settled) return;
188				settled = true;
189				if (graceTimer) clearTimeout(graceTimer);
190				if (pid) untrackPid(pid);
191				reject(err);
192			});
193		});
194	
195		return {
196			child,
197			pid,
198			done,
199			kill() {
200				if (pid) killProcessTree(pid);
201				else child.kill("SIGKILL");
202			},
203		};
204	}
