206	/** Claude Code's duration format: "0s", "45s", "2m 5s", "30m" (hideTrailingZeros), "1h 30m". */
207	export function formatClaudeDuration(ms: number, hideTrailingZeros = false): string {
208		if (ms < 60000) {
209			if (ms === 0) return "0s";
210			if (ms < 1) return `${(ms / 1000).toFixed(1)}s`;
211			return `${Math.floor(ms / 1000)}s`;
212		}
213		let d = Math.floor(ms / 86400000);
214		let h = Math.floor((ms % 86400000) / 3600000);
215		let m = Math.floor((ms % 3600000) / 60000);
216		let s = Math.round((ms % 60000) / 1000);
217		if (s === 60) (s = 0), m++;
218		if (m === 60) (m = 0), h++;
219		if (h === 24) (h = 0), d++;
220		const o = hideTrailingZeros;
221		if (d > 0) {
222			if (o && h === 0 && m === 0) return `${d}d`;
223			if (o && m === 0) return `${d}d ${h}h`;
224			return `${d}d ${h}h ${m}m`;
225		}
226		if (h > 0) {
227			if (o && m === 0 && s === 0) return `${h}h`;
228			if (o && s === 0) return `${h}h ${m}m`;
229			return `${h}h ${m}m ${s}s`;
230		}
231		if (m > 0) {
232			if (o && s === 0) return `${m}m`;
233			return `${m}m ${s}s`;
234		}
235		return `${s}s`;
236	}
