21	/** Claude Code's <task-notification> system reminder. */
22	export function formatTaskNotification(n: TaskNotification): string {
23		const lines = ["<task-notification>", `<task-id>${n.taskId}</task-id>`];
24		if (n.toolUseId) lines.push(`<tool-use-id>${n.toolUseId}</tool-use-id>`);
25		if (n.outputFile) lines.push(`<output-file>${n.outputFile}</output-file>`);
26		lines.push(`<status>${n.status}</status>`, `<summary>${n.summary}</summary>`);
27		if (n.note) lines.push(`<note>${n.note}</note>`);
28		if (n.result !== undefined) lines.push(`<result>${n.result}</result>`);
29		if (n.usage) {
30			lines.push(
31				`<usage><subagent_tokens>${n.usage.subagentTokens}</subagent_tokens><tool_uses>${n.usage.toolUses}</tool_uses><duration_ms>${n.usage.durationMs}</duration_ms></usage>`,
32			);
33		}
34		lines.push("</task-notification>");
35		return `<system-reminder>\n${PREAMBLE}\n\n${lines.join("\n")}\n</system-reminder>`;
