224	/** Split a command line into simple commands at unquoted `&&`, `||`, `;`, `|`, `&` and newlines. */
225	export function splitCommands(command: string): string[] {
226		const parts: string[] = [];
227		let cur = "";
228		let quote: "'" | '"' | undefined;
229		for (let i = 0; i < command.length; i++) {
230			const ch = command[i];
231			if (quote) {
232				cur += ch;
233				if (ch === "\\" && quote === '"' && i + 1 < command.length) cur += command[++i];
234				else if (ch === quote) quote = undefined;
235				continue;
236			}
237			if (ch === "\\" && i + 1 < command.length) {
238				cur += ch + command[++i];
239				continue;
240			}
241			if (ch === "'" || ch === '"') {
242				quote = ch;
243				cur += ch;
244				continue;
245			}
246			if (ch === ";" || ch === "|" || ch === "&" || ch === "\n" || ch === "\r") {
247				if ((ch === "|" || ch === "&") && command[i + 1] === ch) i++;
248				if (cur.trim()) parts.push(cur.trim());
249				cur = "";
250				continue;
251			}
252			cur += ch;
253		}
254		if (cur.trim()) parts.push(cur.trim());
255		return parts;
256	}
