260	/** Claude Code's exit-code interpretation: for grep/find/diff/test (and git diff/grep), exit 1 is not an error. */
261	export function isErrorExit(command: string, exitCode: number): boolean {
262		if (exitCode === 0) return false;
263		const last = splitCommands(command).at(-1) ?? command;
264		const words = last.trim().split(/\s+/);
265		let exit1Ok = EXIT_1_OK.has(words[0] ?? "");
266		if (words[0] === "git") {
267			for (let i = 1; i < words.length; i++) {
268				const w = words[i];
269				if (w.startsWith("-")) {
270					if (w === "-C" || w === "-c") i++;
271					continue;
272				}
273				exit1Ok = w === "diff" || w === "grep";
274				break;
275			}
276		}
277		return exit1Ok ? exitCode >= 2 : true;
