336	/** A spawned command whose output is buffered in memory and, once it runs in the background, written to a file. */
337	interface ShellRun {
338		proc: SpawnedShell;
339		output: OutputBuffer;
340		/** First MAX_OUTPUT_CHARS characters of output (what a failed command's result shows). */
341		head: string;
342		/** Output file descriptor once the command became a background task. */
343		fd?: number;
344		onData?: (text: string) => void;
345		done: Promise<{ exitCode: number | null; signal: NodeJS.Signals | null }>;
346	}
