348	function startRun(script: string, cwd: string): ShellRun {
349		const run = { output: new OutputBuffer(), head: "" } as ShellRun;
350		run.proc = spawnShell(script, cwd, (text) => {
351			if (run.fd !== undefined) {
352				try {
353					writeSync(run.fd, text);
354				} catch {
355					// output file gone; keep running
356				}
357			} else {
358				run.output.append(text);
359				if (run.head.length < MAX_OUTPUT_CHARS) run.head += text.slice(0, MAX_OUTPUT_CHARS - run.head.length);
360			}
361			run.onData?.(text);
362		});
363		run.done = run.proc.done.catch((err: Error) => {
364			const text = `${err.message}\n`;
365			if (run.fd !== undefined) {
366				try {
367					writeSync(run.fd, text);
368				} catch {}
369			} else run.output.append(text);
