375	export function registerBash(pi: ExtensionAPI, cc: CCContext): void {
376		const maxTimeout = Math.max(cc.options.bash?.maxTimeoutMs ?? MAX_TIMEOUT_MS, 1);
377		const defaultTimeout = Math.min(cc.options.bash?.defaultTimeoutMs ?? DEFAULT_TIMEOUT_MS, maxTimeout);
