379		/** Persistent shell cwd for this session (undefined until the first command). */
380		let shellCwd: string | undefined;
381		/** Working directory the model was last told about (environment-update reminders). */
382		let announcedCwd: string | undefined;
383		const live = new Set<ShellRun>();
384		let shuttingDown = false;
385	
386		function resolveCwd(baseCwd: string): string {
387			announcedCwd ??= baseCwd;
388			if (!shellCwd || !isDir(shellCwd)) shellCwd = baseCwd;
389			return shellCwd;
390		}
391	
392		function clampTimeout(t: number | undefined, def: number, max: number): number {
393			if (t === undefined || !Number.isFinite(t) || t <= 0) return Math.min(def, max);
394			return Math.min(Math.max(Math.floor(t), 1), max);
395		}
