397		/** "# Environment update" reminder when the shell cwd changed since the model was last told. */
398		function environmentUpdate(): string | undefined {
399			if (!shellCwd || !announcedCwd || shellCwd === announcedCwd) return undefined;
400			const lines = [` - Primary working directory: ${shellCwd} (was ${announcedCwd})`];
401			const wasGit = isGitRepo(announcedCwd);
402			const isGit = isGitRepo(shellCwd);
403			if (wasGit !== isGit) lines.push(` - Is a git repository: ${isGit} (was ${wasGit})`);
404			announcedCwd = shellCwd;
405			return `<system-reminder>\n# Environment update\n${lines.join("\n")}\n</system-reminder>`;
406		}
