408		/** After a formatter/fixer, name previously read files it modified (they must be re-read before editing). */
409		function staleReadHint(command: string, startedAt: number): string | undefined {
410			if (!FORMATTER_RE.test(command)) return undefined;
411			const changed = cc.fileState.changedSinceRead().filter((p) => {
412				try {
413					return statSync(p).mtimeMs > startedAt;
414				} catch {
415					return false;
416				}
417			});
418			if (changed.length === 0) return undefined;
419			const base = shellCwd ?? process.cwd();
420			const names = changed.slice(0, 5).map((p) => (isWithin(p, base) ? relative(base, p) || p : p));
421			const more = changed.length > 5 ? ` and ${changed.length - 5} more` : "";
422			return `[This command modified ${changed.length} ${changed.length === 1 ? "file" : "files"} you've previously read: ${names.join(", ")}${more}. Call Read before editing.]`;
423		}
