425		/** Turn a running command into a background task (output file, TaskStop, completion notification). */
426		function adoptAsTask(run: ShellRun, opts: { command: string; description?: string; toolCallId: string; limitMs: number; cleanup?: () => void }): BackgroundTask {
427			const id = newTaskId("local_bash");
428			const outputFile = cc.tasks.outputPath(id);
429			run.fd = openSync(outputFile, "w");
430			const buffered = run.output.toString();
431			if (buffered) writeSync(run.fd, buffered);
432			let stopped = false;
433			let deadlineHit = false;
434			let finish!: () => void;
435			const finished = new Promise<void>((r) => (finish = r));
436			const task = cc.tasks.add({
437				id,
438				type: "local_bash",
439				label: opts.command,
440				status: "running",
441				outputFile,
442				toolUseId: opts.toolCallId,
443				async stop() {
444					stopped = true;
445					run.proc.kill();
446					await finished;
447				},
448			});
449			live.add(run);
450			cc.emit({ type: "background_shell_started", shellId: id, command: opts.command });
451			const deadline = setTimeout(() => {
452				deadlineHit = true;
453				run.proc.kill();
454			}, opts.limitMs);
455			deadline.unref?.();
456	
457			void run.done.then((exit) => {
458				clearTimeout(deadline);
459				live.delete(run);
460				opts.cleanup?.();
461				const killed = stopped || deadlineHit || shuttingDown;
462				const code = exitCodeOf(exit);
463				try {
464					writeSync(run.fd!, killed ? "\n[killed]\n" : `\n[exited with code ${code}]\n`);
465					closeSync(run.fd!);
466				} catch {
467					// ignore
468				}
469				task.status = killed ? "killed" : code === 0 ? "completed" : "failed";
470				cc.emit({ type: "background_shell_exited", shellId: id, exitCode: exit.exitCode, signal: exit.signal });
471				finish();
472				if (stopped || shuttingDown) return; // stopped on purpose: no notification
473				const label = `Background command "${opts.description || opts.command}"`;
474				const summary = deadlineHit
475					? `${label} was stopped after reaching its background time limit`
476					: code === 0
477						? `${label} completed (exit code ${code})`
478						: `${label} failed with exit code ${code}`;
479				cc.notifications.enqueue(
480					formatTaskNotification({
481						taskId: id,
482						toolUseId: opts.toolCallId,
483						outputFile,
484						status: task.status as "completed" | "failed" | "killed",
485						summary: escapeXml(summary),
486						note: deadlineHit ? escapeXml(DEADLINE_NOTE) : undefined,
487					}),
488				);
489			});
490			return task;
491		}
