493		// ---------------------------------------------------------------- foreground
494		async function runForeground(
495			params: { command: string; description?: string; timeout?: number },
496			toolCallId: string,
497			baseCwd: string,
498			signal: AbortSignal | undefined,
499			onUpdate: ((r: AgentToolResult<BashDetails>) => void) | undefined,
500		): Promise<AgentToolResult<BashDetails>> {
501			const { command } = params;
502			if (signal?.aborted) throw new Error(ABORTED);
503			const timeoutMs = clampTimeout(params.timeout, defaultTimeout, maxTimeout);
504			const cwd = resolveCwd(baseCwd);
505			const cwdFile = join(tmpdir(), `pi-cc-cwd-${process.pid}-${randomBytes(6).toString("hex")}`);
506			const removeCwdFile = () => {
507				try {
508					rmSync(cwdFile, { force: true });
509				} catch {
510					// ignore
511				}
512			};
513			const startedAt = Math.floor(Date.now() / 1000) * 1000;
514			const run = startRun(buildScript(command, cwdFile), cwd);
515			live.add(run);
516	
517			let updateTimer: NodeJS.Timeout | undefined;
518			let lastUpdate = 0;
519			const flushUpdate = () => {
520				updateTimer = undefined;
521				lastUpdate = Date.now();
522				try {
523					onUpdate?.({ content: [{ type: "text", text: run.output.tail(UPDATE_TAIL_CHARS) }], details: { cwd } });
524				} catch {
525					// progress consumers must not break execution
526				}
527			};
528			if (onUpdate) {
529				run.onData = () => {
530					if (run.fd !== undefined || updateTimer) return;
531					const delay = UPDATE_THROTTLE_MS - (Date.now() - lastUpdate);
532					if (delay <= 0) flushUpdate();
533					else updateTimer = setTimeout(flushUpdate, delay);
534				};
535			}
536	
537			let onAbort: (() => void) | undefined;
538			let timer: NodeJS.Timeout | undefined;
539			const outcome = await new Promise<"exit" | "timeout" | "abort">((resolve) => {
540				run.done.then(() => resolve("exit"));
541				timer = setTimeout(() => resolve("timeout"), timeoutMs);
542				onAbort = () => resolve("abort");
543				signal?.addEventListener("abort", onAbort, { once: true });
544			});
545			clearTimeout(timer);
546			if (onAbort) signal?.removeEventListener("abort", onAbort);
547			if (updateTimer) clearTimeout(updateTimer);
548			run.onData = undefined;
549			live.delete(run);
550	
551			if (outcome === "timeout" && canAutoBackground(command)) {
552				// Claude Code does not kill a command at its timeout: it keeps running as a background task.
553				const task = adoptAsTask(run, {
554					command,
555					description: params.description,
556					toolCallId,
557					limitMs: BACKGROUND_DEFAULT_TIMEOUT_MS,
558					cleanup: removeCwdFile,
559				});
560				const text =
561					`Command did not complete within its ${Math.max(1, Math.round(timeoutMs / 1000))}s timeout and was moved to the background (ID: ${task.id}). ` +
562					`Output is being written to: ${task.outputFile}. You will be notified when it completes. ` +
563					`If it is still running after ${formatClaudeDuration(BACKGROUND_DEFAULT_TIMEOUT_MS, true)} in the background, it will be stopped and you will be notified. ` +
564					`To check interim output, use Read on that file path.`;
565				return textResult<BashDetails>(text, { backgroundTaskId: task.id, outputFile: task.outputFile, timedOut: true, cwd });
566			}
567	
568			if (outcome !== "exit") run.proc.kill();
569			const exit = await run.done;
570			let newCwd: string | undefined;
571			try {
572				if (existsSync(cwdFile)) newCwd = readFileSync(cwdFile, "utf8").trim() || undefined;
573			} catch {
574				// ignore
575			}
576			removeCwdFile();
577	
578			if (outcome === "abort") {
579				throw new Error([run.output.toString().trim(), ABORTED].filter(Boolean).join("\n"));
580			}
581			if (outcome === "timeout") {
582				const text = [`Exit code ${TIMEOUT_EXIT_CODE}`, `Command timed out after ${formatClaudeDuration(timeoutMs)}`, run.head].join("\n").trim();
583				throw new Error(truncateError(text));
584			}
585	
586			const exitCode = exitCodeOf(exit);
587			if (isErrorExit(command, exitCode)) {
588				throw new Error(truncateError([`Exit code ${exitCode}`, run.head].filter(Boolean).join("\n").trim()));
589			}
590	
591			let resetNote: string | undefined;
592			if (newCwd && isDir(newCwd)) {
593				if (isWithin(newCwd, baseCwd) || isWithin(newCwd, realpathOr(baseCwd))) shellCwd = newCwd;
594				else {
595					// Claude Code keeps the shell inside the project: leaving it resets to the original directory.
596					shellCwd = baseCwd;
597					resetNote = `Shell cwd was reset to ${baseCwd}`;
598				}
599			}
600			let text = [run.output.toString().trim(), resetNote, staleReadHint(command, startedAt)].filter(Boolean).join("\n") || NO_OUTPUT;
601			const env = environmentUpdate();
602			if (env) text += `\n\n${env}`;
603			return textResult<BashDetails>(text, { exitCode, signal: exit.signal, cwd: shellCwd });
604		}
605	
606		// ---------------------------------------------------------------- background
607		function startBackground(params: { command: string; description?: string; timeout?: number }, toolCallId: string, baseCwd: string): AgentToolResult<BashDetails> {
608			const cwd = resolveCwd(baseCwd);
609			const run = startRun(buildScript(params.command), cwd);
610			const task = adoptAsTask(run, {
611				command: params.command,
612				description: params.description,
613				toolCallId,
614				limitMs: clampTimeout(params.timeout, BACKGROUND_DEFAULT_TIMEOUT_MS, BACKGROUND_MAX_TIMEOUT_MS),
615			});
616			let text =
617				`Command running in background with ID: ${task.id}. Output is being written to: ${task.outputFile}. ` +
618				`You will be notified when it completes. To check interim output, use Read on that file path.`;
619			if (changesDirectory(params.command)) text += `\nSession cwd remains ${cwd}; ${BG_CWD_NOTE}`;
620			return textResult<BashDetails>(text, { backgroundTaskId: task.id, outputFile: task.outputFile, cwd });
621		}
