623		pi.registerTool({
624			name: "Bash",
625			label: "Bash",
626			description: bashDescription(defaultTimeout, maxTimeout),
627			promptSnippet: "Execute shell commands (persistent working directory, optional background execution)",
628			parameters: Type.Object(
629				{
630					command: Type.String({ description: "The command to execute" }),
631					timeout: Type.Optional(Type.Number({ description: `Optional timeout in milliseconds (max ${maxTimeout} for a foreground command)` })),
632					description: Type.Optional(Type.String({ description: DESCRIPTION_PARAM })),
