644			prepareArguments: claudeInputValidator<BashInput>("Bash", BashSpec) as any,
645			async execute(toolCallId, rawParams, signal, onUpdate, ctx) {
646				const input = rawParams as BashInput;
647				const timeout = input.timeout === undefined || input.timeout === null || input.timeout === "" ? undefined : Number(input.timeout);
