67	async function waitFor(cond: () => boolean, timeoutMs = 5000): Promise<void> {
68		const start = Date.now();
69		while (!cond()) {
70			if (Date.now() - start > timeoutMs) throw new Error("waitFor timed out");
71			await new Promise((r) => setTimeout(r, 20));
72		}
73	}
