36	/** Claude Code's size formatter (1024-based, trailing ".0" dropped). */
37	export function formatSize(bytes: number): string {
38		const kb = bytes / 1024;
39		if (kb < 1) return `${bytes} bytes`;
40		if (kb < 1024) return `${kb.toFixed(1).replace(/\.0$/, "")}KB`;
41		const mb = kb / 1024;
42		if (mb < 1024) return `${mb.toFixed(1).replace(/\.0$/, "")}MB`;
43		return `${(mb / 1024).toFixed(1).replace(/\.0$/, "")}GB`;
44	}
