51	/** First `max` chars, cut at the last line break when that keeps more than half of the budget. */
52	export function makePreview(text: string, max: number): { preview: string; truncated: boolean } {
53		if (text.length <= max) return { preview: text, truncated: false };
54		const nl = text.slice(0, max).lastIndexOf("\n");
55		return { preview: text.slice(0, nl > max * 0.5 ? nl : max), truncated: true };
56	}
