70	/** Persistence threshold for a tool (characters of text; results strictly larger are spilled). */
71	export function spillThreshold(toolName: string, maxChars?: number): number {
72		if (maxChars !== undefined) return Math.max(1, maxChars);
73		return Math.min(TOOL_SPILL_THRESHOLDS[toolName] ?? SPILL_THRESHOLD_CEILING, SPILL_THRESHOLD_CEILING);
74	}
