1	import type { Model } from "@earendil-works/pi-ai";
2	import type { ModelRegistry } from "@earendil-works/pi-coding-agent";
3	
4	/** Model aliases accepted by the Agent tool's `model` parameter (Claude Code's enum). */
5	export const MODEL_ALIASES = ["sonnet", "opus", "haiku", "fable"] as const;
6	
7	export function isModelAlias(s: string): boolean {
8		return (MODEL_ALIASES as readonly string[]).includes(s.toLowerCase());
9	}
10	
11	function safe<T>(fn: () => T, fallback: T): T {
12		try {
13			return fn();
14		} catch {
15			return fallback;
16		}
17	}
18	
19	function hasAuth(registry: ModelRegistry, m: Model<any>): boolean {
20		return safe(() => registry.hasConfiguredAuth(m), false);
21	}
22	
23	/** Prefer: same provider as parent, then configured auth, then undated ids, then highest (latest-looking) id. */
24	function pickBest(candidates: Model<any>[], registry: ModelRegistry, parent: Model<any> | undefined): Model<any> | undefined {
25		if (candidates.length === 0) return undefined;
26		const score = (m: Model<any>) => (parent && m.provider === parent.provider ? 2 : 0) + (hasAuth(registry, m) ? 1 : 0);
27		const dated = (m: Model<any>) => (/\d{8}/.test(m.id) ? 1 : 0); // prefer undated aliases like "claude-haiku-4-5"
28		return [...candidates].sort((a, b) => score(b) - score(a) || dated(a) - dated(b) || b.id.localeCompare(a.id))[0];
29	}
30	
31	export type ModelResolution =
32		| { ok: true; model: Model<any> | undefined; note?: string }
33		| { ok: false; error: string };
34	
35	/**
36	 * Resolve a model spec for a subagent.
37	 * - undefined / "inherit" → parent model
38	 * - a pi Model object → used as-is
39	 * - "sonnet" | "opus" | "haiku" | "fable" → best available registry model whose id contains the alias
40	 *   (preferring the parent's provider); falls back to the parent model when none is found
41	 * - "provider/model-id" or bare "model-id" → registry lookup (exact id match; the parent model
42	 *   itself also matches). Unknown ids → error (strict) or parent model with a note (non-strict).
43	 */
44	export function resolveSubagentModel(
45		spec: Model<any> | string | undefined,
46		registry: ModelRegistry | undefined,
47		parent: Model<any> | undefined,
48		opts: { strict: boolean },
49	): ModelResolution {
50		if (spec === undefined) return { ok: true, model: parent };
51		if (typeof spec !== "string") return { ok: true, model: spec };
52		const s = spec.trim();
53		if (!s || s === "inherit") return { ok: true, model: parent };
54	
55		if (parent && (s === parent.id || s === `${parent.provider}/${parent.id}`)) return { ok: true, model: parent };
56	
57		const all: Model<any>[] = registry ? safe(() => registry.getAll(), [] as Model<any>[]) : [];
58	
59		if (isModelAlias(s)) {
60			const alias = s.toLowerCase();
61			if (parent && parent.id.toLowerCase().includes(alias)) return { ok: true, model: parent };
62			const best = pickBest(
63				all.filter((m) => m.id.toLowerCase().includes(alias) && hasAuth(registry!, m)),
64				registry!,
65				parent,
66			);
67			if (best) return { ok: true, model: best };
68			return { ok: true, model: parent, note: `No available model matches alias "${s}"; using the parent model.` };
69		}
70	
71		let found: Model<any> | undefined;
72		const slash = s.indexOf("/");
73		if (slash > 0 && registry) {
74			found = safe(() => registry.find(s.slice(0, slash), s.slice(slash + 1)), undefined);
75		}
76		if (!found) found = pickBest(all.filter((m) => m.id === s), registry!, parent);
77		if (found) return { ok: true, model: found };
78	
79		if (opts.strict) {
80			return { ok: false, error: `Unknown model "${s}". Use "sonnet", "opus", "haiku", "fable", a model id, or "provider/model-id", or omit the model parameter to inherit the parent model.` };
81		}
82		return { ok: true, model: parent, note: `Unknown model "${s}"; using the parent model.` };
83	}
