174	};
175	
176	/** Parse a `tools` frontmatter value: "A, B", ["A","B"], "*" (all). */
177	export function parseToolList(value: unknown): string[] | undefined {
178		let items: string[];
179		if (Array.isArray(value)) items = value.map((v) => String(v));
180		else if (typeof value === "string") items = value.split(",");
181		else return undefined;
182		items = items.map((s) => s.trim()).filter(Boolean);
183		if (items.length === 0 || items.includes("*")) return undefined;
184		return items;
185	}
186	
187	function parseEffort(value: unknown): AgentEffort | undefined {
188		return typeof value === "string" && (AGENT_EFFORTS as readonly string[]).includes(value.trim()) ? (value.trim() as AgentEffort) : undefined;
189	}
190	
191	/** Parse one markdown agent file. Returns undefined when the file is not a usable agent definition. */
192	export function parseAgentMarkdown(content: string, filePath: string, source: AgentSource): SubagentDefinition | undefined {
193		let frontmatter: Record<string, unknown>;
194		let body: string;
195		try {
196			({ frontmatter, body } = parseFrontmatter<Record<string, unknown>>(content));
197		} catch {
198			return undefined;
199		}
200		const name = typeof frontmatter.name === "string" && frontmatter.name.trim() ? frontmatter.name.trim() : basename(filePath, ".md");
201		const description =
202			typeof frontmatter.description === "string" && frontmatter.description.trim()
203				? frontmatter.description.trim()
204				: `Custom agent "${name}"`;
205		const modelRaw = typeof frontmatter.model === "string" ? frontmatter.model.trim() : undefined;
206		const background = frontmatter.background === true || frontmatter.background === "true";
207		return {
208			name,
209			description,
210			prompt: body.trim(),
211			tools: parseToolList(frontmatter.tools),
212			disallowedTools: parseToolList(frontmatter.disallowedTools),
213			model: modelRaw && modelRaw !== "inherit" ? modelRaw : undefined,
214			effort: parseEffort(frontmatter.effort),
215			...(background ? { background } : {}),
216			source,
217			filePath,
218		};
219	}
220	
221	export function loadAgentsFromDir(dir: string, source: AgentSource): SubagentDefinition[] {
222		if (!existsSync(dir)) return [];
223		let entries: string[];
224		try {
225			entries = readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
226		} catch {
227			return [];
228		}
229		const out: SubagentDefinition[] = [];
230		for (const file of entries) {
231			const p = join(dir, file);
232			try {
233				if (!statSync(p).isFile()) continue;
234				const def = parseAgentMarkdown(readFileSync(p, "utf8"), p, source);
235				if (def) out.push(def);
236			} catch {
237				// unreadable file: skip
238			}
239		}
240		return out;
241	}
242	
243	function fromOptions(name: string, def: AgentDefinition): SubagentDefinition {
244		return {
245			name,
246			description: def.description,
247			prompt: def.prompt,
248			tools: def.tools && def.tools.length > 0 && !def.tools.includes("*") ? [...def.tools] : undefined,
249			model: def.model === "inherit" ? undefined : def.model,
250			source: "options",
251		};
252	}
253	
254	export interface LoadAgentsOptions {
255		cwd: string;
256		agents?: Record<string, AgentDefinition>;
257		loadAgentsFromDisk?: boolean;
258		/** Override for tests. Default: os.homedir(). */
259		homeDir?: string;
260	}
261	
262	/**
263	 * Resolve all agent definitions. Precedence (later wins):
264	 * built-in < ~/.claude/agents < <cwd>/.claude/agents < options.agents.
265	 */
266	export function loadAgentDefinitions(opts: LoadAgentsOptions): Map<string, SubagentDefinition> {
267		const map = new Map<string, SubagentDefinition>();
268		for (const def of Object.values(BUILT_IN_AGENTS)) map.set(def.name, def);
269		if (opts.loadAgentsFromDisk !== false) {
270			const home = opts.homeDir ?? homedir();
271			const userDir = join(home, ".claude", "agents");
272			const projectDir = join(opts.cwd, ".claude", "agents");
273			for (const def of loadAgentsFromDir(userDir, "user")) map.set(def.name, def);
274			if (projectDir !== userDir) for (const def of loadAgentsFromDir(projectDir, "project")) map.set(def.name, def);
275		}
276		for (const [name, def] of Object.entries(opts.agents ?? {})) map.set(name, fromOptions(name, def));
277		return map;
278	}
279	
280	/** True when the definition lets the child use `name` (before subagent-wide exclusions). */
281	export function agentAllowsTool(def: SubagentDefinition, name: string): boolean {
282		if (def.disallowedTools?.includes(name)) return false;
283		return !def.tools || def.tools.includes("*") || def.tools.includes(name);
284	}
285	
286	/** Claude Code's "(Tools: ...)" label. */
287	export function toolsLabel(def: SubagentDefinition): string {
288		const tools = def.tools ?? [];
289		const disallowed = def.disallowedTools ?? [];
290		if (tools.length > 0 && disallowed.length > 0) {
291			const left = tools.filter((t) => !disallowed.includes(t));
292			return left.length > 0 ? left.join(", ") : "None";
293		}
294		if (tools.length > 0) return tools.join(", ");
295		if (disallowed.length > 0) return `All tools except ${disallowed.join(", ")}`;
296		return "All tools";
297	}
298	
299	/** Agent names sorted the way Claude Code lists them (case-insensitive). */
300	export function sortedAgentNames(defs: Map<string, SubagentDefinition>): string[] {
301		return [...defs.keys()].sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()) || a.localeCompare(b));
302	}
303	
304	/** "- name: description (Tools: ...)" lines, as in Claude Code's agent listing. */
305	export function formatAgentList(defs: Map<string, SubagentDefinition>): string {
306		return sortedAgentNames(defs)
307			.map((n) => defs.get(n)!)
308			.map((d) => `- ${d.name}: ${d.description} (Tools: ${toolsLabel(d)})`)
309			.join("\n");
310	}
311	
312	/** The "Available agent types" system reminder Claude Code injects into the conversation. */
313	export function formatAgentListingReminder(defs: Map<string, SubagentDefinition>): string {
314		return `Available agent types for the Agent tool:\n${formatAgentList(defs)}\n\nWhen you launch multiple agents for independent work, send them in a single message with multiple tool uses so they run concurrently.`;
315	}
