1	import { execFileSync } from "node:child_process";
2	import { existsSync, mkdirSync } from "node:fs";
3	import { join, relative } from "node:path";
4	import type { WorktreeInfo } from "./prompt.js";
5	
6	/** A temporary git worktree an `isolation: "worktree"` agent works in. */
7	export interface AgentWorktree {
8		gitRoot: string;
9		path: string;
10		branch: string;
11		headCommit: string;
12		/** The agent's cwd inside the worktree (same relative location as the parent's cwd). */
13		cwd: string;
14	}
15	
16	function git(cwd: string, args: string[]): string {
17		return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
18	}
19	
20	/** Root of the git checkout containing `cwd`, or undefined when it is not inside one. */
21	export function gitRootOf(cwd: string): string | undefined {
22		try {
23			return git(cwd, ["rev-parse", "--show-toplevel"]) || undefined;
24		} catch {
25			return undefined;
26		}
27	}
28	
29	/** Create `<repo>/.claude/worktrees/agent-<id>` on a new branch `worktree-agent-<id>` at HEAD. */
30	export function createAgentWorktree(cwd: string, agentId: string): AgentWorktree {
31		const gitRoot = gitRootOf(cwd);
32		if (!gitRoot) throw new Error(`Cannot create an agent worktree: ${cwd} is not inside a git repository. Omit isolation to run the agent in the current directory.`);
33		let headCommit: string;
34		try {
35			headCommit = git(gitRoot, ["rev-parse", "HEAD"]);
36		} catch {
37			throw new Error("Cannot create an agent worktree: the repository has no commits yet.");
38		}
39		const name = `agent-${agentId.replace(/^a/, "").slice(0, 8)}`;
40		const dir = join(gitRoot, ".claude", "worktrees");
41		mkdirSync(dir, { recursive: true });
42		const path = join(dir, name);
43		const branch = `worktree-${name}`;
44		try {
45			git(gitRoot, ["worktree", "add", "-b", branch, path, headCommit]);
46		} catch (err) {
47			const msg = (err as { stderr?: string }).stderr?.toString().trim() || (err as Error).message;
48			throw new Error(`Cannot create an agent worktree: ${msg}`);
49		}
50		const rel = relative(gitRoot, cwd);
51		const sub = rel && !rel.startsWith("..") ? join(path, rel) : path;
52		return { gitRoot, path, branch, headCommit, cwd: existsSync(sub) ? sub : path };
53	}
54	
55	/**
56	 * Remove the worktree (and its branch) when the agent left it untouched; otherwise keep it and
57	 * return its path and branch for the result.
58	 */
59	export function finishAgentWorktree(w: AgentWorktree): WorktreeInfo | undefined {
60		let dirty = true;
61		try {
62			const status = git(w.path, ["status", "--porcelain"]);
63			const head = git(w.path, ["rev-parse", "HEAD"]);
64			dirty = status !== "" || head !== w.headCommit;
65		} catch {
66			dirty = true;
67		}
68		if (dirty) return { worktreePath: w.path, worktreeBranch: w.branch };
69		try {
70			git(w.gitRoot, ["worktree", "remove", "--force", w.path]);
71			git(w.gitRoot, ["branch", "-D", w.branch]);
72		} catch {
73			return { worktreePath: w.path, worktreeBranch: w.branch };
74		}
75		return undefined;
76	}
