211	const FIELDS: Array<{ name: string; type: "string" | "boolean"; required?: boolean; values?: readonly string[] }> = [
212		{ name: "description", type: "string", required: true },
213		{ name: "prompt", type: "string", required: true },
214		{ name: "subagent_type", type: "string" },
215		{ name: "model", type: "string", values: MODEL_OPTIONS },
216		{ name: "effort", type: "string", values: EFFORT_OPTIONS },
217		{ name: "run_in_background", type: "boolean" },
218		{ name: "isolation", type: "string", values: ISOLATION_OPTIONS },
219	];
220	
221	function typeName(v: unknown): string {
222		if (v === null) return "null";
223		if (Array.isArray(v)) return "array";
224		return typeof v;
225	}
226	
227	function zodIssue(i: Issue): Record<string, unknown> {
228		if (i.kind === "enum") {
229			return { code: "invalid_value", values: i.values, path: [i.path], message: `Invalid option: expected one of ${i.values.map((v) => JSON.stringify(v)).join("|")}` };
230		}
231		const received = i.kind === "missing" ? "undefined" : i.received;
232		return { expected: i.expected, code: "invalid_type", path: [i.path], message: `Invalid input: expected ${i.expected}, received ${received}` };
233	}
234	
235	function humanIssue(i: Issue): string {
236		if (i.kind === "missing") return `The required parameter \`${i.path}\` is missing`;
237		if (i.kind === "type") return `The parameter \`${i.path}\` type is expected as \`${i.expected}\` but provided as \`${i.received}\``;
238		return `The parameter \`${i.path}\` is invalid`;
239	}
240	
241	/**
242	 * Validate raw Agent tool arguments the way Claude Code reports schema errors. Returns an error
243	 * message, or undefined when valid. Unknown extra parameters (e.g. `name`, `team_name`, `mode`)
244	 * are accepted and ignored.
245	 */
246	export function validateAgentInput(args: unknown): string | undefined {
247		const a = (args && typeof args === "object" ? args : {}) as Record<string, unknown>;
248		const issues: Issue[] = [];
249		for (const f of FIELDS) {
250			const v = a[f.name];
251			if (v === undefined) {
252				if (f.required) issues.push({ kind: "missing", path: f.name, expected: f.type });
253			} else if (typeof v !== f.type) {
254				issues.push({ kind: "type", path: f.name, expected: f.type, received: typeName(v) });
255			} else if (f.values && !f.values.includes(v as string)) {
256				issues.push({ kind: "enum", path: f.name, values: f.values });
257			}
258		}
259		if (issues.length === 0) return undefined;
260		if (issues.some((i) => i.kind === "enum")) return `InputValidationError: ${JSON.stringify(issues.map(zodIssue), null, 2)}`;
261		const plural = issues.length > 1;
262		return `InputValidationError: Agent failed due to the following ${plural ? "issues" : "issue"}:\n${issues.map(humanIssue).join("\n")}`;
263	}
