126	function modelLabel(m: Model<any> | undefined): string | undefined {
127		return m ? `${m.provider}/${m.id}` : undefined;
128	}
129	
130	function isAssistant(m: unknown): m is AssistantMessage {
131		return !!m && typeof m === "object" && (m as { role?: string }).role === "assistant";
132	}
133	
134	function assistantText(m: AssistantMessage | undefined): string {
135		if (!m) return "";
136		return m.content
137			.filter((c): c is { type: "text"; text: string } => c.type === "text" && !!c.text)
138			.map((c) => c.text)
139			.join("\n");
140	}
141	
142	function messageTokens(m: AssistantMessage): number {
143		const u = m.usage;
144		if (!u) return 0;
145		return u.totalTokens ?? (u.input ?? 0) + (u.output ?? 0) + (u.cacheRead ?? 0) + (u.cacheWrite ?? 0);
146	}
147	
148	/** Sum usage over the assistant messages of one run. */
149	export function computeSubagentUsage(messages: readonly unknown[], durationMs: number): SubagentUsage {
150		const u: SubagentUsage = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, costTotal: 0, turns: 0, toolUses: 0, durationMs };
151		for (const m of messages) {
152			if (!isAssistant(m)) continue;
153			u.turns++;
154			u.toolUses += m.content.filter((c) => c.type === "toolCall").length;
155			const usage = m.usage;
156			if (!usage) continue;
157			u.input += usage.input ?? 0;
158			u.output += usage.output ?? 0;
159			u.cacheRead += usage.cacheRead ?? 0;
160			u.cacheWrite += usage.cacheWrite ?? 0;
161			u.totalTokens += messageTokens(m);
162			u.costTotal += usage.cost?.total ?? 0;
163		}
164		return u;
165	}
166	
167	/** Claude Code reports a subagent's tokens as the context size of its last model call. */
168	function lastCallTokens(messages: readonly unknown[]): number {
169		const last = [...messages].reverse().find((m) => isAssistant(m) && !!m.usage) as AssistantMessage | undefined;
170		return last ? messageTokens(last) : 0;
171	}
