173	/**
174	 * A sibling model of the parent's provider (e.g. the "opus" alias) is reached through the same
175	 * endpoint as the parent model, so a parent configured with a custom baseUrl/proxy keeps using it.
176	 */
177	function sameEndpoint(model: Model<any> | undefined, parent: Model<any> | undefined): Model<any> | undefined {
178		if (!model || !parent || model === parent || model.provider !== parent.provider) return model;
179		if (model.baseUrl === parent.baseUrl && model.headers === parent.headers) return model;
180		return { ...model, baseUrl: parent.baseUrl, ...(parent.headers ? { headers: parent.headers } : {}) };
181	}
