183	/**
184	 * Rewrites pi's "Tool X not found" result for a call to an unavailable tool into Claude Code's
185	 * wording. Installed in every subagent session and in the session that owns the Agent tool.
186	 */
187	export function registerUnknownToolErrors(pi: ExtensionAPI): void {
188		pi.on("message_end", (event) => {
189			const m = event.message as { role?: string; isError?: boolean; toolName?: string; content?: unknown };
190			if (m?.role !== "toolResult" || !m.isError || !Array.isArray(m.content) || m.content.length !== 1) return undefined;
191			const block = m.content[0] as { type?: string; text?: string };
192			const match = block?.type === "text" ? /^Tool (.+) not found$/.exec(block.text ?? "") : null;
193			if (!match || (m.toolName && match[1] !== m.toolName)) return undefined;
194			return { message: { ...(event.message as object), content: [{ type: "text", text: noSuchToolText(match[1]) }] } as typeof event.message };
195		});
196	}
