237	/** Register Claude Code's Agent tool (subagents). */
238	export function registerAgent(pi: ExtensionAPI, cc: CCContext, internal: RegisterAgentInternalOptions = {}): void {
239		const runs = new Map<string, AgentRun>();
240		let shuttingDown = false;
241		let lastListing: string | undefined;
242		const isSubagent = cc.options.isSubagent === true;
243	
244		const loadDefs = (cwd: string) =>
245			loadAgentDefinitions({
246				cwd,
247				agents: cc.options.agents,
248				loadAgentsFromDisk: cc.options.loadAgentsFromDisk,
249				homeDir: subagentInternals.homeDir,
250			});
251	
252		const emit = (event: ClaudeCodeHostEvent) => cc.emit(event);
253	
254		function resolveAgentType(defs: Map<string, SubagentDefinition>, requested: string | undefined): SubagentDefinition {
255			const names = sortedAgentNames(defs);
256			if (!requested) {
257				const def = defs.get(DEFAULT_AGENT_TYPE);
258				if (!def) {
259					const avail = internal.inFork ? names : [FORK_AGENT_TYPE, ...names];
260					throw new Error(`subagent_type is required: the general-purpose agent is not available in this session. Available agents: ${avail.join(", ") || "none"}`);
261				}
262				return def;
263			}
264			const exact = defs.get(requested);
265			if (exact) return exact;
266			// Claude Code matches names ignoring case, whitespace, dashes and underscores
267			const norm = (s: string) => s.normalize("NFKC").toLowerCase().replace(/[\p{White_Space}\p{Pd}_]+/gu, "");
268			const matches = names.filter((n) => norm(n) === norm(requested));
269			if (matches.length === 1) return defs.get(matches[0])!;
270			if (matches.length > 1) throw new Error(`Agent type '${requested}' is ambiguous: ${matches.join(", ")}. Use the exact name: ${matches.join(" or ")}`);
271			throw new Error(`Agent type '${requested}' not found. Available agents: ${names.join(", ") || "none"}`);
272		}
