274		async function disposeSession(session: AgentSession): Promise<void> {
275			try {
276				const runner = session.extensionRunner;
277				if (runner?.hasHandlers("session_shutdown")) await runner.emit({ type: "session_shutdown", reason: "quit" });
278			} catch {
279				// ignore child extension errors during teardown
280			}
281			try {
282				session.dispose();
283			} catch {
284				// ignore
285			}
286		}
