288		/** Seed a fork's session with the parent's conversation plus synthetic results for the pending tool calls. */
289		function forkSessionManager(ctx: ExtensionContext, cwd: string): SessionManager {
290			const sm = SessionManager.inMemory(cwd);
291			let messages: any[] = [];
292			try {
293				messages = [...((ctx.sessionManager as any).buildSessionProjection?.().messages ?? [])];
294			} catch {
295				messages = [];
296			}
297			messages = messages.filter((m) => m && m.role !== "system");
298			for (const m of messages) {
299				try {
300					sm.appendMessage(m);
301				} catch {
302					// not a message pi can replay; skip it
303				}
304			}
305			const last = messages.at(-1);
306			if (isAssistant(last)) {
307				for (const c of last.content) {
308					if (c.type !== "toolCall") continue;
309					sm.appendMessage({ role: "toolResult", toolCallId: c.id, toolName: c.name, content: [{ type: "text", text: FORK_STARTED }], isError: false, timestamp: Date.now() } as any);
310				}
311			}
312			return sm;
313		}
