315		async function createChildSession(
316			ctx: ExtensionContext,
317			def: SubagentDefinition,
318			model: Model<any> | undefined,
319			opts: { agentId: string; toolCallId: string; background: boolean; cwd: string; effort?: AgentEffort; fork: boolean },
320		): Promise<AgentSession> {
321			let parentActive: Set<string> | undefined;
322			if (opts.fork) {
323				try {
324					parentActive = new Set(pi.getActiveTools());
325				} catch {
326					parentActive = undefined;
327				}
328			}
329			const allowed = (name: string): boolean => {
330				if (parentActive) return parentActive.has(name);
331				if (SUBAGENT_EXCLUDED_TOOLS.includes(name)) return false;
332				if (opts.background && BACKGROUND_EXCLUDED_TOOLS.includes(name)) return false;
333				return agentAllowsTool(def, name);
334			};
335			const deferredTools = opts.fork ? cc.options.deferredTools : (cc.options.deferredTools ?? []).filter(allowed);
336	
337			let thinkingLevel: ReturnType<ExtensionAPI["getThinkingLevel"]> | undefined = opts.effort;
338			if (!thinkingLevel) {
339				try {
340					thinkingLevel = pi.getThinkingLevel();
341				} catch {
342					thinkingLevel = undefined;
343				}
344			}
345	
346			const childOptions: ClaudeCodeToolsOptions = {
347				...cc.options,
348				isSubagent: true,
349				onAskUserQuestion: undefined,
350				sharedTaskStore: cc.taskStore,
351				deferredTools,
352				// child host events (todos, background shells, ...) are forwarded wrapped in subagent_event,
353				// so they never clobber the parent's state in the host UI
354				onEvent: (event) => emit({ type: "subagent_event", agentId: opts.agentId, parentToolCallId: opts.toolCallId, event }),
355			};
356			const factories: ExtensionFactory[] = [...(cc.options.subagentExtensions ?? []), ...subagentInternals.childExtensionFactories, (childPi) => registerUnknownToolErrors(childPi)];
357			if (allowed(AGENT_TOOL_NAME)) {
358				// subagents can launch their own agents (foreground by default)
359				factories.push((childPi) => {
360					const childCC = createCCContext(childOptions, childPi);
361					registerAgent(withDeferredExposure(childPi, new Set(deferredTools ?? [])), childCC, { inFork: internal.inFork || opts.fork });
362					(childCC.notifications as { attachToToolResults?: () => void }).attachToToolResults?.();
363				});
364			}
365	
366			let parentPrompt = "";
367			if (opts.fork) {
368				try {
369					parentPrompt = ctx.getSystemPrompt();
370				} catch {
371					parentPrompt = "";
372				}
373			}
374			const systemPrompt = opts.fork ? parentPrompt : def.prompt ? `${def.prompt}\n\n${SUBAGENT_PROMPT_NOTES}` : SUBAGENT_PROMPT_NOTES;
375	
376			const registry = ctx.modelRegistry;
377			const { session } = await createClaudeCodeSession({
378				cwd: opts.cwd,
379				sessionManager: opts.fork ? forkSessionManager(ctx, opts.cwd) : SessionManager.inMemory(opts.cwd),
380				settingsManager: SettingsManager.inMemory(),
381				// share the parent's credentials and model catalog
382				modelRuntime: cc.options.modelRuntime ?? (registry as unknown as { runtime?: ModelRuntime } | undefined)?.runtime,
383				model,
384				thinkingLevel,
385				claudeCode: childOptions,
386				loader: {
387					// no disk-discovered pi extensions/templates/themes/skills in children; context files (AGENTS.md/CLAUDE.md) are kept
388					noExtensions: true,
389					noPromptTemplates: true,
390					noThemes: true,
391					noSkills: true,
392					...(opts.fork ? { noContextFiles: true } : {}),
393					systemPromptOverride: () => systemPrompt,
394					appendSystemPromptOverride: () => [],
395					extensionFactories: factories,
396				},
397			});
398			try {
399				await session.bindExtensions({});
400			} catch (err) {
401				session.dispose();
402				throw err;
403			}
404			// Deferred tools stay registered-but-inactive until tool_search loads them, as in the parent.
405			session.setActiveToolsByName(session.getActiveToolNames().filter((n) => n === "tool_search" || allowed(n)));
406			return session;
407		}
