409		function startTranscript(run: AgentRun): () => void {
410			const file = run.outputFile;
411			if (!file) return () => {};
412			try {
413				writeFileSync(file, "");
414			} catch {
415				return () => {};
416			}
417			return run.session.subscribe((event) => {
418				if (event.type !== "message_end" || (event.message as { role?: string }).role === "system") return;
419				try {
420					appendFileSync(file, `${JSON.stringify({ type: (event.message as { role?: string }).role, agentId: run.agentId, timestamp: new Date().toISOString(), message: event.message })}\n`);
421				} catch {
422					// transcript is best-effort
423				}
424			});
425		}
