427		async function runAgent(run: AgentRun, prompt: string, onUpdate: AgentToolUpdateCallback<AgentDetails> | undefined): Promise<RunResult> {
428			const { session, agentId, toolCallId: parentToolCallId } = run;
429			const signal = run.controller.signal;
430			const subagentType = run.definition.name;
431			run.running = true;
432			emit({ type: "subagent_start", agentId, parentToolCallId, subagentType, description: run.description, background: run.background });
433	
434			const t0 = Date.now();
435			const startIndex = run.startIndex;
436			let toolUses = 0;
437			const stopTranscript = startTranscript(run);
438			const unsubscribe = session.subscribe((event) => {
439				emit({ type: "subagent_event", agentId, parentToolCallId, event });
440				if (event.type === "tool_execution_start" && onUpdate) {
441					toolUses++;
442					try {
443						onUpdate({
444							content: [{ type: "text", text: `[${subagentType}] ${event.toolName} (${toolUses} tool use${toolUses === 1 ? "" : "s"})` }],
445							details: { agentId, subagentType, description: run.description, status: "running", background: run.background, toolUses, lastToolName: event.toolName },
446						});
447					} catch {
448						// progress is best-effort
449					}
450				}
451			});
452			const onAbort = () => {
453				session.abort().catch(() => {});
454			};
455			signal.addEventListener("abort", onAbort, { once: true });
456	
457			let usage: SubagentUsage | undefined;
458			let isError = true;
459			try {
460				if (signal.aborted) throw new SubagentAbortedError();
461				await session.prompt(prompt, { expandPromptTemplates: false });
462				const newMessages = session.messages.slice(startIndex);
463				usage = computeSubagentUsage(newMessages, Date.now() - t0);
464				const last = [...newMessages].reverse().find(isAssistant);
465				if (signal.aborted || last?.stopReason === "aborted") throw new SubagentAbortedError();
466				if (!last) throw new Error("Subagent produced no response");
467				if (last.stopReason === "error") throw new Error(`Subagent failed: ${last.errorMessage ?? "unknown error"}`);
468				isError = false;
469				return { text: assistantText(last), usage, totalTokens: lastCallTokens(newMessages) };
470			} finally {
471				unsubscribe();
472				stopTranscript();
473				signal.removeEventListener("abort", onAbort);
474				run.running = false;
475				usage ??= computeSubagentUsage(session.messages.slice(startIndex), Date.now() - t0);
476				emit({ type: "subagent_end", agentId, parentToolCallId, subagentType, isError, usage });
477			}
478		}
479	
480		/** Last assistant text of a run that did not complete (for failed/killed notifications). */
481		function partialText(run: AgentRun): string {
482			const last = [...run.session.messages.slice(run.startIndex)].reverse().find(isAssistant);
483			return assistantText(last);
484		}
485	
486		async function finishBackground(run: AgentRun, outcome: { ok: true; result: RunResult } | { ok: false; error: unknown }): Promise<void> {
487			const status: AgentEndStatus = outcome.ok ? "completed" : run.killedBy ? "killed" : "failed";
488			if (run.task && run.task.status === "running") run.task.status = status;
489			const result = outcome.ok ? outcome.result.text : partialText(run);
490			runs.delete(run.agentId);
491			const worktree = run.worktree ? finishAgentWorktree(run.worktree) : undefined;
492			const silent = run.killedBy === "shutdown" || shuttingDown;
493			if (!silent) {
494				const error = outcome.ok ? undefined : outcome.error instanceof Error ? outcome.error.message : String(outcome.error);
495				let text = formatTaskNotification({
496					taskId: run.agentId,
497					toolUseId: run.toolCallId,
498					outputFile: run.outputFile,
499					status,
500					summary: agentNotificationSummary(run.description, status, error),
501					note: AGENT_NOTIFICATION_NOTE,
502					result: result.trim() ? result : undefined,
503					usage: outcome.ok ? { subagentTokens: outcome.result.totalTokens, toolUses: outcome.result.usage.toolUses, durationMs: outcome.result.usage.durationMs } : undefined,
504				});
505				if (worktree) {
506					const branch = worktree.worktreeBranch ? `<worktreeBranch>${worktree.worktreeBranch}</worktreeBranch>` : "";
507					text = text.replace("\n</task-notification>", `\n<worktree><worktreePath>${worktree.worktreePath}</worktreePath>${branch}</worktree>\n</task-notification>`);
508				}
509				if (status === "killed") {
510					// stopped by TaskStop: delivered after that tool call settles, never inside its result
511					setTimeout(() => {
512						if (!shuttingDown) cc.notifications.enqueue(text);
513					}, 0);
514				} else {
515					cc.notifications.enqueue(text);
516				}
517			}
518			await disposeSession(run.session);
519		}
520	
521		async function stopRun(run: AgentRun): Promise<void> {
522			if (!run.running) return;
523			run.killedBy ??= "parent";
524			run.controller.abort();
525			await Promise.race([run.done, new Promise((r) => setTimeout(r, 10_000).unref?.())]);
526		}
527	
528		async function execute(
529			toolCallId: string,
530			params: AgentInput,
531			signal: AbortSignal | undefined,
532			onUpdate: AgentToolUpdateCallback<AgentDetails> | undefined,
533			ctx: ExtensionContext,
534		): Promise<{ content: Array<{ type: "text"; text: string }>; details: AgentDetails }> {
535			if (signal?.aborted) throw new SubagentAbortedError();
536			const invalid = validateAgentInput(params);
537			if (invalid) throw new Error(invalid);
538	
539			const requested = params.subagent_type?.trim() || undefined;
540			const fork = requested === FORK_AGENT_TYPE && !loadDefs(ctx.cwd).has(FORK_AGENT_TYPE);
541			if (fork && internal.inFork) throw new Error("Fork is not available inside a forked worker. Complete your task directly using your tools.");
542			if (fork && params.isolation === "remote") {
543				throw new Error('Fork cannot use isolation: "remote" — a remote session cannot inherit the conversation context. Omit isolation (or use "worktree"), or spawn a named agent type for remote work.');
544			}
545			const def = fork ? FORK_DEFINITION : resolveAgentType(loadDefs(ctx.cwd), requested);
546	
547			const resolved = fork
548				? ({ ok: true, model: ctx.model } as const)
549				: params.model
550					? resolveSubagentModel(params.model, ctx.modelRegistry, ctx.model, { strict: true })
551					: resolveSubagentModel(def.model, ctx.modelRegistry, ctx.model, { strict: false });
552			if (!resolved.ok) throw new Error(resolved.error);
553			const childModel = sameEndpoint(resolved.model, ctx.model);
554			const modelNote = "note" in resolved ? resolved.note : undefined;
555	
556			// Claude Code: agents run in the background unless run_in_background is false; agents launched
557			// by a subagent run in the foreground unless run_in_background is true.
558			const background = params.run_in_background === true || def.background === true || (!isSubagent && params.run_in_background !== false);
559	
560			// "remote" is not available here: fall back to a worktree in a git checkout, else run locally
561			const isolation = params.isolation === "remote" ? (gitRootOf(ctx.cwd) ? "worktree" : undefined) : params.isolation;
562			const agentId = newTaskId("local_agent");
563			const worktree = isolation === "worktree" ? createAgentWorktree(ctx.cwd, agentId) : undefined;
564	
565			let session: AgentSession;
566			try {
567				session = await createChildSession(ctx, def, childModel, {
568					agentId,
569					toolCallId,
570					background,
571					cwd: worktree?.cwd ?? ctx.cwd,
572					effort: fork ? undefined : (params.effort ?? def.effort),
573					fork,
574				});
575			} catch (err) {
576				if (worktree) finishAgentWorktree(worktree);
577				throw err;
578			}
579			const run: AgentRun = {
580				agentId,
581				toolCallId,
582				definition: def,
583				description: params.description,
584				session,
585				model: session.model ?? childModel,
586				modelNote,
587				background,
588				controller: new AbortController(),
589				running: false,
590				startIndex: session.messages.length,
591				worktree,
592			};
593			if (signal?.aborted) {
594				if (worktree) finishAgentWorktree(worktree);
595				await disposeSession(session);
596				throw new SubagentAbortedError();
597			}
598			const prompt = fork ? `${forkDirective(params.prompt)}${worktree ? `\n\n${forkWorktreeNotice(ctx.cwd, worktree.path)}` : ""}` : params.prompt;
599			const baseDetails: AgentDetails = {
600				agentId,
601				subagentType: def.name,
602				description: params.description,
603				status: "completed",
604				background,
605				model: modelLabel(run.model),
606				modelNote,
607			};
608			runs.set(agentId, run);
609	
610			if (background) {
611				run.outputFile = cc.tasks.outputPath(agentId);
612				run.task = cc.tasks.add({
613					id: agentId,
614					type: "local_agent",
615					label: params.description,
616					status: "running",
617					outputFile: run.outputFile,
618					toolUseId: toolCallId,
619					stop: () => stopRun(run),
620				});
621				// not tied to the parent's abort signal: the tool call returns immediately
622				run.done = runAgent(run, prompt, undefined).then(
623					(result) => finishBackground(run, { ok: true, result }),
624					(error) => finishBackground(run, { ok: false, error }),
625				);
626				return {
627					content: [{ type: "text", text: asyncLaunchText(agentId, run.outputFile) }],
628					details: { ...baseDetails, status: "async_launched", outputFile: run.outputFile },
629				};
630			}
631	
632			const forwardAbort = () => run.controller.abort();
633			signal?.addEventListener("abort", forwardAbort, { once: true });
634			let worktreeInfo: WorktreeInfo | undefined;
635			try {
636				const result = await runAgent(run, prompt, onUpdate);
637				worktreeInfo = worktree ? finishAgentWorktree(worktree) : undefined;
638				return {
639					content: [
640						{
641							type: "text",
642							text: foregroundResultText({
643								report: result.text,
644								agentId,
645								agentType: def.name,
646								usage: { totalTokens: result.totalTokens, toolUses: result.usage.toolUses, durationMs: result.usage.durationMs },
647								worktree: worktreeInfo,
648							}),
649						},
650					],
651					details: { ...baseDetails, usage: result.usage, worktree: worktreeInfo },
652				};
653			} catch (err) {
654				if (worktree) finishAgentWorktree(worktree);
655				throw err;
656			} finally {
657				signal?.removeEventListener("abort", forwardAbort);
658				runs.delete(agentId);
659				await disposeSession(session);
660			}
661		}
662	
663		pi.registerTool({
664			name: AGENT_TOOL_NAME,
665			label: "Agent",
666			description: AGENT_TOOL_DESCRIPTION,
667			promptSnippet: "Launch a subagent (general-purpose, Explore, Plan, fork, or a custom agent) for complex multi-step work",
668			parameters: AgentParams,
669			// Claude Code's InputValidationError wording (pi's own validation would word it differently)
670			prepareArguments: (args) => {
671				const invalid = validateAgentInput(args);
672				if (invalid) throw new Error(invalid);
673				return args as AgentInput;
674			},
675			execute: (toolCallId, params, signal, onUpdate, ctx) => execute(toolCallId, params as AgentInput, signal, onUpdate, ctx),
676		});
677	
678		if (!isSubagent) registerUnknownToolErrors(pi);
679	
680		// Claude Code lists the agent types in a system reminder (re-sent when the list changes).
681		pi.on("before_agent_start", (_event, ctx) => {
682			let listing: string;
683			try {
684				listing = formatAgentListingReminder(loadDefs(ctx.cwd));
685			} catch {
686				return undefined;
687			}
688			if (listing === lastListing) return undefined;
689			lastListing = listing;
690			return { message: { customType: REMINDER_CUSTOM_TYPE, content: wrapReminder(listing), display: false } };
691		});
692	
693		pi.on("session_shutdown", async () => {
694			shuttingDown = true;
695			await Promise.all(
696				[...runs.values()].map(async (run) => {
697					if (run.running) {
698						run.killedBy ??= "shutdown";
699						run.controller.abort();
700						await run.session.abort().catch(() => {});
701					}
702					if (run.done) await Promise.race([run.done, new Promise((r) => setTimeout(r, 5_000).unref?.())]);
703				}),
704			);
705		});
706	}
