24	/**
25	 * Convenience wrapper: createAgentSession with pi's built-in tools disabled, the Claude Code tool
26	 * extension installed, and pi's tool_search extension for deferred tools.
27	 */
28	export async function createClaudeCodeSession(opts: CreateClaudeCodeSessionOptions = {}): Promise<CreateAgentSessionResult> {
29		const { claudeCode, toolSearch = true, loader: loaderOpts, ...sessionOpts } = opts;
30		const cwd = sessionOpts.cwd ?? process.cwd();
31		const agentDir = sessionOpts.agentDir ?? getAgentDir();
32		// Created here (instead of inside createAgentSession) so subagent sessions can share it.
33		const modelRuntime = sessionOpts.modelRuntime ?? claudeCode?.modelRuntime ?? (await ModelRuntime.create());
34		const loader = new DefaultResourceLoader({
35			...loaderOpts,
36			cwd,
37			agentDir,
38			settingsManager: loaderOpts?.settingsManager ?? sessionOpts.settingsManager,
39			extensionFactories: [
40				createClaudeCodeExtension({ ...claudeCode, modelRuntime }),
41				...(toolSearch ? [createToolSearchExtension()] : []),
42				...(loaderOpts?.extensionFactories ?? []),
43			],
44		});
45		await loader.reload();
46		return createAgentSession({ ...sessionOpts, cwd, agentDir, modelRuntime, resourceLoader: loader, noTools: "builtin" });
47	}
