7	const TaskStopSpec: Spec = {
8		kind: "object",
9		strict: true,
10		props: { task_id: { spec: { kind: "string" }, optional: true }, shell_id: { spec: { kind: "string" }, optional: true } },
11	};
12	
13	const TASK_STOP_DESCRIPTION = `
14	- Stops a running background task by its ID
15	- Takes a task_id parameter identifying the task to stop
16	- To stop an agent-team teammate, pass its agent ID or bare teammate name as task_id
17	- To stop a background agent spawned with a name, pass that name as task_id
18	- Returns a success or failure status
19	- Use this tool when you need to terminate a long-running task
20	`;
21	
22	/** Claude Code reports input-validation failures wrapped in <tool_use_error>. */
23	const validationError = (message: string) => new Error(`<tool_use_error>${message}</tool_use_error>`);
24	
25	/** TaskStop: stops a background bash command or agent (Claude Code's replacement for KillShell). */
26	export function registerTaskStop(pi: ExtensionAPI, cc: CCContext): void {
27		pi.registerTool({
28			name: "TaskStop",
29			label: "TaskStop",
30			description: TASK_STOP_DESCRIPTION,
31			promptSnippet: "Stop a running background task (bash command or agent) by ID",
32			parameters: Type.Object(
33				{
34					task_id: Type.Optional(
35						Type.String({
36							description:
37								"The ID of the background task to stop. Agent-team teammates and named background agents are also accepted by agent ID or name.",
38						}),
39					),
40					shell_id: Type.Optional(Type.String({ description: "Deprecated: use task_id instead" })),
41				},
42				{ additionalProperties: false },
43			),
44			prepareArguments: claudeInputValidator<{ task_id?: string; shell_id?: string }>("TaskStop", TaskStopSpec) as any,
45			async execute(_toolCallId, params) {
46				const id = params.task_id ?? params.shell_id;
47				if (!id) throw validationError("Missing required parameter: task_id");
48				const task = cc.tasks.get(id);
49				// Claude Code drops finished tasks from its registry once their completion is reported.
50				if (!task || task.status !== "running") throw validationError(`No task found with ID: ${id}`);
51				await cc.tasks.stop(id);
52				return textResult(
53					JSON.stringify({ message: `Successfully stopped task: ${task.id} (${task.label})`, task_id: task.id, task_type: task.type, command: task.label }),
54					{ taskId: task.id, taskType: task.type },
55				);
56			},
57		});
58		pi.on("session_shutdown", async () => {
59			await cc.tasks.stopAll();
60		});
61	}
