3	/**
4	 * Returns a view of `pi` whose registerTool() registers the named tools with pi's native
5	 * `exposure: "deferred"`: they are not declared to the model until pi's built-in `tool_search`
6	 * finds and activates them.
7	 */
8	export function withDeferredExposure(pi: ExtensionAPI, deferred: ReadonlySet<string>): ExtensionAPI {
9		if (deferred.size === 0) return pi;
10		return new Proxy(pi, {
11			get(target, prop, receiver) {
12				if (prop === "registerTool") {
13					return (def: Parameters<ExtensionAPI["registerTool"]>[0]) =>
14						target.registerTool(deferred.has(def.name) ? { ...def, exposure: "deferred" } : def);
15				}
16				const value = Reflect.get(target, prop, receiver);
17				return typeof value === "function" ? value.bind(target) : value;
18			},
19		});
20	}
