22	/**
23	 * Activates pi's built-in `tool_search` (registered inactive by createToolSearchExtension())
24	 * whenever any registered tool — ours, the host's, or an MCP server's — has deferred exposure.
25	 */
26	export function registerToolSearchActivation(pi: ExtensionAPI): void {
27		const ensure = () => {
28			const all = pi.getAllTools();
29			if (!all.some((t) => t.name === "tool_search")) return;
30			if (!all.some((t) => t.exposure === "deferred")) return;
31			const active = pi.getActiveTools();
32			if (!active.includes("tool_search")) pi.setActiveTools([...active, "tool_search"]);
33		};
34		pi.on("session_start", ensure);
35		pi.on("before_agent_start", ensure);
36	}
