146	/**
147	 * pi 1.x passes faux response factories a TranscriptContext whose prompt and tool declarations live
148	 * in system messages. Tests read `context.tools` / `context.systemPrompt`, so expose them again.
149	 */
150	export function withLegacyContext<T extends ReturnType<typeof registerFauxProvider>>(faux: T): T {
151		const wrap = (steps: FauxResponseStep[]) =>
152			steps.map((step) =>
153				typeof step === "function"
154					? ((ctx: any, ...rest: any[]) =>
155							(step as any)(
156								Object.assign(Object.create(ctx), {
157									messages: ctx.messages,
158									tools: getCurrentTools(ctx.messages),
159									systemPrompt: getCurrentSystemPrompt(ctx.messages),
160								}),
161								...rest,
162							)) as FauxResponseStep
163					: step,
164			);
165		const set = faux.setResponses.bind(faux);
166		const append = faux.appendResponses.bind(faux);
167		faux.setResponses = (steps) => set(wrap(steps));
168		faux.appendResponses = (steps) => append(wrap(steps));
169		return faux;
170	}
