158	/** Claude Code's validationErrorSteer: a question with fewer than 2 options gets extra guidance. */
159	function singleOptionSteer(input: unknown): string | null {
160		if (typeof input !== "object" || input === null || Array.isArray(input)) return null;
161		const questions = (input as Record<string, unknown>).questions;
162		if (!Array.isArray(questions)) return null;
163		for (const q of questions) {
