204	/** Claude Code's sentinel answer for "the user only added notes". */
205	const NOTES_ONLY = "(notes only)";
206	
207	const own = <T>(obj: Record<string, T> | undefined, key: string): T | undefined => (obj && Object.hasOwn(obj, key) ? obj[key] : undefined);
208	
209	/** Join multiSelect labels the way Claude Code's UI does (labels with ", " or quotes are JSON-quoted). */
210	export function joinLabels(labels: string[]): string {
211		return labels.map((l) => (l.includes(", ") || l.includes('"') ? JSON.stringify(l) : l)).join(", ");
212	}
213	
214	/** Split a joined multiSelect answer (inverse of joinLabels); null when it is not such a list. */
215	function splitLabels(answer: string): string[] | null {
216		const out: string[] = [];
217		let rest = answer;
218		for (;;) {
219			if (rest.startsWith('"')) {
220				let end = -1;
221				let escaped = false;
222				for (let i = 1; i < rest.length; i++) {
223					const ch = rest[i];
224					if (escaped) {
225						escaped = false;
226						continue;
227					}
228					if (ch === "\\") {
229						escaped = true;
230						continue;
231					}
232					if (ch === '"') {
233						end = i;
234						break;
235					}
236				}
237				if (end === -1) return null;
238				try {
239					const v = JSON.parse(rest.slice(0, end + 1));
240					if (typeof v !== "string") return null;
241					out.push(v);
242				} catch {
243					return null;
244				}
245				rest = rest.slice(end + 1);
246			} else {
247				const i = rest.indexOf(", ");
248				const part = i === -1 ? rest : rest.slice(0, i);
249				if (part.includes('"')) return null;
250				out.push(part);
251				rest = i === -1 ? "" : rest.slice(i);
252			}
253			if (rest === "") break;
254			if (!rest.startsWith(", ")) return null;
255			rest = rest.slice(2);
256			if (rest === "") return null;
257		}
258		return out;
259	}
