261	/** Build Claude Code's result text. */
262	export function formatAnswers(
263		questions: AskUserQuestionItem[],
264		answers: Record<string, string | string[]>,
265		annotations?: Record<string, AskUserQuestionAnnotation>,
266		response?: string,
267	): string {
268		const parts = questions
269			.map(({ question }) => {
270				const answer = own(answers, question);
271				const note = own(annotations, question);
272				const answered = !!answer && answer !== NOTES_ONLY && !(Array.isArray(answer) && answer.length === 0);
273				if (!answered && !note?.notes) return null;
274				const p = [answered ? `"${question}"="${answer}"` : `"${question}"=(no option selected)`];
275				if (note?.preview) p.push(`selected preview:\n${note.preview}`);
276				if (note?.notes) p.push(`notes: ${note.notes}`);
277				return p.join(" ");
278			})
279			.filter((p): p is string => p !== null)
280			.join(", ");
281		if (response?.trim()) return `The user responded: ${response}`;
282		if (!parts) return "The user did not answer the questions.";
283		const allOptionLabels = questions.every(({ question, options, multiSelect }) => {
284			if (own(annotations, question)?.notes) return false;
285			const answer = own(answers, question);
286			const labels = new Set(options.map((o) => o.label));
287			if (Array.isArray(answer)) return multiSelect && answer.length > 0 && answer.every((a) => labels.has(a));
288			if (!answer || answer === NOTES_ONLY) return true;
289			if (labels.has(answer)) return true;
290			if (!multiSelect) return false;
291			const split = splitLabels(answer);
292			return split !== null && split.length >= 1 && joinLabels(split) === answer && split.every((a) => labels.has(a));
293		});
294		return allOptionLabels
295			? `Your questions have been answered: ${parts}. You can now continue with these answers in mind.`
296			: `The user answered: ${parts}. Read the answers carefully — they may request clarification, changes, or that you not proceed — and follow what they actually say.`;
297	}
