299	function abortError(): Error {
300		return new Error("AskUserQuestion was aborted");
301	}
302	
303	/** Resolve `p`, rejecting early when `signal` aborts. */
304	function raceAbort<T>(p: Promise<T>, signal: AbortSignal | undefined): Promise<T> {
305		if (!signal) return p;
306		if (signal.aborted) return Promise.reject(abortError());
307		return new Promise<T>((resolve, reject) => {
308			const onAbort = () => reject(abortError());
309			signal.addEventListener("abort", onAbort, { once: true });
310			p.then(
311				(v) => {
312					signal.removeEventListener("abort", onAbort);
313					resolve(v);
314				},
315				(e) => {
316					signal.removeEventListener("abort", onAbort);
317					reject(e);
318				},
319			);
320		});
321	}
322	
323	const OTHER_LABEL = "Other (type your own answer)";
324	const DONE_LABEL = "Done";
325	
326	/**
327	 * Fallback when no host callback is configured but pi has a UI: one `ctx.ui.select` per question
328	 * (option labels plus an "Other" entry that opens `ctx.ui.input`). For multiSelect questions the
329	 * select is shown repeatedly, removing already-picked labels and adding a "Done" entry, until the
330	 * user picks "Done", dismisses the dialog, or every option is picked. A dismissed dialog leaves
331	 * that question unanswered.
332	 */
333	async function askViaUI(questions: AskUserQuestionItem[], ctx: ExtensionContext, signal: AbortSignal | undefined): Promise<Record<string, string | string[]>> {
334		const answers: Record<string, string | string[]> = {};
335		const dialogOpts = signal ? { signal } : undefined;
336		for (const q of questions) {
337			if (signal?.aborted) throw abortError();
338			const title = `${q.header}: ${q.question}`;
339			const picked: string[] = [];
340			while (true) {
341				const remaining = q.options.map((o) => o.label).filter((l) => !picked.includes(l));
342				const choices = [...remaining, OTHER_LABEL];
343				if (q.multiSelect && picked.length > 0) choices.push(DONE_LABEL);
344				const choice = await ctx.ui.select(q.multiSelect && picked.length ? `${title} (selected: ${picked.join(", ")})` : title, choices, dialogOpts);
345				if (signal?.aborted) throw abortError();
346				if (choice === undefined || choice === DONE_LABEL) break;
347				if (choice === OTHER_LABEL) {
348					const text = await ctx.ui.input(q.question, "Your answer", dialogOpts);
349					if (signal?.aborted) throw abortError();
350					if (text !== undefined && text.trim() !== "") picked.push(text.trim());
351					if (!q.multiSelect) break;
352					continue;
353				}
354				picked.push(choice);
355				if (!q.multiSelect || picked.length >= q.options.length) break;
356			}
357			if (picked.length) answers[q.question] = q.multiSelect ? picked : picked[0];
358		}
359		return answers;
360	}
361	
362	const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
363	
364	/** Normalize what the host returned into string answers (multiSelect arrays joined) plus extras. */
365	function normalizeHostResult(
366		questions: AskUserQuestionItem[],
367		raw: unknown,
368	): { answers: Record<string, string>; annotations?: Record<string, AskUserQuestionAnnotation>; response?: string } {
369		let answersIn: Record<string, unknown> = {};
370		let annotations: Record<string, AskUserQuestionAnnotation> | undefined;
371		let response: string | undefined;
372		if (isPlainObject(raw)) {
373			// structured form: { answers: {...}, annotations?, response? } (an answer is never an object)
374			if (isPlainObject(raw.answers) || isPlainObject(raw.annotations)) {
375				answersIn = isPlainObject(raw.answers) ? raw.answers : {};
376				if (isPlainObject(raw.annotations)) annotations = raw.annotations as Record<string, AskUserQuestionAnnotation>;
377				if (typeof raw.response === "string") response = raw.response;
378			} else answersIn = raw;
379		}
380		const answers: Record<string, string> = {};
381		for (const q of questions) {
382			const v = own(answersIn, q.question);
383			if (Array.isArray(v)) {
384				const labels = v.filter((x) => x !== undefined && x !== null).map(String);
385				if (labels.length) answers[q.question] = joinLabels(labels);
386			} else if (v !== undefined && v !== null && String(v) !== "") answers[q.question] = String(v);
387		}
388		return { answers, annotations, response };
389	}
