391	export function registerAskUserQuestion(pi: ExtensionAPI, cc: CCContext): void {
392		pi.registerTool({
393			name: ASK_USER_QUESTION_TOOL_NAME,
394			label: "AskUserQuestion",
395			description: ASK_USER_QUESTION_DESCRIPTION,
396			promptSnippet: "AskUserQuestion: ask the user 1-4 multiple-choice questions to clarify requirements or decisions",
397			parameters: AskUserQuestionParams as any,
398			prepareArguments: claudeInputValidator<AskUserQuestionInput>(ASK_USER_QUESTION_TOOL_NAME, AskUserQuestionSpec, { steer: singleOptionSteer }),
399			async execute(toolCallId, params, signal, _onUpdate, ctx) {
400				const { questions } = params as AskUserQuestionInput;
401				if (signal?.aborted) throw abortError();
402	
403				let raw: unknown;
404				const host = cc.options.onAskUserQuestion;
405				if (host) {
406					try {
407						const copy = questions.map((q) => ({ ...q, options: q.options.map((o) => ({ ...o })) }));
408						raw = await raceAbort(Promise.resolve().then(() => host(copy, { signal, toolCallId })), signal);
409					} catch (err) {
410						if (signal?.aborted) throw abortError();
411						const msg = err instanceof Error ? err.message : String(err);
412						throw new Error(`Failed to ask the user: ${msg}`);
413					}
414				} else if (ctx?.hasUI) {
415					raw = await askViaUI(questions, ctx, signal);
416				} else {
417					throw new Error(
418						"The user cannot be asked questions interactively in this environment (no question handler is available). " +
419							"Do not retry AskUserQuestion. Proceed using your best judgement, and clearly state any assumptions you make.",
420					);
421				}
422				if (signal?.aborted) throw abortError();
423	
424				const { answers, annotations, response } = normalizeHostResult(questions, raw);
425				const unanswered = questions.filter((q) => !(q.question in answers)).map((q) => q.question);
426				const details: AskUserQuestionDetails = { questions, answers, unanswered };
427				if (annotations) details.annotations = annotations;
428				if (response?.trim()) details.response = response;
429				return textResult<AskUserQuestionDetails>(formatAnswers(questions, answers, annotations, response), details);
430			},
