13	// Mirrors Claude Code's Glob tool description verbatim.
14	const DESCRIPTION = `- Fast file pattern matching tool that works with any codebase size
15	- Supports glob patterns like "**/*.js" or "src/**/*.ts"
16	- Returns matching file paths sorted by modification time
17	- Use this tool when you need to find files by name patterns
18	- When you are doing an open ended search that may require multiple rounds of globbing and grepping, use the Agent tool instead (if available)`;
19	
20	const globSchema = Type.Object({
21		pattern: Type.String({ description: "The glob pattern to match files against" }),
22		path: Type.Optional(
23			Type.String({
24				description:
25					'The directory to search in. If not specified, the current working directory will be used. IMPORTANT: Omit this field to use the default directory. DO NOT enter "undefined" or "null" - simply omit it for the default behavior. Must be a valid directory path if provided.',
26			}),
27		),
28	});
29	
30	export type GlobParams = Static<typeof globSchema>;
31	
32	/** Same shape as Claude Code's Glob output. */
33	export interface GlobDetails {
34		durationMs: number;
35		/** Number of file paths returned (after truncation). */
36		numFiles: number;
37		filenames: string[];
38		truncated: boolean;
39		/** Total number of matching files before truncation. */
40		totalMatches: number;
41		countIsComplete: boolean;
42	}
43	
44	/** Claude Code's truncation line. */
45	export function globTruncationNote(shown: number, total: number): string {
46		return `(Showing ${shown} of ${total} matching files; ${total - shown} more are not listed. Narrow the pattern or path to see the rest.)`;
47	}
48	
49	function envFlag(name: string, dflt: boolean): boolean {
50		const v = process.env[name];
51		if (v === undefined || v === "") return dflt;
52		return ["1", "true", "yes", "on"].includes(v.trim().toLowerCase());
53	}
54	
55	/**
56	 * An absolute pattern is split into its literal base directory and the rest
57	 * ("/repo/src/**\/*.ts" → "/repo/src" + "**\/*.ts"); the base directory replaces `path`.
58	 */
59	export function splitAbsolutePattern(pattern: string): { baseDir: string; relativePattern: string } | null {
60		if (!isAbsolute(pattern)) return null;
61		const m = /[*?[{]/.exec(pattern);
62		if (!m) return { baseDir: dirname(pattern), relativePattern: basename(pattern) };
63		const literal = pattern.slice(0, m.index);
64		const cut = Math.max(literal.lastIndexOf("/"), literal.lastIndexOf(sep));
65		if (cut === -1) return null;
66		let baseDir = literal.slice(0, cut);
67		if (baseDir === "" && cut === 0) baseDir = "/";
68		if (!baseDir) return null;
69		return { baseDir, relativePattern: pattern.slice(cut + 1) };
70	}
71	
72	/**
73	 * When the pattern repeats the tail of the search directory ("src/**\/*.ts" searched in ".../src"),
74	 * return the pattern anchored without that prefix ("/**\/*.ts"); otherwise the pattern unchanged.
75	 */
76	export function stripRepeatedDirPrefix(pattern: string, searchDir: string): string {
77		const segs = pattern.split("/");
78		let literal = 0;
79		while (literal < segs.length - 1 && segs[literal] !== "" && !/[*?[\]{}!]/.test(segs[literal])) literal++;
80		const dirSegs = searchDir.split(/[\\/]+/).filter(Boolean);
81		for (let n = literal; n > 0; n--) {
82			const head = segs.slice(0, n);
83			const tail = dirSegs.slice(-n);
84			if (tail.length === n && head.every((s, i) => s === tail[i])) return "/" + segs.slice(n).join("/");
85		}
86		return pattern;
87	}
88	
89	/** True when every segment exists under `dir` as a real (non-symlink) directory. */
90	async function prefixIsRealDir(dir: string, segs: string[]): Promise<boolean> {
91		let p = dir;
92		for (const s of segs) {
93			p = join(p, s);
94			try {
95				const st = await lstat(p);
96				if (!st.isDirectory() || st.isSymbolicLink()) return false;
97			} catch {
98				return false;
99			}
100		}
101		return segs.length > 0;
102	}
103	
104	export async function executeGlob(
105		params: GlobParams,
106		cwd: string,
107		signal?: AbortSignal,
108	): Promise<{ text: string; details: GlobDetails }> {
109		const start = Date.now();
110		if (typeof params.pattern !== "string") throw new Error("pattern must be a string");
111		if (signal?.aborted) throw new Error("Operation aborted");
112	
113		const abs = splitAbsolutePattern(params.pattern);
114		const searchDir = abs ? resolve(abs.baseDir) : params.path ? resolvePath(cwd, params.path) : resolve(cwd);
115	
116		// The path parameter is validated only when it is the directory searched.
117		if (params.path && searchDir === resolvePath(cwd, params.path)) {
118			let st;
119			try {
120				st = await stat(searchDir);
121			} catch {
122				throw new Error(missingPathMessage("Directory", params.path, searchDir, cwd));
123			}
124			if (!st.isDirectory()) throw new Error(`Path is not a directory: ${params.path}`);
125		}
126	
127		let pattern = abs ? abs.relativePattern : params.pattern;
128		if (!abs) {
129			const stripped = stripRepeatedDirPrefix(pattern, searchDir);
130			if (stripped !== pattern) {
131				const restSegs = stripped.replace(/^\//, "").split("/").length;
132				const segs = pattern.split("/");
133				if (!(await prefixIsRealDir(searchDir, segs.slice(0, Math.max(1, segs.length - restSegs))))) pattern = stripped;
134			}
135		}
136	
137		const details: GlobDetails = { durationMs: 0, numFiles: 0, filenames: [], truncated: false, totalMatches: 0, countIsComplete: true };
138		let isDir = false;
139		try {
140			isDir = (await stat(searchDir)).isDirectory();
141		} catch {
142			details.durationMs = Date.now() - start;
143			return { text: "No files found", details };
144		}
145	
146		const args = ["--files", "--null", "--glob", pattern, "--sort=modified"];
147		if (envFlag("CLAUDE_CODE_GLOB_NO_IGNORE", true)) args.push("--no-ignore");
148		if (envFlag("CLAUDE_CODE_GLOB_HIDDEN", true)) args.push("--hidden");
149		args.push(isDir ? "." : searchDir);
150		const run = await runRipgrep(args, isDir ? searchDir : dirname(searchDir), signal);
151		if (signal?.aborted) throw new Error("Operation aborted");
152	
153		const files = splitNullOutput(run.lines, "files_with_matches").map((p) =>
154			isDir ? join(searchDir, p.startsWith("./") ? p.slice(2) : p) : p,
155		);
156		const shown = files.slice(0, GLOB_MAX_RESULTS).map((f) => displayPath(cwd, f));
157		details.filenames = shown;
158		details.numFiles = shown.length;
159		details.truncated = files.length > GLOB_MAX_RESULTS;
160		details.totalMatches = files.length;
161		details.durationMs = Date.now() - start;
162		if (shown.length === 0) return { text: "No files found", details };
163		const text = [...shown, ...(details.truncated ? [globTruncationNote(shown.length, files.length)] : [])].join("\n");
164		return { text, details };
165	}
166	
167	export function registerGlob(pi: ExtensionAPI, _cc: CCContext): void {
168		pi.registerTool({
169			name: GLOB_TOOL_NAME,
170			label: "Glob",
171			description: DESCRIPTION,
172			promptSnippet: 'Find files by glob pattern (e.g. "**/*.ts"), oldest first',
173			parameters: globSchema,
174			async execute(_toolCallId, params, signal, _onUpdate, ctx) {
175				const { text, details } = await executeGlob(params, ctx.cwd, signal);
176				return textResult<GlobDetails>(text, details);
177			},
178		});
179	}
