133	let cachedRgPath: string | undefined;
134	
135	function commandWorks(cmd: string): boolean {
136		try {
137			const r = spawnSync(cmd, ["--version"], { stdio: "ignore" });
138			return !r.error && r.status === 0;
139		} catch {
140			return false;
141		}
142	}
