144	/**
145	 * Locate ripgrep the same way pi does: pi's managed bin dir (<agentDir>/bin/rg) first,
146	 * then `rg` on PATH, then (best effort) pi's own `ensureTool` downloader. That module is not
147	 * part of pi's public exports, so it is loaded by file path; failures fall through to a clear error.
148	 */
149	export async function resolveRgPath(): Promise<string> {
150		if (cachedRgPath) return cachedRgPath;
151		const exe = process.platform === "win32" ? "rg.exe" : "rg";
152		try {
153			const local = join(getAgentDir(), "bin", exe);
154			if (existsSync(local)) return (cachedRgPath = local);
155		} catch {
156			// ignore
157		}
158		if (commandWorks("rg")) return (cachedRgPath = "rg");
159		try {
160			const require = createRequire(import.meta.url);
161			const entry = require.resolve("@earendil-works/pi-coding-agent");
162			const managerPath = join(dirname(entry), "utils", "tools-manager.js");
163			if (existsSync(managerPath)) {
164				const mod: any = await import(pathToFileURL(managerPath).href);
165				const p = await mod.ensureTool?.("rg", true);
166				if (typeof p === "string" && p) return (cachedRgPath = p);
167			}
168		} catch {
169			// ignore
170		}
171		throw new Error(
172			"ripgrep (rg) is not installed or not on PATH. Install ripgrep (https://github.com/BurntSushi/ripgrep) to use Grep.",
173		);
174	}
