186	/**
187	 * Claude Code's "Did you mean" hint for a missing path: when the path lies in cwd's parent
188	 * (but not in cwd) and the same relative path exists inside cwd, suggest that.
189	 */
190	export function suggestUnderCwd(cwd: string, abs: string): string | undefined {
191		const parent = dirname(cwd);
192		let p = abs;
193		try {
194			p = join(realpathSync(dirname(abs)), basename(abs));
195		} catch {
196			// keep lexical path
197		}
198		const parentPrefix = parent === sep ? sep : parent + sep;
199		if (!p.startsWith(parentPrefix) || p.startsWith(cwd + sep) || p === cwd) return undefined;
200		const candidate = join(cwd, relative(parent, p));
201		return existsSync(candidate) ? candidate : undefined;
202	}
