204	/** Message for a path that does not exist, as Claude Code words it. */
205	export function missingPathMessage(kind: "Path" | "Directory", raw: string, abs: string, cwd: string): string {
206		const hint = suggestUnderCwd(cwd, abs);
207		return `${kind} does not exist: ${raw}. ${CWD_NOTE} ${cwd}.${hint ? ` Did you mean ${hint}?` : ""}`;
208	}
