210	/** Truncate to `max` UTF-16 units without splitting a surrogate pair. */
211	function safeSlice(s: string, max: number): string {
212		if (s.length <= max) return s;
213		const cut = s.slice(0, max);
214		const c = cut.charCodeAt(max - 1);
215		return c >= 0xd800 && c <= 0xdbff ? cut.slice(0, -1) : cut;
216	}
