227	function rgTimeoutMs(): number {
228		const s = Number(process.env.CLAUDE_CODE_GLOB_TIMEOUT_SECONDS);
229		return Number.isFinite(s) && s > 0 ? s * 1000 : DEFAULT_RG_TIMEOUT_MS;
230	}
