232	/**
233	 * Run rg and collect its output the way Claude Code does: exit 1 = no matches; exit 2 with output =
234	 * partial errors (results kept); 20 MB stdout cap and 20 s timeout keep the complete lines read so far.
235	 */
236	export async function runRipgrep(args: string[], cwd: string, signal: AbortSignal | undefined): Promise<RgRun> {
237		const rgPath = await resolveRgPath();
238		const run = await new Promise<{ stdout: string; stderr: string; code: number | null; timedOut: boolean; capped: boolean }>(
239			(resolvePromise, reject) => {
240				if (signal?.aborted) {
241					reject(new Error("Operation aborted"));
242					return;
243				}
244				const child = spawn(rgPath, args, { cwd, stdio: ["ignore", "pipe", "pipe"] });
245				const chunks: Buffer[] = [];
246				let bytes = 0;
247				let capped = false;
248				let timedOut = false;
249				let stderr = "";
250				let settled = false;
251				const timer = setTimeout(() => {
252					timedOut = true;
253					child.kill("SIGTERM");
254					setTimeout(() => child.kill("SIGKILL"), 5000).unref();
255				}, rgTimeoutMs());
256				const onAbort = () => {
257					child.kill("SIGKILL");
258					if (!settled) {
259						settled = true;
260						clearTimeout(timer);
261						reject(new Error("Operation aborted"));
262					}
263				};
264				signal?.addEventListener("abort", onAbort, { once: true });
265				child.stdout.on("data", (d: Buffer) => {
266					if (capped) return;
267					if (bytes + d.length > MAX_RG_OUTPUT_BYTES) {
268						chunks.push(d.subarray(0, MAX_RG_OUTPUT_BYTES - bytes));
269						bytes = MAX_RG_OUTPUT_BYTES;
270						capped = true;
271						child.kill("SIGKILL");
272						return;
273					}
274					chunks.push(d);
275					bytes += d.length;
276				});
277				child.stderr.on("data", (d: Buffer) => {
278					if (stderr.length < 64 * 1024) stderr += d.toString("utf8");
279				});
280				child.on("error", (err) => {
281					clearTimeout(timer);
282					signal?.removeEventListener("abort", onAbort);
283					if (!settled) {
284						settled = true;
285						reject(new Error(`Failed to run ripgrep: ${err.message}`));
286					}
287				});
288				child.on("close", (code) => {
289					clearTimeout(timer);
290					signal?.removeEventListener("abort", onAbort);
291					if (settled) return;
292					settled = true;
293					resolvePromise({ stdout: Buffer.concat(chunks).toString("utf8"), stderr, code, timedOut, capped });
294				});
295			},
296		);
297	
298		const abnormal = run.code !== 0 && run.code !== 1 && run.code !== 2;
299		const cut = run.capped || run.timedOut || abnormal;
300		let stdout = run.stdout;
301		if (cut && !stdout.endsWith("\n")) {
302			// drop the partial last line
303			const nl = stdout.lastIndexOf("\n");
304			stdout = nl >= 0 ? stdout.slice(0, nl + 1) : "";
305		}
306		const lines = stdout === "" ? [] : stdout.replace(/\n$/, "").split("\n");
307		if (run.code === 1 && !cut) return { lines: [], stderr: run.stderr, code: 1 };
308		if (lines.length === 0) {
309			if (run.code === 2 && RG_USAGE_ERROR.test(run.stderr)) {
310				throw new Error(`Search failed — ripgrep rejected the pattern, glob, or file type without searching:\n${safeSlice(run.stderr.trim(), 2000)}`);
311			}
312			if (run.timedOut) {
313				throw new Error(
314					`Ripgrep search timed out after ${rgTimeoutMs() / 1000} seconds. The search may have matched files but did not complete in time. Try searching a more specific path or pattern.`,
315				);
316			}
317			if (run.capped) {
318				throw new Error(
319					`Ripgrep output passed the ${MAX_RG_OUTPUT_BYTES / 1e6}MB limit before a single complete line was read, so there are no usable results: at least one matching line is extremely long. Try a more specific pattern or path, or exclude very large files.`,
320				);
321			}
322			if (abnormal) {
323				throw new Error(
324					'The search failed, so this is not a "no matches" result: matches may exist. What happened to the search program (ripgrep) is not known, and no results were read. Run the search once more. If it fails again, tell the user that searches are failing. Do not run a recursive search in the shell instead (for example grep -r, find or rg): it can reach what this tool is set to leave out.',
325				);
326			}
327		}
328		return { lines, stderr: run.stderr, code: run.code };
329	}
