331	/**
332	 * Split rg `--null` output (lines joined back with "\n") into entries. Count mode yields
333	 * "path:N" (zero counts dropped), the other modes yield paths.
334	 */
335	export function splitNullOutput(lines: string[], mode: "count" | "files_with_matches"): string[] {
336		const s = lines.join("\n");
337		if (!s.includes("\0")) return lines;
338		const out: string[] = [];
339		if (mode === "count") {
340			const re = /([^\0]*)\0:?(\d+)(?:\n|$)/y;
341			for (let m = re.exec(s); m !== null; m = re.exec(s)) if (m[2] !== "0") out.push(`${m[1]}:${m[2]}`);
342			return out;
343		}
344		const parts = s.split("\0");
345		parts.pop();
346		for (let i = 0; i < parts.length; i++) {
347			const p = i === 0 ? parts[i] : parts[i].replace(/^\n/, "");
348			if (p !== "") out.push(p);
349		}
350		return out;
351	}
352	
353	/**
354	 * Split a glob parameter into individual rg --glob values. Whitespace separates patterns;
355	 * commas separate patterns too, except inside brace expressions like "*.{ts,tsx}".
356	 */
357	export function splitGlobs(glob: string): string[] {
358		const out: string[] = [];
359		for (const part of glob.split(/\s+/)) {
360			if (part.includes("{") && part.includes("}")) out.push(part);
361			else out.push(...part.split(",").filter(Boolean));
362		}
363		return out.filter(Boolean);
364	}
365	
366	function applyPaging<T>(items: T[], limit: number | undefined, offset: number): { items: T[]; appliedLimit?: number } {
367		if (limit === 0) return { items: items.slice(offset) };
368		const n = limit ?? GREP_DEFAULT_HEAD_LIMIT;
369		return { items: items.slice(offset, offset + n), appliedLimit: items.length - offset > n ? n : undefined };
370	}
371	
372	function pagingText(limit: number | undefined, offset: number | undefined): string {
373		const parts: string[] = [];
374		if (limit !== undefined) parts.push(`limit: ${limit}`);
375		if (offset) parts.push(`offset: ${offset}`);
376		return parts.join(", ");
377	}
378	
379	/** Build the rg argument list (Claude Code's order). Exported for tests. */
380	export function buildRgArgs(params: GrepParams, target: string): string[] {
381		const mode: GrepOutputMode = params.output_mode ?? "files_with_matches";
382		const args: string[] = ["--hidden"];
383		for (const d of VCS_DIRS) args.push("--glob", `!${d}`);
384		args.push("--max-columns", "500");
385		if (params.multiline) args.push("-U", "--multiline-dotall");
386		if (params["-i"]) args.push("-i");
387		if (mode === "files_with_matches") args.push("-l");
388		else if (mode === "count") args.push("-c", "-H");
389		args.push(mode === "content" ? "--json" : "--null");
390		if (mode === "content") {
391			args.push("-n");
392			if (params["-o"]) args.push("-o");
393			if (params.context !== undefined) args.push("-C", String(params.context));
394			else if (params["-C"] !== undefined) args.push("-C", String(params["-C"]));
395			else {
396				if (params["-B"] !== undefined) args.push("-B", String(params["-B"]));
397				if (params["-A"] !== undefined) args.push("-A", String(params["-A"]));
398			}
399		}
400		if (params.pattern.startsWith("-")) args.push("-e", params.pattern);
401		else args.push(params.pattern);
402		if (params.type) args.push("--type", params.type);
403		if (params.glob) for (const g of splitGlobs(params.glob)) args.push("--glob", g);
404		args.push(target);
405		return args;
406	}
