408	// ---------------------------------------------------------------------------
409	// content mode: rg --json → "path\0N:line" entries (Claude Code's format)
410	// ---------------------------------------------------------------------------
411	
412	interface RgJsonText {
413		text?: string;
414		bytes?: string;
415	}
416	interface RgJsonEvent {
417		type: string;
418		data?: {
419			path?: RgJsonText;
420			lines?: RgJsonText;
421			line_number?: number;
422			submatches?: Array<{ match?: RgJsonText; start?: number }>;
423			binary_offset?: number | null;
424		};
425	}
426	
427	const jsonText = (t: RgJsonText | undefined): string =>
428		t === undefined ? "" : t.text !== undefined ? t.text : Buffer.from(t.bytes ?? "", "base64").toString("utf8");
429	
430	function newlinesBefore(buf: Buffer, end: number): number {
431		let n = 0;
432		for (let i = Math.min(end, buf.length) - 1; i >= 0; i--) if (buf[i] === 10) n++;
433		return n;
434	}
435	
436	/**
437	 * Parse rg --json output into "path\0N:line" / "path\0N-line" entries plus "--" context breaks.
438	 * Claude Code keeps rg's (multi-threaded, unstable) file order; files are sorted by path here so
439	 * output and paging are deterministic.
440	 */
441	export function parseRgJson(lines: string[], opts: { contextBreaks: boolean; onlyMatching: boolean }): string[] {
442		// group events per file (begin .. end)
443		const groups: Array<{ path: string; events: RgJsonEvent[] }> = [];
444		let current: { path: string; events: RgJsonEvent[] } | undefined;
445		for (const line of lines) {
446			if (!line.startsWith("{")) continue;
447			let ev: RgJsonEvent;
448			try {
449				ev = JSON.parse(line);
450			} catch {
451				continue;
452			}
453			if (ev === null || typeof ev !== "object") continue;
454			if (ev.type === "begin") {
455				current = { path: jsonText(ev.data?.path), events: [ev] };
456				groups.push(current);
457				continue;
458			}
459			if (ev.type === "summary") continue;
460			if (!current) {
461				current = { path: jsonText(ev.data?.path), events: [] };
462				groups.push(current);
463			}
464			current.events.push(ev);
465			if (ev.type === "end") current = undefined;
466		}
467		groups.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
468	
469		const omit = (s: string, kind: "match" | "context") =>
470			s.length > MAX_LINE_CHARS ? (kind === "match" ? "[Omitted long matching line]" : "[Omitted long context line]") : s;
471		const out: string[] = [];
472		let pending: string[] = [];
473		let lastPath: string | null = null;
474		let lastLine = -1;
475		for (const g of groups) {
476			for (const ev of g.events) {
477				const d = ev.data ?? {};
478				if (ev.type === "begin") {
479					pending = [];
480					continue;
481				}
482				if (ev.type === "end") {
483					const binaryOffset = d.binary_offset;
484					const isBinary = typeof binaryOffset === "number";
485					for (const l of pending) if (!isBinary || !l.slice(l.indexOf("\0") + 1).includes("\0")) out.push(l);
486					if (isBinary && pending.length > 0) out.push(`${jsonText(d.path)}\0binary file matches (found "\\0" byte around offset ${binaryOffset})`);
487					pending = [];
488					continue;
489				}
490				if (ev.type !== "match" && ev.type !== "context") continue;
491				const path = jsonText(d.path);
492				const lineNo = d.line_number ?? 0;
493				const text = jsonText(d.lines).replace(/\r?\n$/, "");
494				if (opts.contextBreaks && lastPath !== null && (path !== lastPath || lineNo > lastLine + 1)) pending.push("--");
495				if (ev.type === "match" && opts.onlyMatching) {
496					let last = lineNo;
497					const buf = Buffer.from(text);
498					for (const sm of d.submatches ?? []) {
499						const start = lineNo + newlinesBefore(buf, sm.start ?? 0);
500						jsonText(sm.match)
501							.split("\n")
502							.forEach((part, i) => {
503								pending.push(`${path}\0${start + i}:${omit(part.replace(/\r$/, ""), "match")}`);
504								last = start + i;
505							});
506					}
507					lastPath = path;
508					lastLine = last;
509					continue;
510				}
511				const kind = ev.type === "match" ? "match" : "context";
512				const sepChar = kind === "match" ? ":" : "-";
513				const parts = text.split("\n").map((p) => p.replace(/\r$/, ""));
514				parts.forEach((p, i) => pending.push(`${path}\0${lineNo + i}${sepChar}${omit(p, kind)}`));
515				lastPath = path;
516				lastLine = lineNo + parts.length - 1;
517			}
518		}
519		for (const l of pending) out.push(l);
520		return out;
521	}
