525	// ---------------------------------------------------------------------------
526	
527	function validateWholeNumber(name: "head_limit" | "offset", v: unknown): void {
528		if (v === undefined || v === null) return;
529		if (typeof v !== "number" || !Number.isInteger(v) || v < 0) {
530			throw new Error(`${name} must be a whole number of 0 or more, got ${v}.${name === "head_limit" ? " Pass 0 for unlimited." : ""}`);
531		}
532	}
533	
534	const byString = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
535	
536	export async function executeGrep(
537		params: GrepParams,
538		cwd: string,
539		signal?: AbortSignal,
540	): Promise<{ text: string; details: GrepDetails }> {
541		const mode: GrepOutputMode = params.output_mode ?? "files_with_matches";
542		if (typeof params.pattern !== "string") throw new Error("pattern must be a string");
543		validateWholeNumber("head_limit", params.head_limit);
544		validateWholeNumber("offset", params.offset);
545		const limit = params.head_limit ?? undefined;
546		const offset = params.offset ?? 0;
547	
548		const searchAbs = params.path ? resolvePath(cwd, params.path) : cwd;
549		let isDirectory: boolean;
550		try {
551			isDirectory = statSync(searchAbs).isDirectory();
552		} catch {
553			if (params.path) throw new Error(missingPathMessage("Path", params.path, searchAbs, cwd));
554			const empty = emptyDetails(mode);
555			return { text: formatGrep(empty), details: empty };
556		}
557	
558		// Directories: run inside the directory on "." (paths come back as "./x"); files: absolute path.
559		const target = isDirectory ? "." : searchAbs;
560		const spawnCwd = isDirectory ? searchAbs : dirname(searchAbs);
561		const toAbs = (p: string) => (isDirectory ? join(searchAbs, p.startsWith("./") ? p.slice(2) : p) : p);
562		const run = await runRipgrep(buildRgArgs(params, target), spawnCwd, signal);
563	
564		let details: GrepDetails;
565		if (mode === "content") {
566			const contextBreaks = [params.context, params["-C"], params["-B"], params["-A"]].some((v) => typeof v === "number" && v > 0);
567			const entries = parseRgJson(run.lines, { contextBreaks, onlyMatching: params["-o"] === true });
568			const showNumbers = params["-n"] !== false;
569			const paged = applyPaging(entries, limit, offset);
570			const out = paged.items.map((e) => {
571				const nul = e.indexOf("\0");
572				if (nul < 0) return showNumbers ? e : e.replace(/^\d+[:-]/, "");
573				const rest = e.slice(nul + 1);
574				const m = /^(\d+)([:-])/.exec(rest);
575				const sepChar = m?.[2] ?? ":";
576				const body = showNumbers || m === null ? rest : rest.slice(m[0].length);
577				return isDirectory ? displayPath(cwd, toAbs(e.slice(0, nul))) + sepChar + body : body;
578			});
579			details = {
580				mode: "content",
581				numFiles: 0,
582				filenames: [],
583				content: out.join("\n"),
584				numLines: out.length,
585				totalLines: entries.length,
586				...(paged.appliedLimit !== undefined && { appliedLimit: paged.appliedLimit }),
587				...(offset > 0 && { appliedOffset: offset }),
588			};
589		} else if (mode === "count") {
590			const entries = splitNullOutput(run.lines, "count").map((e) => {
591				const i = e.lastIndexOf(":");
592				return i > 0 ? toAbs(e.slice(0, i)) + e.slice(i) : e;
593			});
594			// rg prints files in thread-completion order; sort so output and paging are deterministic
595			const key = (e: string) => e.slice(0, Math.max(0, e.lastIndexOf(":")));
596			entries.sort((a, b) => byString(key(a), key(b)));
597			const paged = applyPaging(entries, limit, offset);
598			const out = paged.items.map((e) => {
599				const i = e.lastIndexOf(":");
600				return i > 0 ? displayPath(cwd, e.slice(0, i)) + e.slice(i) : e;
601			});
602			let numMatches = 0;
603			let numFiles = 0;
604			for (const e of entries) {
605				const i = e.lastIndexOf(":");
606				const n = Number.parseInt(e.slice(i + 1), 10);
607				if (i > 0 && !Number.isNaN(n)) {
608					numMatches += n;
609					numFiles += 1;
610				}
611			}
612			details = {
613				mode: "count",
614				numFiles,
615				filenames: [],
616				content: out.join("\n"),
617				numMatches,
618				...(paged.appliedLimit !== undefined && { appliedLimit: paged.appliedLimit }),
619				...(offset > 0 && { appliedOffset: offset }),
620			};
621		} else {
622			const files = splitNullOutput(run.lines, "files_with_matches").map(toAbs);
623			const stats = await Promise.allSettled(files.map((f) => stat(f)));
624			const sorted = files
625				.map((f, i) => {
626					const s = stats[i];
627					return [f, s.status === "fulfilled" ? (s.value.mtimeMs ?? 0) : 0] as const;
628				})
629				.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
630				.map((x) => x[0]);
631			const paged = applyPaging(sorted, limit, offset);
632			const filenames = paged.items.map((f) => displayPath(cwd, f));
633			details = {
634				mode: "files_with_matches",
635				filenames,
636				numFiles: filenames.length,
637				totalFiles: sorted.length,
638				...(paged.appliedLimit !== undefined && { appliedLimit: paged.appliedLimit }),
639				...(offset > 0 && { appliedOffset: offset }),
640			};
641		}
642		return { text: formatGrep(details), details };
643	}
644	
645	function emptyDetails(mode: GrepOutputMode): GrepDetails {
646		if (mode === "content") return { mode, numFiles: 0, filenames: [], content: "", numLines: 0, totalLines: 0 };
647		if (mode === "count") return { mode, numFiles: 0, filenames: [], content: "", numMatches: 0 };
648		return { mode, filenames: [], numFiles: 0, totalFiles: 0 };
649	}
650	
651	/** Claude Code's Grep tool_result text. */
652	export function formatGrep(d: GrepDetails): string {
653		const paging = pagingText(d.appliedLimit, d.appliedOffset);
654		if (d.mode === "content") {
655			const body = d.content || (d.appliedOffset && (d.totalLines ?? 0) > 0 ? "No entries at this offset" : "No matches found");
656			return paging ? `${body}\n\n[Showing results with pagination = ${paging}]` : body;
657		}
658		if (d.mode === "count") {
659			const matches = d.numMatches ?? 0;
660			const files = d.numFiles ?? 0;
661			const body = d.content || (matches > 0 ? "No entries at this offset" : "No matches found");
662			return `${body}\n\nFound ${matches} total ${matches === 1 ? "occurrence" : "occurrences"} across ${files} ${files === 1 ? "file" : "files"}.${paging ? ` with pagination = ${paging}` : ""}`;
663		}
664		if (d.numFiles === 0) {
665			return d.appliedOffset && (d.totalFiles ?? 0) > 0 ? `No entries at this offset. [Showing results with pagination = ${paging}]` : "No files found";
666		}
667		return `Found ${d.numFiles} ${d.numFiles === 1 ? "file" : "files"}${paging ? ` ${paging}` : ""}\n${d.filenames.join("\n")}`;
668	}
669	
670	export function registerGrep(pi: ExtensionAPI, _cc: CCContext): void {
671		pi.registerTool({
672			name: GREP_TOOL_NAME,
673			label: "Grep",
674			description: DESCRIPTION,
675			promptSnippet: "Search file contents with ripgrep (regex; glob/type filters; content, files_with_matches, count modes)",
676			parameters: grepSchema,
677			async execute(_toolCallId, params, signal, _onUpdate, ctx) {
678				const { text, details } = await executeGrep(params, ctx.cwd, signal);
679				return textResult<GrepDetails>(text, details);
680			},
681		});
682	}
