314	// ---------------------------------------------------------------------------------------------
315	// Input repair (Claude Code's coerceInput / validationErrorSteer for these tools)
316	// ---------------------------------------------------------------------------------------------
317	
318	const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
319	const nonEmpty = (v: unknown): v is string => typeof v === "string" && v.trim() !== "";
320	const hasTaskArray = (o: Record<string, unknown>) => "tasks" in o || "todos" in o;
321	const hasAgentParams = (o: Record<string, unknown>) => "prompt" in o || "subagent_type" in o;
322	
323	const CREATE_KEYS = new Set(["subject", "description", "activeForm", "metadata"]);
324	const CREATE_ALIASES: Array<[string[], string]> = [
325		[["title", "name"], "subject"],
326		[["content"], "description"],
327		[["active_form"], "activeForm"],
328	];
329	const UPDATE_ALIASES: Array<[string[], string]> = [
330		[["id", "task_id"], "taskId"],
331		[["active_form"], "activeForm"],
332	];
333	
334	/** A subject derived from a description: its first line, at most 80 characters, cut at a word boundary. */
335	export function subjectFromDescription(description: string): string {
336		const text = firstLine(description).trim();
337		const chars = Array.from(text);
338		if (chars.length <= 80) return text;
339		const head = chars.slice(0, 80).join("");
340		const cut = head.lastIndexOf(" ");
341		return (cut > 40 ? head.slice(0, cut) : head).trim();
342	}
343	
344	function firstLine(text: string): string {
345		return text.split("\n")[0];
346	}
347	
348	/** TaskCreate input repair: aliases, a `task` wrapper, a missing subject/description, unknown keys. */
349	export function coerceTaskCreateInput(input: unknown): Record<string, unknown> | null {
350		if (!isObj(input) || hasTaskArray(input)) return null;
351		const changes: string[] = [];
352		const r: Record<string, unknown> = { ...input };
353		if (hasAgentParams(r) && !(nonEmpty(r.subject) && nonEmpty(r.description))) return null;
354		if (!("subject" in r) && !("description" in r) && "task" in r) {
355			const task = r.task;
356			if (nonEmpty(task)) {
357				delete r.task;
358				r.description = task;
359				changes.push("task_wrapper_string");
360			} else if (isObj(task)) {
361				if (hasTaskArray(task)) return null;
362				if (hasAgentParams(task) && !(nonEmpty(task.subject) && nonEmpty(task.description))) return null;
363				delete r.task;
364				Object.assign(r, task);
365				changes.push("task_wrapper_object");
366			} else return null;
367		}
368		for (const [aliases, target] of CREATE_ALIASES) {
369			for (const alias of aliases) {
370				if (alias in r && !(target in r) && nonEmpty(r[alias])) {
371					r[target] = r[alias];
372					delete r[alias];
373					changes.push(`alias_${alias}`);
374				}
375			}
376		}
377		if (nonEmpty(r.subject) && !("description" in r)) {
378			r.description = r.subject;
379			changes.push("backfill_description");
380		} else if (nonEmpty(r.description) && !("subject" in r)) {
381			r.subject = subjectFromDescription(r.description);
382			changes.push("backfill_subject");
383		}
384		if (nonEmpty(r.subject) && nonEmpty(r.description)) {
385			for (const key of Object.keys(r)) {
386				if (!CREATE_KEYS.has(key)) {
387					delete r[key];
388					changes.push(`strip_${key}`);
389				}
390			}
391			if ("activeForm" in r && typeof r.activeForm !== "string") {
392				delete r.activeForm;
393				changes.push("drop_invalid_activeForm");
394			}
395			if ("metadata" in r && !isObj(r.metadata)) {
396				delete r.metadata;
397				changes.push("drop_invalid_metadata");
398			}
399		}
400		return changes.length ? r : null;
401	}
