403	/** TaskUpdate input repair: `id`/`task_id` → taskId, `active_form` → activeForm. */
404	export function coerceTaskUpdateInput(input: unknown): Record<string, unknown> | null {
405		if (!isObj(input)) return null;
406		const r: Record<string, unknown> = { ...input };
407		let changed = false;
408		for (const [aliases, target] of UPDATE_ALIASES) {
409			for (const alias of aliases) {
410				if (alias in r && !(target in r) && nonEmpty(r[alias])) {
411					r[target] = r[alias];
412					delete r[alias];
413					changed = true;
414				}
415			}
416		}
417		return changed ? r : null;
418	}
419	
420	function taskCreateSteer(input: unknown): string | null {
421		if (!isObj(input)) return null;
422		const task = isObj(input.task) ? input.task : null;
423		if (hasTaskArray(input) || (task !== null && hasTaskArray(task))) {
424			return "TaskCreate creates ONE task per call and has no `tasks` or `todos` parameter. Call TaskCreate once per task, passing `subject` (a brief title) and `description` (what needs to be done) as top-level string parameters.";
425		}
426		if ((hasAgentParams(input) || (task !== null && hasAgentParams(task))) && !(nonEmpty(input.subject) && nonEmpty(input.description))) {
427			return "This call used Agent-tool parameters (`prompt`/`subagent_type`). TaskCreate adds an item to the task list and takes `subject` and `description` string parameters. To delegate work to a subagent, use the Agent tool instead.";
428		}
429		return null;
430	}
