435	
436	function cloneTask(t: TaskItem): TaskItem {
437		const copy: TaskItem = { ...t, blocks: [...t.blocks], blockedBy: [...t.blockedBy] };
438		if (t.metadata) copy.metadata = { ...t.metadata };
439		return copy;
440	}
441	
442	/** In-memory task list with Claude Code's semantics (ids, dependencies, deletion). */
443	export class TaskStore {
444		private listeners = new Set<() => void>();
445		/** Called after a session that shares this store (a subagent) changed it. */
446		subscribe(fn: () => void): () => void {
447			this.listeners.add(fn);
448			return () => this.listeners.delete(fn);
449		}
450		notify(): void {
451			for (const fn of this.listeners) fn();
452		}
453	
454		private tasks = new Map<string, TaskItem>();
455		private highWaterMark = 0;
456	
457		constructor(state?: TaskListState) {
458			if (state) this.load(state);
459		}
460	
461		load(state: TaskListState): void {
462			this.tasks = new Map(state.tasks.map((t) => [t.id, cloneTask(t)]));
463			this.highWaterMark = state.highWaterMark ?? 0;
464		}
465	
466		snapshot(): TaskListState {
467			return { tasks: this.list().map(cloneTask), highWaterMark: this.highWaterMark };
468		}
469	
470		/** All tasks, sorted by numeric id. */
471		list(): TaskItem[] {
472			return [...this.tasks.values()].sort((a, b) => Number(a.id) - Number(b.id));
473		}
474	
475		get(id: string): TaskItem | undefined {
476			return this.tasks.get(id);
477		}
478	
479		create(fields: Omit<TaskItem, "id">): string {
480			const ids = [...this.tasks.keys()].map(Number).filter(Number.isFinite);
481			const id = String(Math.max(this.highWaterMark, 0, ...ids) + 1);
482			this.tasks.set(id, { id, ...fields });
483			this.highWaterMark = Number(id);
484			return id;
485		}
486	
487		update(id: string, fields: Partial<TaskItem>): void {
488			const t = this.tasks.get(id);
489			if (t) this.tasks.set(id, { ...t, ...fields, id });
490		}
491	
492		/** Delete a task and drop it from every other task's dependencies. */
493		delete(id: string): boolean {
494			const n = Number.parseInt(id, 10);
495			if (!Number.isNaN(n) && n > this.highWaterMark) this.highWaterMark = n;
496			if (!this.tasks.delete(id)) return false;
497			for (const t of this.tasks.values()) {
498				t.blocks = t.blocks.filter((b) => b !== id);
499				t.blockedBy = t.blockedBy.filter((b) => b !== id);
500			}
501			return true;
502		}
503	
504		/** `from` blocks `to` (both must exist). */
505		block(from: string, to: string): boolean {
506			const a = this.tasks.get(from);
507			const b = this.tasks.get(to);
508			if (!a || !b) return false;
509			if (!a.blocks.includes(to)) a.blocks = [...a.blocks, to];
510			if (!b.blockedBy.includes(from)) b.blockedBy = [...b.blockedBy, from];
511			return true;
512		}
513	}
