519	export function formatTaskGet(t: TaskItem | undefined): string {
520		if (!t) return "Task not found";
521		const lines = [`Task #${t.id}: ${t.subject}`, `Status: ${t.status}`, `Description: ${t.description}`];
522		if (t.blockedBy.length > 0) lines.push(`Blocked by: ${t.blockedBy.map((id) => `#${id}`).join(", ")}`);
523		if (t.blocks.length > 0) lines.push(`Blocks: ${t.blocks.map((id) => `#${id}`).join(", ")}`);
524		return lines.join("\n");
525	}
526	
527	export function formatTaskList(tasks: TaskItem[]): string {
528		const visible = tasks.filter((t) => !t.metadata?._internal);
529		if (visible.length === 0) return "No tasks found";
530		const completed = new Set(visible.filter((t) => t.status === "completed").map((t) => t.id));
531		return visible
532			.map((t) => {
533				const owner = t.owner ? ` (${t.owner})` : "";
534				const open = t.blockedBy.filter((id) => !completed.has(id));
535				const blocked = open.length > 0 ? ` [blocked by ${open.map((id) => `#${id}`).join(", ")}]` : "";
536				return `#${t.id} [${t.status}] ${t.subject}${owner}${blocked}`;
537			})
538			.join("\n");
539	}
540	
541	function mergeMetadata(current: Record<string, unknown> | undefined, patch: Record<string, unknown>): Record<string, unknown> {
542		const out = { ...current };
543		for (const [k, v] of Object.entries(patch)) {
544			if (v === null) delete out[k];
545			else out[k] = v;
546		}
547		return out;
548	}
549	
550	/** Apply a TaskUpdate call to the store and return Claude Code's result text. */
551	export function applyTaskUpdate(store: TaskStore, input: TaskUpdateInput): string {
552		const { taskId } = input;
553		const task = store.get(taskId);
554		if (!task) return "Task not found";
555		const before = cloneTask(task);
556		const updated: string[] = [];
557		const patch: Partial<TaskItem> = {};
558		if (input.subject !== undefined && input.subject !== before.subject) {
559			patch.subject = input.subject;
560			updated.push("subject");
561		}
562		if (input.description !== undefined && input.description !== before.description) {
563			patch.description = input.description;
564			updated.push("description");
565		}
566		if (input.activeForm !== undefined && input.activeForm !== before.activeForm) {
567			patch.activeForm = input.activeForm;
568			updated.push("activeForm");
569		}
570		if (input.owner !== undefined && input.owner !== before.owner) {
571			patch.owner = input.owner;
572			updated.push("owner");
573		}
574		if (input.metadata !== undefined) {
575			patch.metadata = mergeMetadata(before.metadata, input.metadata);
576			updated.push("metadata");
577		}
578		if (input.status !== undefined) {
579			if (input.status === "deleted") {
580				// other field changes in the same call are discarded, as in Claude Code
581				return store.delete(taskId) ? `Updated task #${taskId} deleted` : "Failed to delete task";
582			}
583			if (input.status !== before.status) {
584				patch.status = input.status;
585				updated.push("status");
586			}
587		}
588		if (Object.keys(patch).length > 0) store.update(taskId, patch);
589		if (input.addBlocks && input.addBlocks.length > 0) {
590			const added = input.addBlocks.filter((id) => !before.blocks.includes(id));
591			for (const id of added) store.block(taskId, id);
592			if (added.length > 0) updated.push("blocks");
593		}
594		if (input.addBlockedBy && input.addBlockedBy.length > 0) {
595			const added = input.addBlockedBy.filter((id) => !before.blockedBy.includes(id));
596			for (const id of added) store.block(id, taskId);
597			if (added.length > 0) updated.push("blockedBy");
598		}
599		return `Updated task #${taskId} ${updated.join(", ")}`;
600	}
