606	/**
607	 * Claude Code nudges the model when the task tools have not been used for a while: when at least
608	 * this many assistant content blocks (text and tool calls; thinking does not count) came after the
609	 * last TaskCreate/TaskUpdate call and after the last reminder.
610	 */
611	export const TASK_REMINDER_TURNS = 10;
612	
613	/** `details.kind` of injected task reminder messages. */
614	export const TASK_REMINDER_KIND = "task_reminder";
615	
616	/** Claude Code's reminder text, listing the current tasks. */
617	export function buildTaskReminderText(tasks: TaskItem[]): string {
618		let text =
619			"The task tools haven't been used recently. If you're working on tasks that would benefit from tracking progress, consider using TaskCreate to add new tasks and TaskUpdate to update task status (set to in_progress when starting, completed when done). Also consider cleaning up the task list if it has become stale. Only use these if relevant to the current work. This is just a gentle reminder - ignore if not applicable.\n";
620		if (tasks.length > 0) text += `\n\nHere are the existing tasks:\n\n${tasks.map((t) => `#${t.id}. [${t.status}] ${t.subject}`).join("\n")}`;
621		return text;
622	}
