624	/** Latest task list found in successful TaskCreate/TaskUpdate results of a session branch. */
625	export function taskListFromBranch(entries: readonly any[]): TaskListState | undefined {
626		let state: TaskListState | undefined;
627		for (const entry of entries) {
628			if (entry?.type !== "message") continue;
629			const msg = entry.message;
630			if (msg?.role !== "toolResult" || !MUTATING_TOOLS.has(msg.toolName) || msg.isError) continue;
631			const list = (msg.details as Partial<TaskToolDetails> | undefined)?.taskList;
632			if (list && Array.isArray(list.tasks)) state = list;
633		}
634		return state;
635	}
636	
637	function messageKey(m: any, index: number): string {
638		return `${index}:${m?.role}:${m?.timestamp ?? ""}:${m?.toolCallId ?? ""}`;
639	}
640	
641	function reminderMessage(content: string) {
642		return { role: "custom", customType: REMINDER_CUSTOM_TYPE, content, display: false, details: { kind: TASK_REMINDER_KIND }, timestamp: Date.now() };
643	}
