647	// ---------------------------------------------------------------------------------------------
648	
649	export function registerTaskTools(pi: ExtensionAPI, cc: CCContext): void {
650		// Foreground subagents share the parent's list; the parent owns persistence and host events.
651		const shared = cc.options.sharedTaskStore;
652		const store = shared ?? new TaskStore();
653		cc.taskStore = store;
654		/** Reminders injected so far, by the key of the message they follow (re-inserted on every call). */
655		let reminders = new Map<string, string>();
656	
657		const publish = () => {
658			const tasks = store.list().map(cloneTask);
659			cc.emit({ type: "todos_updated", todos: tasks.map(taskToTodo) });
660			cc.emit({ type: "tasks_updated", tasks });
661		};
662	
663		if (!shared) store.subscribe(() => publish());
664	
665		const reconstruct = (ctx: ExtensionContext) => {
666			if (shared) return; // the parent's branch is the source of truth
667			let entries: readonly any[] = [];
668			try {
669				entries = ctx.sessionManager?.getBranch?.() ?? [];
670			} catch {
671				entries = [];
672			}
673			store.load(taskListFromBranch(entries) ?? { tasks: [], highWaterMark: 0 });
674			reminders = new Map();
675			publish();
676		};
677	
678		// session_start covers startup, reload, new, resume and fork; session_tree covers /tree navigation.
679		pi.on("session_start", async (_event, ctx) => reconstruct(ctx));
680		pi.on("session_tree", async (_event, ctx) => reconstruct(ctx));
681	
682		const mutated = (text: string) => {
683			store.notify(); // owner publishes (also when a subagent sharing the store mutated it)
684			return textResult<TaskToolDetails>(text, { taskList: store.snapshot() });
685		};
686	
687		pi.registerTool({
688			name: TASK_CREATE_TOOL_NAME,
689			label: "TaskCreate",
690			description: TASK_CREATE_DESCRIPTION,
691			promptSnippet: "TaskCreate: add a task to the session task list",
692			parameters: TaskCreateParams as any,
693			prepareArguments: claudeInputValidator<TaskCreateInput>(TASK_CREATE_TOOL_NAME, TaskCreateSpec, { coerce: coerceTaskCreateInput, steer: taskCreateSteer }),
694			async execute(_toolCallId, params) {
695				const { subject, description, activeForm, metadata } = params as TaskCreateInput;
696				const id = store.create({ subject, description, activeForm, status: "pending", owner: undefined, blocks: [], blockedBy: [], metadata });
697				return mutated(`Task #${id} created successfully: ${subject}`);
698			},
699		});
700	
701		pi.registerTool({
702			name: TASK_GET_TOOL_NAME,
703			label: "TaskGet",
704			description: TASK_GET_DESCRIPTION,
705			promptSnippet: "TaskGet: show one task with its description and dependencies",
706			parameters: TaskGetParams as any,
707			prepareArguments: claudeInputValidator(TASK_GET_TOOL_NAME, TaskGetSpec),
708			async execute(_toolCallId, params) {
709				return textResult(formatTaskGet(store.get((params as { taskId: string }).taskId)));
710			},
711		});
712	
713		pi.registerTool({
714			name: TASK_LIST_TOOL_NAME,
715			label: "TaskList",
716			description: TASK_LIST_DESCRIPTION,
717			promptSnippet: "TaskList: list all tasks with status, owner and blockers",
718			parameters: TaskListParams as any,
719			prepareArguments: claudeInputValidator(TASK_LIST_TOOL_NAME, TaskListSpec),
720			async execute() {
