725		pi.registerTool({
726			name: TASK_UPDATE_TOOL_NAME,
727			label: "TaskUpdate",
728			description: TASK_UPDATE_DESCRIPTION,
729			promptSnippet: "TaskUpdate: change a task's status, fields or dependencies, or delete it",
730			parameters: TaskUpdateParams as any,
731			prepareArguments: claudeInputValidator<TaskUpdateInput>(TASK_UPDATE_TOOL_NAME, TaskUpdateSpec, { coerce: coerceTaskUpdateInput }),
