737		/*
738		 * Reminder. Claude Code adds it to the conversation as a persistent attachment. Here it is
739		 * injected in the `context` hook (synchronous with the model call it targets, branch-correct)
740		 * and remembered by the message it follows, so later calls see it at the same position (stable
741		 * prompt prefix) without storing it in the session.
742		 */
743		pi.on("context", async (event) => {
744			const input = event.messages as any[];
745			if (input.length === 0) return undefined;
746			const messages: any[] = [];
747			let sinceTaskTool = 0;
748			let sinceReminder = 0;
749			let reinserted = false;
750			input.forEach((m, i) => {
751				messages.push(m);
752				if (m?.role === "assistant" && Array.isArray(m.content)) {
753					for (const block of m.content) {
754						if (block?.type === "thinking" || block?.type === "redactedThinking") continue;
755						if (block?.type === "toolCall" && MUTATING_TOOLS.has(block.name)) sinceTaskTool = 0;
756						else sinceTaskTool++;
757						sinceReminder++;
758					}
759				}
760				const text = reminders.get(messageKey(m, i));
761				if (text !== undefined) {
762					messages.push(reminderMessage(text));
763					sinceReminder = 0;
764					reinserted = true;
765				}
766			});
767			if (sinceTaskTool >= TASK_REMINDER_TURNS && sinceReminder >= TASK_REMINDER_TURNS) {
768				const text = wrapReminder(buildTaskReminderText(store.list()));
769				reminders.set(messageKey(input.at(-1), input.length - 1), text);
770				messages.push(reminderMessage(text));
771				return { messages };
772			}
773			return reinserted ? { messages } : undefined;
774		});
775	}
