1	/**
2	 * Claude Code-compatible tool input validation.
3	 *
4	 * Claude Code validates tool input with zod (v4) and reports failures as
5	 * `InputValidationError: <text>`, where <text> is either a readable summary
6	 * ("<Tool> failed due to the following issue:\nThe required parameter `x` is missing") or, when every
7	 * issue is of a kind the summary does not describe (too_small, invalid_value, ...), zod's own
8	 * JSON dump of the issues. pi validates tool arguments with its own (TypeBox) validator before a
9	 * tool runs, with different wording, so tools that want Claude's exact errors validate in
10	 * `prepareArguments` with this module and throw (pi turns the throw into an error tool result).
11	 *
12	 * Only the subset of zod used by these tools' schemas is modelled.
13	 */
14	
15	export type Spec =
16		| { kind: "string" }
17		| { kind: "boolean"; default?: boolean }
18		| { kind: "enum"; values: readonly string[] }
19		| { kind: "literal"; value: string }
20		| { kind: "union"; options: Spec[] }
21		| { kind: "array"; items: Spec; min?: number; max?: number }
22		| { kind: "object"; props: Record<string, { spec: Spec; optional?: boolean }>; strict?: boolean; refine?: { check: (v: any) => boolean; message: string } }
23		/** z.record(z.string(), valueSpec) */
24		| { kind: "record"; value: Spec }
25		| { kind: "unknown" };
26	
27	export type Path = Array<string | number>;
28	export type ZodIssue = Record<string, unknown> & { code: string; path: Path; message: string };
29	
30	/** zod v4's name for a value's type (used in "received X"). */
31	function parsedType(v: unknown): string {
32		if (v === undefined) return "undefined";
33		if (v === null) return "null";
34		if (Array.isArray(v)) return "array";
35		if (typeof v === "number") return Number.isNaN(v) ? "nan" : "number";
36		return typeof v;
37	}
38	
39	const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
40	
41	function quote(v: string): string {
42		return JSON.stringify(v);
43	}
44	
45	function invalidType(expected: string, value: unknown, path: Path): ZodIssue {
46		return { expected, code: "invalid_type", path, message: `Invalid input: expected ${expected}, received ${parsedType(value)}` };
47	}
48	
49	/** zod v4 length checks also run on strings (with "characters" wording) when the type check failed. */
50	function lengthIssues(spec: { min?: number; max?: number }, value: unknown, path: Path): ZodIssue[] {
51		const out: ZodIssue[] = [];
52		let origin: string;
53		let unit: string;
54		if (Array.isArray(value)) {
55			origin = "array";
56			unit = "items";
57		} else if (typeof value === "string") {
58			origin = "string";
59			unit = "characters";
60		} else return out;
61		const len = value.length;
62		if (spec.min !== undefined && len < spec.min) {
63			out.push({ origin, code: "too_small", minimum: spec.min, inclusive: true, path, message: `Too small: expected ${origin} to have >=${spec.min} ${unit}` });
64		}
65		if (spec.max !== undefined && len > spec.max) {
66			out.push({ origin, code: "too_big", maximum: spec.max, inclusive: true, path, message: `Too big: expected ${origin} to have <=${spec.max} ${unit}` });
67		}
68		return out;
69	}
70	
71	/** Parse `value` against `spec`: returns the parsed value (defaults applied) and zod-style issues. */
72	export function parse(spec: Spec, value: unknown, path: Path = []): { value: unknown; issues: ZodIssue[] } {
73		switch (spec.kind) {
74			case "unknown":
75				return { value, issues: [] };
76			case "string":
77				return typeof value === "string" ? { value, issues: [] } : { value, issues: [invalidType("string", value, path)] };
78			case "boolean":
79				if (value === undefined && spec.default !== undefined) return { value: spec.default, issues: [] };
80				return typeof value === "boolean" ? { value, issues: [] } : { value, issues: [invalidType("boolean", value, path)] };
81			case "enum":
82				if (typeof value === "string" && spec.values.includes(value)) return { value, issues: [] };
83				return {
84					value,
85					issues: [{ code: "invalid_value", values: [...spec.values], path, message: `Invalid option: expected one of ${spec.values.map(quote).join("|")}` }],
86				};
87			case "literal":
88				if (value === spec.value) return { value, issues: [] };
89				return { value, issues: [{ code: "invalid_value", values: [spec.value], path, message: `Invalid input: expected ${quote(spec.value)}` }] };
90			case "union": {
91				const errors: ZodIssue[][] = [];
92				for (const option of spec.options) {
93					const r = parse(option, value, []);
94					if (r.issues.length === 0) return r;
95					errors.push(r.issues);
96				}
97				return { value, issues: [{ code: "invalid_union", errors, path, message: "Invalid input" }] };
98			}
99			case "array": {
100				const issues: ZodIssue[] = [];
101				let out: unknown = value;
102				if (!Array.isArray(value)) issues.push(invalidType("array", value, path));
103				else {
104					const items: unknown[] = [];
105					value.forEach((item, i) => {
106						const r = parse(spec.items, item, [...path, i]);
107						issues.push(...r.issues);
108						items.push(r.value);
109					});
110					out = items;
111				}
112				issues.push(...lengthIssues(spec, value, path));
113				return { value: out, issues };
114			}
115			case "record": {
116				if (!isPlainObject(value)) return { value, issues: [invalidType("record", value, path)] };
117				const issues: ZodIssue[] = [];
118				const out: Record<string, unknown> = {};
119				for (const [k, v] of Object.entries(value)) {
120					const r = parse(spec.value, v, [...path, k]);
121					issues.push(...r.issues);
122					out[k] = r.value;
123				}
124				return { value: out, issues };
125			}
126			case "object": {
127				if (!isPlainObject(value)) return { value, issues: [invalidType("object", value, path)] };
128				const issues: ZodIssue[] = [];
129				const out: Record<string, unknown> = {};
130				for (const [key, { spec: propSpec, optional }] of Object.entries(spec.props)) {
131					const v = value[key];
132					if (v === undefined && optional) continue;
133					const r = parse(propSpec, v, [...path, key]);
134					issues.push(...r.issues);
135					if (r.value !== undefined) out[key] = r.value;
136				}
137				const unknownKeys = Object.keys(value).filter((k) => !(k in spec.props));
138				if (unknownKeys.length > 0) {
139					if (spec.strict !== false) {
140						issues.push({
141							code: "unrecognized_keys",
142							keys: unknownKeys,
143							path,
144							message: `Unrecognized key${unknownKeys.length > 1 ? "s" : ""}: ${unknownKeys.map(quote).join(", ")}`,
145						});
146					}
147				}
148				if (issues.length === 0 && spec.refine && !spec.refine.check(out)) {
149					issues.push({ code: "custom", path, message: spec.refine.message });
150				}
151				return { value: out, issues };
152			}
153		}
154	}
155	
156	/** `a.b[0].c` (Claude Code's rendering of an issue path). */
157	function formatPath(path: Path): string {
158		return path.reduce<string>((acc, part, i) => (typeof part === "number" ? `${acc}[${part}]` : i === 0 ? String(part) : `${acc}.${part}`), "");
159	}
160	
161	const MAX_LISTED_ISSUES = 20;
162	const MAX_ISSUE_MESSAGE = 500;
163	
164	function truncate(s: string, max: number): string {
165		return s.length > max ? `${s.slice(0, max)}…` : s;
166	}
167	
168	/** Claude Code's text for a failed schema validation (without the "InputValidationError: " prefix). */
169	export function formatIssues(toolName: string, issues: ZodIssue[]): string {
170		const missing = issues.filter((i) => i.code === "invalid_type" && i.message.includes("received undefined")).map((i) => formatPath(i.path));
171		const unexpected = issues.filter((i) => i.code === "unrecognized_keys").flatMap((i) => (i.keys as string[]).map((k) => formatPath([...i.path, k])));
172		const wrongType = issues
173			.filter((i) => i.code === "invalid_type" && !i.message.includes("received undefined"))
174			.map((i) => ({ param: formatPath(i.path), expected: i.expected as string, received: i.message.match(/received (\w+)/)?.[1] ?? "unknown" }));
175		const other = issues
176			.filter((i) => i.code !== "invalid_type" && i.code !== "unrecognized_keys")
177			.map((i) => {
178				const p = formatPath(i.path);
179				const subject = p === "" ? "The input" : `The parameter \`${p}\``;
180				const msg = truncate(i.message.replace(/^Invalid input(?:: |$)/, ""), MAX_ISSUE_MESSAGE);
181				if (msg !== "") return `${subject} is invalid: ${msg}`;
182				return i.code === "invalid_union" ? `${subject} matches none of the accepted forms` : `${subject} is invalid`;
183			});
184		const lines: string[] = [
185			...missing.map((p) => `The required parameter \`${p}\` is missing`),
186			...unexpected.map((p) => `An unexpected parameter \`${p}\` was provided`),
187			...wrongType.map(({ param, expected, received }) => `The parameter \`${param}\` type is expected as \`${expected}\` but provided as \`${received}\``),
188		];
189		if (lines.length === 0) return JSON.stringify(issues, null, 2);
190		lines.push(...other.slice(0, MAX_LISTED_ISSUES));
191		const more = other.length - MAX_LISTED_ISSUES;
192		if (more > 0) lines.push(`(${more} more ${more === 1 ? "issue" : "issues"} not listed)`);
193		return `${toolName} failed due to the following ${lines.length > 1 ? "issues" : "issue"}:\n${lines.join("\n")}`;
194	}
195	
196	export class InputValidationError extends Error {
197		constructor(message: string) {
198			super(message);
199			this.name = "InputValidationError";
200		}
201	}
202	
203	export interface ValidateOptions {
204		/** Claude Code's `coerceInput`: repairs common input shapes before validation (null = unchanged). */
205		coerce?: (input: unknown) => unknown | null;
206		/** Claude Code's `validationErrorSteer`: extra guidance put before the issue text. Gets the raw input. */
207		steer?: (input: unknown, issues: ZodIssue[]) => string | null;
208	}
209	
210	/**
211	 * Validate raw tool arguments like Claude Code does. Returns the parsed input, or throws an
212	 * InputValidationError whose message is Claude Code's model-facing text.
213	 */
214	export function validateInput<T>(toolName: string, spec: Spec, raw: unknown, opts: ValidateOptions = {}): T {
215		const coerced = opts.coerce?.(raw) ?? null;
216		const input = coerced === null ? raw : coerced;
217		const { value, issues } = parse(spec, input);
218		if (issues.length === 0) return value as T;
219		let text = formatIssues(toolName, issues);
220		const steer = opts.steer?.(raw, issues);
221		if (steer) text = `${steer}\n\n${text}`;
222		throw new InputValidationError(`InputValidationError: ${text}`);
223	}
224	
225	/** prepareArguments implementation for pi tools: validate like Claude Code, pass the parsed input on. */
226	export function claudeInputValidator<T>(toolName: string, spec: Spec, opts: ValidateOptions = {}): (args: unknown) => T {
227		return (args) => validateInput<T>(toolName, spec, args, opts);
228	}
