166	/** Claude Code's Read input coercion: unwrap 1-element arrays, drop negative offsets / non-positive limits, `length` → limit. */
167	export function coerceReadInput(args: unknown): unknown {
168		if (typeof args !== "object" || args === null || Array.isArray(args)) return args;
169		const n: Record<string, unknown> = { ...(args as Record<string, unknown>) };
170		const num = (v: unknown): number | undefined => {
171			if (typeof v === "number") return Number.isFinite(v) ? v : undefined;
172			if (typeof v === "string" && /^[-+]?\d+$/.test(v.trim())) return Number(v);
173			return undefined;
174		};
175		if (Array.isArray(n.offset) && n.offset.length === 1) n.offset = n.offset[0];
176		if (Array.isArray(n.limit) && n.limit.length === 1) n.limit = n.limit[0];
177		const off = num(n.offset);
178		if (off !== undefined && off < 0) delete n.offset;
179		const lim = num(n.limit);
180		if (lim !== undefined && lim <= 0) delete n.limit;
181		if ("length" in n) {
182			const len = num(n.length);
183			if (!("limit" in n) && len !== undefined && len > 0) n.limit = len;
184			delete n.length;
185		}
186		delete n.description;
