247		) {
248			super(
249				`File content (${tokenCount} tokens) exceeds maximum allowed tokens (${maxTokens}). Use offset and limit parameters to read specific portions of the file, or search for specific content instead of reading the whole file.`,
250			);
251		}
252	}
253	
254	/** Context room for this read (Claude Code's contextRoom): allow_large may raise the caps up to it. */
255	interface Room {
256		roomTokens: number | undefined;
257		raised: { maxTokens: number; maxSizeBytes: number } | undefined;
258	}
259	
260	const BYTES_PER_TOKEN = 4;
261	
262	function contextRoom(ctx: ExtensionContext | undefined, maxTokens: number): Room {
263		let usage: { tokens: number | null; contextWindow: number } | undefined;
264		try {
265			usage = (ctx as any)?.getContextUsage?.();
266		} catch {
267			usage = undefined;
268		}
269		if (!usage || !(usage.contextWindow > 0)) return { roomTokens: undefined, raised: undefined };
270		// Claude Code's auto-compact threshold: window minus output reserve (≤20k) minus a 13k buffer.
271		const threshold = usage.contextWindow - Math.min(20000, Math.floor(usage.contextWindow / 10)) - 13000;
272		const roomTokens = Math.max(0, Math.floor((threshold - (usage.tokens ?? 0)) * 0.7));
273		if (roomTokens <= maxTokens) return { roomTokens, raised: undefined };
274		return { roomTokens, raised: { maxTokens: roomTokens, maxSizeBytes: Math.max(MAX_READ_SIZE_BYTES, roomTokens * BYTES_PER_TOKEN * 3) } };
275	}
276	
277	function allowLargeSuffix(room: Room, optedIn: boolean, need: { bytes?: number; tokens?: number }): string {
278		if (room.roomTokens === undefined) return optedIn ? ALLOW_LARGE_UNAVAILABLE : "";
279		if (optedIn || room.raised === undefined) return ALLOW_LARGE_NO_ROOM;
280		const fits = (need.bytes === undefined || need.bytes <= room.raised.maxSizeBytes) && (need.tokens === undefined || need.tokens <= room.raised.maxTokens);
281		return fits ? ALLOW_LARGE_HINT : ALLOW_LARGE_NO_ROOM;
282	}
283	
284	function withAllowLargeSuffix(err: unknown, room: () => Room, optedIn: boolean): unknown {
285		if (err instanceof FileTooLargeError) return new Error(err.message + allowLargeSuffix(room(), optedIn, { bytes: err.sizeInBytes }));
286		if (err instanceof SelectedRangeTooLargeError) return new Error(err.message + allowLargeSuffix(room(), optedIn, { bytes: err.selectedBytes }));
287		if (err instanceof TokenLimitError) return new Error(err.message + allowLargeSuffix(room(), optedIn, { tokens: err.tokenCount }));
288		return err;
289	}
290	
291	/** Claude Code's rough token estimate: chars / 4 (chars / 2 for JSON). */
292	export function estimateTokens(text: string, ext: string): number {
293		const per = ext === "json" || ext === "jsonl" || ext === "jsonc" ? 2 : 4;
294		return Math.round(text.length / per);
295	}
296	
297	/**
298	 * Token check of a read result. Claude Code asks the API for an exact count when the estimate is
299	 * above a quarter of the cap; pi tools have no such endpoint, so the estimate is used throughout.
300	 */
301	function checkTokens(text: string, ext: string, maxTokens: number, allowLarge: boolean): number | undefined {
302		const est = estimateTokens(text, ext);
303		const tokens = allowLarge && est ? Math.max(est, Math.ceil(Buffer.byteLength(text) / 2)) : est;
304		if (!tokens || tokens <= maxTokens / 4) return tokens || undefined;
305		if (tokens > maxTokens) throw new TokenLimitError(tokens, maxTokens);
306		return tokens;
307	}
