309	// ---------------------------------------------------------------------------------------------
310	// Text file reading (Claude Code's readFileInRange)
311	// ---------------------------------------------------------------------------------------------
312	
313	interface TextRange {
314		content: string;
315		lineCount: number;
316		totalLines: number;
317		notText?: NotText;
318		/** The raw file (not set for streamed files). */
319		raw?: Buffer;
320	}
321	
322	function decodeText(buf: Buffer): { text: string; notText?: NotText } {
323		if (buf.length >= 2 && buf[0] === 0xff && buf[1] === 0xfe) return { text: buf.toString("utf16le") };
324		let notText: NotText | undefined;
325		if (buf.length >= 2 && buf[0] === 0xfe && buf[1] === 0xff) notText = "utf16be";
326		else if (buf.subarray(0, 8000).includes(0)) notText = "nul";
327		else if (!isUtf8(buf)) notText = "not_utf8";
328		return { text: buf.toString("utf8"), notText };
329	}
330	
331	/** Select lines [offset, offset+limit) of `text` (0-based offset). */
332	export function selectLines(text: string, offset: number, limit: number | undefined, maxSelectedBytes?: number): { content: string; lineCount: number; totalLines: number } {
333		const body = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
334		if (offset === 0 && limit === undefined && maxSelectedBytes === undefined) {
335			let content = body.includes("\r") ? body.replaceAll("\r\n", "\n") : body;
336			if (content.endsWith("\r")) content = content.slice(0, -1);
337			let n = 1;
338			for (let i = content.indexOf("\n"); i !== -1; i = content.indexOf("\n", i + 1)) n++;
339			return { content, lineCount: n, totalLines: n };
340		}
341		const end = limit !== undefined ? offset + limit : Infinity;
342		const selected: string[] = [];
343		let selectedBytes = 0;
344		let index = 0;
345		let pos = 0;
346		const take = (line: string) => {
347			if (line.endsWith("\r")) line = line.slice(0, -1);
348			if (maxSelectedBytes !== undefined) {
349				const next = selectedBytes + (selected.length > 0 ? 1 : 0) + Buffer.byteLength(line);
350				if (next > maxSelectedBytes) throw new SelectedRangeTooLargeError(next, maxSelectedBytes);
351				selectedBytes = next;
352			}
353			selected.push(line);
354		};
355		for (let nl = body.indexOf("\n", pos); nl !== -1; nl = body.indexOf("\n", pos)) {
356			if (index >= offset && index < end) take(body.slice(pos, nl));
357			index++;
358			pos = nl + 1;
359		}
360		if (index >= offset && index < end) take(body.slice(pos));
361		index++;
362		return { content: selected.join("\n"), lineCount: selected.length, totalLines: index };
363	}
364	
365	/** Streaming variant for large files (UTF-8 only, like Claude Code). */
366	async function streamLines(
367		absPath: string,
368		offset: number,
369		limit: number | undefined,
370		maxBytes: number | undefined,
371		maxSelectedBytes: number | undefined,
372		signal?: AbortSignal,
373	): Promise<TextRange> {
374		const end = limit !== undefined ? offset + limit : Infinity;
375		const selected: string[] = [];
376		let selectedBytes = 0;
377		let index = 0;
378		let total = 0;
379		let partial = "";
380		let first = true;
381		const decoder = new TextDecoder("utf-8");
382		const take = (line: string) => {
383			if (line.endsWith("\r")) line = line.slice(0, -1);
384			if (maxSelectedBytes !== undefined) {
385				const next = selectedBytes + (selected.length > 0 ? 1 : 0) + Buffer.byteLength(line);
386				if (next > maxSelectedBytes) throw new SelectedRangeTooLargeError(next, maxSelectedBytes);
387				selectedBytes = next;
388			}
389			selected.push(line);
390		};
391		const stream = createReadStream(absPath, { highWaterMark: STREAM_CHUNK_BYTES, signal });
392		try {
393			for await (const chunk of stream as AsyncIterable<Buffer>) {
394				let s = decoder.decode(chunk, { stream: true });
395				if (first) {
396					first = false;
397					if (s.charCodeAt(0) === 0xfeff) s = s.slice(1);
398				}
399				total += Buffer.byteLength(s);
400				if (maxBytes !== undefined && total > maxBytes) throw new FileTooLargeError(total, maxBytes);
401				s = partial + s;
402				let pos = 0;
403				for (let nl = s.indexOf("\n", pos); nl !== -1; nl = s.indexOf("\n", pos)) {
404					if (index >= offset && index < end) take(s.slice(pos, nl));
405					index++;
406					pos = nl + 1;
407				}
408				partial = s.slice(pos);
409			}
410		} finally {
411			stream.destroy();
412		}
413		partial += decoder.decode();
414		if (index >= offset && index < end) take(partial);
415		index++;
416		return { content: selected.join("\n"), lineCount: selected.length, totalLines: index };
417	}
418	
419	async function readTextRange(
420		absPath: string,
421		size: number,
422		offset: number,
423		limit: number | undefined,
424		maxBytes: number | undefined,
425		maxSelectedBytes: number | undefined,
426		signal?: AbortSignal,
427	): Promise<TextRange> {
428		if (maxSelectedBytes !== undefined && size <= maxSelectedBytes) maxSelectedBytes = undefined;
429		if (size >= STREAM_THRESHOLD_BYTES) return streamLines(absPath, offset, limit, maxBytes, maxSelectedBytes, signal);
430		if (maxBytes !== undefined && size > maxBytes) throw new FileTooLargeError(size, maxBytes);
431		const buf = await readFile(absPath, { signal });
432		if (maxBytes !== undefined && buf.length > maxBytes) throw new FileTooLargeError(buf.length, maxBytes);
433		const { text, notText } = decodeText(buf);
434		return { ...selectLines(text, offset, limit, maxSelectedBytes), notText, raw: buf };
435	}
436	
437	/** Cut a too-large whole-file read down to what fits the token cap (Claude Code's paged view). */
438	function pageDown(content: string, tokenCount: number, maxTokens: number): { text: string; lines: number; byChars: boolean } {
439		const lines = content.split("\n");
440		const charsPerToken = Math.max(0.5, content.length / Math.max(1, tokenCount));
441		const tokensOf = (s: string) => s.length / charsPerToken;
442		let n = Math.max(1, Math.min(lines.length, Math.floor(((lines.length * maxTokens) / Math.max(1, tokenCount)) * 0.85)));
443		let text = lines.slice(0, n).join("\n");
444		for (let i = 0; i < 6; i++) {
445			if (tokensOf(text) <= maxTokens || n <= 1) break;
446			n = Math.max(1, Math.floor(n * 0.7));
447			text = lines.slice(0, n).join("\n");
448		}
449		if (tokensOf(text) > maxTokens || text.trim() === "") {
450			let chars = Math.max(1, Math.floor(maxTokens * charsPerToken * 0.85));
451			for (let i = 0; i < 6; i++) {
452				text = content.slice(0, chars);
453				if (tokensOf(text) <= maxTokens) break;
454				chars = Math.max(1, Math.floor(chars * 0.7));
455			}
456			const last = text.charCodeAt(text.length - 1);
457			if (last >= 0xd800 && last <= 0xdbff) text = text.slice(0, -1);
458			return { text, lines: text.split("\n").length, byChars: true };
459		}
460		return { text, lines: n, byChars: false };
461	}
462	
463	function escapeForReminder(s: string): string {
464		return s.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
465	}
466	
467	async function readTextFile(
468		cc: CCContext,
469		ctx: ExtensionContext | undefined,
470		absPath: string,
471		size: number,
472		params: { offset: number; limit: number | undefined; allowLarge: boolean },
473		signal?: AbortSignal,
474	): Promise<AgentToolResult<ReadToolDetails>> {
475		const ext = extname(absPath).toLowerCase().slice(1);
476		const baseMaxTokens = maxReadTokens();
477		const room = () => contextRoom(ctx, baseMaxTokens);
478		const optIn = params.allowLarge ? room() : undefined;
479		const maxBytes = optIn?.raised?.maxSizeBytes ?? MAX_READ_SIZE_BYTES;
480		const maxTokens = optIn?.raised?.maxTokens ?? baseMaxTokens;
481		const { offset, limit } = params;
482		const startIndex = offset === 0 ? 0 : offset - 1;
483		const wholeFile = offset <= 1 && limit === undefined;
484	
485		let range: TextRange;
486		try {
487			range = await readTextRange(
488				absPath,
489				size,
490				startIndex,
491				limit,
492				limit === undefined ? maxBytes : undefined,
493				limit === undefined ? undefined : Math.max(baseMaxTokens * SELECTED_BYTES_PER_TOKEN, optIn?.raised?.maxSizeBytes ?? 0),
494				signal,
495			);
496		} catch (err) {
497			throw withAllowLargeSuffix(err, room, params.allowLarge);
498		}
499		throwIfAborted(signal);
500	
501		let content = range.content;
502		let numLines = range.lineCount;
503		let recordedLimit = limit;
504		let banner: string | undefined;
505		try {
506			const checked = optIn?.raised ? addLineNumbers(content, Math.max(1, offset)) : content;
507			const tokens = checkTokens(checked, ext, maxTokens, optIn?.raised !== undefined);
508			if (optIn?.raised && tokens !== undefined) {
509				const cap = room().raised?.maxTokens ?? baseMaxTokens;
510				if (tokens > cap) throw new TokenLimitError(tokens, cap);
511			}
512		} catch (err) {
513			if (!(err instanceof TokenLimitError) || !wholeFile) throw withAllowLargeSuffix(err, room, params.allowLarge);
514			const hint = allowLargeSuffix(room(), params.allowLarge, { tokens: err.tokenCount });
515			const capNote = optIn?.raised && err.maxTokens > baseMaxTokens ? `allow_large had room for ${err.maxTokens} tokens this turn` : `cap ${baseMaxTokens}`;
516			const full = content;
517			const paged = pageDown(full, err.tokenCount, baseMaxTokens);
518			content = paged.text;
519			numLines = paged.lines;
520			recordedLimit = numLines;
521			banner =
522				!paged.byChars && numLines < range.totalLines
523					? `[Truncated: PARTIAL view — ${absPath}: showing lines 1-${numLines} of ${range.totalLines} total (${err.tokenCount} tokens, ${capNote}). Call Read with offset=${numLines + 1} limit=${numLines} for the next page, or Grep to find a specific section.${hint} Do NOT answer from this page alone if the answer may be further in the file.]`
524					: `[Truncated: PARTIAL view — ${absPath}: showing the first ${content.length} of ${full.length} characters (${err.tokenCount} tokens, ${capNote}); this file has very long lines and cannot be paginated by line. Use Grep to find a specific section, or Read with offset/limit to page through it.${hint} Do NOT answer from this excerpt alone if the answer may be elsewhere in the file.]`;
525		}
526	
527		const startLine = banner !== undefined ? Math.max(1, offset) : offset;
528		const partial = banner !== undefined || startIndex > 0 || numLines < range.totalLines;
529		try {
530			cc.fileState.recordRead(absPath, range.raw ?? (await readFile(absPath)), { partial, truncated: banner !== undefined, offset, limit: recordedLimit });
531		} catch {
532			// the file vanished between reading and recording: nothing to track
533		}
534	
535		let text: string;
536		if (content) text = addLineNumbers(content, startLine);
537		else if (numLines >= 1 && range.totalLines > 1) text = formatNumberedLine(startLine, "");
538		else if (numLines >= 1 || range.totalLines === 0) text = EMPTY_FILE_REMINDER;
539		else
540			text = `<system-reminder>Warning: the file exists but is shorter than the provided offset (${startLine}). The file has ${range.totalLines} lines.</system-reminder>`;
541		if (range.notText) text += `\n\n${notTextNote(range.notText)}`;
542		// Claude Code sends the truncation banner as a separate system reminder after the tool result.
543		if (banner !== undefined) text += `\n\n<system-reminder>\n${escapeForReminder(banner)}\n</system-reminder>`;
544		return {
545			content: [{ type: "text", text }],
546			details: { filePath: absPath, kind: "text", startLine, numLines, totalLines: range.totalLines, truncated: banner !== undefined },
547		};
548	}
