553	
554	const IMAGE_EXTENSIONS = new Set(["png", "jpg", "jpeg", "gif", "webp"]);
555	
556	export function sniffImageMimeType(buf: Buffer): string | undefined {
557		if (buf.length < 4) return undefined;
558		if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) return "image/png";
559		if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return "image/jpeg";
560		if (buf.length >= 6 && buf.toString("latin1", 0, 4) === "GIF8" && (buf[4] === 0x37 || buf[4] === 0x39) && buf[5] === 0x61) return "image/gif";
561		if (buf.length >= 12 && buf.toString("latin1", 0, 4) === "RIFF" && buf.toString("latin1", 8, 12) === "WEBP") return "image/webp";
562		return undefined;
563	}
564	
565	/** What a file that should be an image actually looks like (for the error message). */
566	function describeBytes(buf: Buffer): string {
567		const head = buf.subarray(0, 32);
568		const ascii = head.toString("latin1").replace(/[^\x20-\x7e]/g, ".");
569		const lower = ascii.toLowerCase();
570		if (lower.includes("<!doctype") || lower.includes("<html")) return `HTML document (starts with "${ascii.slice(0, 24)}")`;
571		if (lower.startsWith("<?xml") || lower.startsWith("<svg")) return `XML/SVG document (starts with "${ascii.slice(0, 24)}")`;
572		if (lower.startsWith("{") || lower.startsWith("[")) return `JSON/text (starts with "${ascii.slice(0, 24)}")`;
573		if (head.subarray(0, 4).toString("latin1").toLowerCase() === "%pdf") return "PDF document";
574		if (head[0] === 0x50 && head[1] === 0x4b && head[2] === 3 && head[3] === 4) return "ZIP archive (Office documents such as .pptx/.docx/.xlsx are ZIPs)";
575		return `unrecognized bytes (hex: ${head.subarray(0, 8).toString("hex").replace(/(..)/g, "$1 ").trim()})`;
576	}
577	
578	interface ResizedImage {
579		data: string;
580		mimeType: string;
581		originalWidth: number;
582		originalHeight: number;
583		width: number;
584		height: number;
585		wasResized: boolean;
586	}
587	interface PiImageResizeModule {
588		resizeImage?: (img: ImageContent) => Promise<ResizedImage | null>;
589	}
590	
591	let resizeModulePromise: Promise<PiImageResizeModule> | undefined;
592	
593	/**
594	 * pi's image resizer (Photon/WASM, same one pi's built-in read tool uses) is internal (not in the
595	 * package "exports"), so load it by file URL relative to the resolved package. Falls back to
596	 * "no resizing" if that fails.
597	 */
598	function loadPiImageResize(): Promise<PiImageResizeModule> {
599		resizeModulePromise ??= (async () => {
600			const candidates: string[] = [];
601			try {
602				const indexUrl = import.meta.resolve("@earendil-works/pi-coding-agent");
603				candidates.push(new URL("./utils/image-resize.js", indexUrl).href);
604			} catch {
605				// ignore
606			}
607			const starts = [process.cwd()];
608			try {
609				starts.push(dirname(fileURLToPath(import.meta.url)));
610			} catch {
611				// ignore
612			}
613			for (const start of starts) {
614				let dir = start;
615				for (let i = 0; i < 10; i++) {
616					const p = join(dir, "node_modules", "@earendil-works", "pi-coding-agent", "dist", "utils", "image-resize.js");
617					if (existsSync(p)) candidates.push(pathToFileURL(p).href);
618					const parent = dirname(dir);
619					if (parent === dir) break;
620					dir = parent;
621				}
622			}
623			for (const href of candidates) {
624				try {
625					const mod = await import(href);
626					if (typeof mod.resizeImage === "function") return mod as PiImageResizeModule;
627				} catch {
628					// try next
629				}
630			}
631			return {};
632		})();
633		return resizeModulePromise;
634	}
