636	/** Prepare an image for inline use: resize via pi if possible, else pass through if small enough. */
637	export async function prepareImage(buffer: Buffer, mimeType: string): Promise<{ image?: ImageContent; note?: string }> {
638		const base64 = buffer.toString("base64");
639		const { resizeImage } = await loadPiImageResize();
640		if (resizeImage) {
641			try {
642				const r = await resizeImage({ type: "image", data: base64, mimeType });
643				if (r) {
644					const resized = r.originalWidth !== r.width || r.originalHeight !== r.height;
645					return {
646						image: { type: "image", data: r.data, mimeType: r.mimeType },
647						note:
648							resized && r.width > 0 && r.height > 0
649								? `[Image: original ${r.originalWidth}x${r.originalHeight}, displayed at ${r.width}x${r.height}. Multiply coordinates by ${(r.originalWidth / r.width).toFixed(2)} to map to original image.]`
650								: undefined,
651					};
652				}
653			} catch {
654				// fall through to raw handling
655			}
656		}
657		if (base64.length <= MAX_INLINE_IMAGE_BASE64) return { image: { type: "image", data: base64, mimeType } };
658		return { note: "[Image omitted: could not be resized below the inline image size limit.]" };
659	}
660	
661	async function readImage(absPath: string, size: number): Promise<AgentToolResult<ReadToolDetails>> {
662		if (size > MAX_IMAGE_FILE_BYTES) {
663			throw new Error(
664				`File is too large to read as an image (the limit is ${formatBytes(MAX_IMAGE_FILE_BYTES)}): ${absPath}. If it is an image, resize it or export a smaller copy, then read that.`,
665			);
666		}
667		const buffer = await readFile(absPath);
668		if (buffer.length === 0) throw new Error(`Image file is empty: ${absPath}`);
669		const mime = sniffImageMimeType(buffer);
670		if (!mime) {
671			throw new Error(
672				`File has an image extension but its content is not a valid PNG/JPEG/GIF/WebP. Detected: ${describeBytes(buffer)}. This usually means a download saved an error/login page instead of the image. Use \`file "${absPath}"\` to confirm, or read it as text with Bash (e.g. \`head -c 500\`).`,
673			);
674		}
675		const { image, note } = await prepareImage(buffer, mime);
676		// Claude Code's tool result is the image alone; the resize note follows as a separate message.
677		const content: Content[] = [];
678		if (image) content.push(image);
679		if (note) content.push({ type: "text", text: note });
680		return { content, details: { filePath: absPath, kind: "image" } };
681	}
