687	function run(cmd: string, args: string[], signal?: AbortSignal): Promise<{ stdout: string; stderr: string }> {
688		return new Promise((resolve, reject) => {
689			execFile(cmd, args, { signal, maxBuffer: 64 * 1024 * 1024, encoding: "utf8", timeout: 120000 }, (err, stdout, stderr) => {
690				if (err) {
691					(err as any).stderr = stderr;
692					reject(err);
693				} else resolve({ stdout, stderr });
694			});
695		});
