698	/** Parse "3" or "1-5" ("4-" is open-ended: lastPage = Infinity). Returns null when invalid. */
699	export function parsePageRange(pages: string): { firstPage: number; lastPage: number } | null {
700		const m = /^(\d{1,9})(?:\s*(-)\s*(\d{1,9})?)?$/.exec(pages.trim());
701		if (!m) return null;
702		const first = Number(m[1]);
703		const last = m[3] ? Number(m[3]) : m[2] ? Infinity : first;
704		if (first < 1 || last < first) return null;
705		return { firstPage: first, lastPage: last };
706	}
707	
708	/** Validate the pages parameter like Claude Code (also for non-PDF files). Returns an error message. */
709	export function validatePages(pages: string): string | undefined {
710		const r = parsePageRange(pages);
711		if (!r) {
712			return `Invalid pages parameter: "${pages}". Give one page ("3") or one range ("1-5"), not a list. To read several pages or ranges, read each one separately. Pages are 1-indexed.`;
713		}
714		const count = r.lastPage === Infinity ? PDF_MAX_PAGES_PER_REQUEST + 1 : r.lastPage - r.firstPage + 1;
715		if (count > PDF_MAX_PAGES_PER_REQUEST) return `Page range "${pages}" exceeds maximum of ${PDF_MAX_PAGES_PER_REQUEST} pages per request. Please use a smaller range.`;
716		return undefined;
717	}
