719	async function pdfPageCount(absPath: string, signal?: AbortSignal): Promise<number | undefined> {
720		try {
721			const { stdout } = await run("pdfinfo", [absPath], signal);
722			const m = /^Pages:\s+(\d+)/m.exec(stdout);
723			return m ? Number(m[1]) : undefined;
724		} catch (err: any) {
725			if (err?.name === "AbortError") throw new Error("Operation aborted");
726			return undefined;
727		}
728	}
