730	const PDFTOPPM_MISSING =
731		"pdftoppm is not installed. Install poppler-utils (e.g. `brew install poppler` or `apt-get install poppler-utils`) to enable PDF page rendering.";
732	
733	/** Render pages as JPEGs (pdftoppm -jpeg -r 100) and return them in page order. */
734	async function renderPdfPages(absPath: string, size: number, range: { firstPage: number; lastPage: number } | undefined, signal?: AbortSignal): Promise<Buffer[]> {
735		if (size === 0) throw new Error(`PDF file is empty: ${absPath}`);
736		if (size > PDF_MAX_EXTRACT_BYTES) throw new Error(`PDF file exceeds maximum allowed size for text extraction (${formatBytes(PDF_MAX_EXTRACT_BYTES)}).`);
737		const tmp = await mkdtemp(join(tmpdir(), "pi-cc-pdf-"));
738		try {
739			const args = ["-jpeg", "-r", "100"];
740			if (range?.firstPage) args.push("-f", String(range.firstPage));
741			if (range?.lastPage && range.lastPage !== Infinity) args.push("-l", String(range.lastPage));
742			args.push(absPath, join(tmp, "page"));
743			try {
744				await run("pdftoppm", args, signal);
745			} catch (err: any) {
746				if (err?.code === "ENOENT") throw new Error(PDFTOPPM_MISSING);
747				if (err?.name === "AbortError" || signal?.aborted) throw new Error("Operation aborted");
748				const stderr = String(err?.stderr ?? "");
749				if (/password/i.test(stderr)) throw new Error("PDF is password-protected. Please provide an unprotected version.");
750				const wrong = /Wrong page range given.*last page \((\d+)\)/i.exec(stderr);
751				if (wrong && range) {
752					const total = Number(wrong[1]);
753					if (total === 0) throw new Error("PDF reports 0 pages (empty page tree). The PDF may be invalid.");
754					const what =
755						range.lastPage === Infinity
756							? `pages ${range.firstPage}-`
757							: range.firstPage === range.lastPage
758								? `page ${range.firstPage}`
759								: `pages ${range.firstPage}-${range.lastPage}`;
760					throw new Error(
761						`Requested ${what} is outside the document (PDF has ${total} ${plural(total, "page")}). Use a range within 1-${total}, maximum ${PDF_MAX_PAGES_PER_REQUEST} pages per request (e.g. pages: "1-${Math.min(total, PDF_MAX_PAGES_PER_REQUEST)}").`,
762					);
763				}
764				if (/damaged|corrupt|invalid|Couldn't (find trailer dictionary|read xref table)/i.test(stderr)) {
765					throw new Error("PDF file is corrupted or invalid.");
766				}
767				throw new Error(`pdftoppm failed: ${stderr.trim() || err?.message || String(err)}`);
768			}
769			const files = (await readdir(tmp)).filter((f) => f.endsWith(".jpg")).sort();
770			if (files.length === 0) throw new Error("pdftoppm produced no output pages. The PDF may be invalid.");
771			return await Promise.all(files.map((f) => readFile(join(tmp, f))));
772		} finally {
773			await rm(tmp, { recursive: true, force: true }).catch(() => {});
774		}
775	}
