777	async function pageImages(jpegs: Buffer[], firstPage: number): Promise<Content[]> {
778		const out: Content[] = [];
779		for (let i = 0; i < jpegs.length; i++) {
780			const { image, note } = await prepareImage(jpegs[i], "image/jpeg");
781			if (image) out.push(image);
782			else out.push({ type: "text", text: `[Page ${firstPage + i} could not be processed as an image${note ? `: ${note}` : ""}]` });
783		}
784		return out;
785	}
