787	async function readPdf(absPath: string, size: number, pages: string | undefined, signal?: AbortSignal): Promise<AgentToolResult<ReadToolDetails>> {
788		if (pages !== undefined) {
789			const error = validatePages(pages);
790			if (error) throw new Error(error);
791			const range = parsePageRange(pages)!;
792			const jpegs = await renderPdfPages(absPath, size, range, signal);
793			const content: Content[] = [{ type: "text", text: `PDF pages extracted: ${jpegs.length} page(s) from ${absPath} (${formatBytes(size)})` }];
794			content.push(...(await pageImages(jpegs, range.firstPage)));
795			return { content, details: { filePath: absPath, kind: "pdf", pages: [range.firstPage, range.firstPage + jpegs.length - 1] } };
796		}
797	
798		const totalPages = await pdfPageCount(absPath, signal);
799		if (totalPages !== undefined && totalPages > PDF_MAX_PAGES_WITHOUT_RANGE) {
800			throw new Error(
801				`This PDF has ${totalPages} pages, which is too many to read at once. Use the pages parameter to read specific page ranges (e.g., pages: "1-5"). Maximum ${PDF_MAX_PAGES_PER_REQUEST} pages per request.`,
802			);
803		}
804		if (size === 0) throw new Error(`PDF file is empty: ${absPath}`);
805		if (size > PDF_MAX_WHOLE_BYTES) throw new Error(`PDF file exceeds maximum allowed size of ${formatBytes(PDF_MAX_WHOLE_BYTES)}.`);
806		const fh = await open(absPath, "r");
807		try {
808			const head = Buffer.alloc(5);
809			await fh.read(head, 0, 5, 0);
810			if (!head.toString("ascii").startsWith("%PDF-")) throw new Error(`File is not a valid PDF (missing %PDF- header): ${absPath}`);
811		} finally {
812			await fh.close();
813		}
814		// Claude Code attaches the PDF itself as a document block; pi tool results carry text and images
815		// only, so the pages are attached as rendered images (falling back to extracted text).
816		const content: Content[] = [{ type: "text", text: `PDF file read: ${absPath} (${formatBytes(size)})` }];
817		try {
818			content.push(...(await pageImages(await renderPdfPages(absPath, size, undefined, signal), 1)));
819		} catch (err: any) {
820			if (signal?.aborted) throw new Error("Operation aborted");
821			try {
822				const { stdout } = await run("pdftotext", ["-layout", "-enc", "UTF-8", absPath, "-"], signal);
823				const pageTexts = stdout.split("\f");
824				if (pageTexts.length > 1 && pageTexts[pageTexts.length - 1].trim() === "") pageTexts.pop();
825				content.push({ type: "text", text: pageTexts.map((t, i) => `<page number="${i + 1}">\n${t.replace(/\s+$/, "")}\n</page>`).join("\n") });
826			} catch {
827				throw err instanceof Error ? err : new Error(String(err));
828			}
829		}
830		return { content, details: { filePath: absPath, kind: "pdf", totalPages } };
831	}
