837	interface NotebookOutput {
838		output_type: string;
839		text: string;
840		image?: { image_data: string; media_type: string };
841	}
842	interface NotebookCell {
843		cellType: string;
844		source: string;
845		execution_count?: unknown;
846		cell_id: string;
847		language?: string;
848		outputs?: NotebookOutput[];
849	}
850	
851	const joinSource = (src: unknown): string => (Array.isArray(src) ? src.join("") : typeof src === "string" ? src : "");
852	
853	function isValidNotebook(nb: any): boolean {
854		const cells = nb?.cells;
855		return (
856			Array.isArray(cells) &&
857			!cells.some((c: any) => c === null || typeof c !== "object" || (typeof c.source !== "string" && !(Array.isArray(c.source) && c.source.every((s: unknown) => typeof s === "string"))))
858		);
859	}
860	
861	function notebookImage(data: Record<string, unknown>): NotebookOutput["image"] {
862		for (const mime of ["image/png", "image/jpeg"]) {
863			const raw = data[mime];
864			if (typeof raw !== "string") continue;
865			const b64 = raw.replace(/\s/g, "");
866			if (!sniffImageMimeType(Buffer.from(b64, "base64"))) return undefined;
867			return { image_data: b64, media_type: mime };
868		}
869		return undefined;
870	}
871	
872	function processOutput(out: any): NotebookOutput | undefined {
873		switch (out?.output_type) {
874			case "stream":
875				return { output_type: out.output_type, text: joinSource(out.text) };
876			case "execute_result":
877			case "display_data": {
878				const data = out.data && typeof out.data === "object" ? out.data : undefined;
879				return { output_type: out.output_type, text: joinSource(data?.["text/plain"]), image: data ? notebookImage(data) : undefined };
880			}
881			case "error":
882				return {
883					output_type: out.output_type,
884					text: `${out.ename}: ${out.evalue}\n${Array.isArray(out.traceback) ? out.traceback.join("\n") : ""}`,
885				};
886			default:
887				return undefined;
888		}
889	}
890	
891	function processCell(cell: any, index: number, language: string): NotebookCell {
892		const id = cell.id ?? `cell-${index}`;
893		const out: NotebookCell = {
894			cellType: cell.cell_type,
895			source: joinSource(cell.source),
896			execution_count: cell.cell_type === "code" ? cell.execution_count || undefined : undefined,
897			cell_id: id,
898		};
899		if (cell.cell_type === "code") out.language = language;
900		if (cell.cell_type === "code" && Array.isArray(cell.outputs) && cell.outputs.length > 0) {
901			const outputs = cell.outputs.map(processOutput).filter((o: NotebookOutput | undefined): o is NotebookOutput => o !== undefined);
902			let total = 0;
903			const tooLarge = outputs.some((o: NotebookOutput) => {
904				total += o.text.length + (o.image?.image_data.length ?? 0);
905				return total > NOTEBOOK_MAX_OUTPUT_CHARS;
906			});
907			out.outputs = tooLarge
908				? [{ output_type: "stream", text: `Outputs are too large to include. Use Bash with: cat <notebook_path> | jq '.cells[${index}].outputs'` }]
909				: outputs;
910		}
911		return out;
912	}
