914	/** Bun/JavaScriptCore-style JSON.parse messages (what Claude Code reports), from V8's. */
915	function jscJsonError(err: unknown): string {
916		const msg = err instanceof Error ? err.message : String(err);
917		if (/Unexpected end of JSON input/.test(msg)) return "JSON Parse error: Unexpected EOF";
918		if (/Expected property name or '}'/.test(msg)) return "JSON Parse error: Expected '}'";
919		const tok = /Unexpected token '?(.)'?/.exec(msg);
920		if (tok) return `JSON Parse error: Unrecognized token '${tok[1]}'`;
921		return msg;
922	}
