924	async function readNotebook(absPath: string, size: number): Promise<{ result: AgentToolResult<ReadToolDetails>; raw: Buffer }> {
925		if (size > NOTEBOOK_MAX_FILE_BYTES) {
926			throw new Error(`Notebook file exceeds the maximum size this tool can read (${formatBytes(NOTEBOOK_MAX_FILE_BYTES)}). ${NOTEBOOK_JQ_HINT}`);
927		}
928		const raw = await readFile(absPath);
929		let nb: any;
930		try {
931			nb = JSON.parse(raw.toString("utf8"));
932		} catch (err) {
933			throw new Error(`Notebook file is not valid JSON (it may be truncated, corrupted, or still being written): ${jscJsonError(err)}`);
934		}
935		if (!isValidNotebook(nb)) {
936			throw new Error('Notebook file is not a valid Jupyter notebook (top-level "cells" must be an array of cell objects, each with a string or string-array "source").');
937		}
938		const language: string = nb.metadata?.language_info?.name ?? "python";
939		const cells: NotebookCell[] = nb.cells.map((c: any, i: number) => processCell(c, i, language));
940	
941		const json = JSON.stringify(cells);
942		const bytes = Buffer.byteLength(json);
943		if (bytes > MAX_READ_SIZE_BYTES) {
944			throw new Error(`Notebook content (${formatBytes(bytes)}) exceeds maximum allowed size (${formatBytes(MAX_READ_SIZE_BYTES)}). ${NOTEBOOK_JQ_HINT}`);
945		}
946		checkTokens(json, "ipynb", maxReadTokens(), false);
947	
948		const blocks: Content[] = [];
949		const push = (b: Content) => {
950			const last = blocks.at(-1);
951			if (last && last.type === "text" && b.type === "text") last.text += `\n${b.text}`;
952			else blocks.push(b);
953		};
954		for (const cell of cells) {
955			let meta = "";
956			if (cell.cellType !== "code") meta += `<cell_type>${cell.cellType}</cell_type>`;
957			if (cell.language !== "python" && cell.cellType === "code") meta += `<language>${cell.language}</language>`;
958			push({ type: "text", text: `<cell id="${cell.cell_id}">${meta}${cell.source}</cell id="${cell.cell_id}">` });
959			for (const o of cell.outputs ?? []) {
960				if (o.text) push({ type: "text", text: `\n${o.text}` });
961				if (o.image) push({ type: "image", data: o.image.image_data, mimeType: o.image.media_type });
962			}
963		}
964		if (blocks.length === 0) blocks.push({ type: "text", text: NO_OUTPUT });
965		return { result: { content: blocks, details: { filePath: absPath, kind: "notebook", cells: cells.length } }, raw };
966	}
