978	function hasBinaryExtension(absPath: string): boolean {
979		const ext = absPath.slice(absPath.lastIndexOf(".")).toLowerCase();
980		if (!BINARY_EXTENSIONS.has(ext)) return false;
981		const plain = extname(absPath).toLowerCase().slice(1);
982		return !(IMAGE_EXTENSIONS.has(plain) || plain === "pdf");
