985	const BLOCKING_DEVICES = new Set([
986		"/dev/zero",
987		"/dev/random",
988		"/dev/urandom",
989		"/dev/full",
990		"/dev/stdin",
991		"/dev/tty",
992		"/dev/console",
993		"/dev/stdout",
994		"/dev/stderr",
995		"/dev/fd/0",
996		"/dev/fd/1",
997		"/dev/fd/2",
998	]);
