1000	function isBlockingDevice(p: string): boolean {
1001		if (BLOCKING_DEVICES.has(p)) return true;
1002		if (p.startsWith("/proc/") && (p.endsWith("/fd/0") || p.endsWith("/fd/1") || p.endsWith("/fd/2"))) return true;
1003		return /^\/proc\/[^/]+\/(environ|cmdline|auxv|maps|mem|stat)$/.test(p);
1004	}
