1006	/** A sibling with the same name but another (or no) extension. */
1007	async function findSimilarFile(absPath: string): Promise<string | undefined> {
1008		const dir = dirname(absPath);
1009		const stem = basename(absPath, extname(absPath));
1010		try {
1011			const entries = await readdir(dir);
1012			return entries.find((name) => /^(\.[\p{L}\p{N}_+~#-]{1,32})?$/u.test(extname(name).normalize("NFC")) && basename(name, extname(name)) === stem && join(dir, name) !== absPath);
1013		} catch {
1014			return undefined;
1015		}
1016	}
