1018	/** A path under cwd's parent but outside cwd whose cwd-relative twin exists. */
1019	async function findUnderCwd(absPath: string, cwd: string): Promise<string | undefined> {
1020		const parent = dirname(cwd);
1021		let p = absPath;
1022		try {
1023			p = join(await realpath(dirname(absPath)), basename(absPath));
1024		} catch {
1025			// keep as is
1026		}
1027		const prefix = parent === sep ? sep : parent + sep;
1028		if (!p.startsWith(prefix) || p.startsWith(cwd + sep) || p === cwd) return undefined;
1029		const candidate = join(cwd, relative(parent, p));
1030		try {
1031			await stat(candidate);
1032			return candidate;
1033		} catch {
1034			return undefined;
1035		}
1036	}
