1038	async function missingFileError(absPath: string, cwd: string): Promise<Error> {
1039		let msg = `File does not exist. Note: your current working directory is ${cwd}.`;
1040		const inCwd = await findUnderCwd(absPath, cwd);
1041		const similar = inCwd ? undefined : await findSimilarFile(absPath);
1042		if (inCwd) msg += ` Did you mean ${inCwd}?`;
1043		else if (similar) msg += ` Did you mean ${similar}?`;
1044		return new Error(msg);
1045	}
