1047	/** macOS screenshot names use U+202F (narrow no-break space) before AM/PM; models usually type a plain space. */
1048	function alternateScreenshotPath(absPath: string): string | undefined {
1049		const base = basename(absPath);
1050		const alt = base.replace(/ (AM|PM)(\.[A-Za-z0-9]+)$/, " $1$2");
1051		if (alt === base) return undefined;
1052		return join(dirname(absPath), alt);
1053	}
