1059	export function registerRead(pi: ExtensionAPI, cc: CCContext): void {
1060		pi.registerTool({
1061			name: "Read",
1062			label: "Read",
1063			description: DESCRIPTION,
1064			promptSnippet: "Read files (text, images, PDFs, Jupyter notebooks)",
1065			parameters: readSchema,
1066			prepareArguments: (args: unknown) => coerceReadInput(args) as ReadParams,
1067			async execute(_toolCallId, rawParams, signal, _onUpdate, ctx): Promise<AgentToolResult<ReadToolDetails>> {
1068				throwIfAborted(signal);
1069				const params = rawParams as ReadParams;
1070				if (typeof params.file_path !== "string") throw new Error("file_path is required.");
1071				const cwd = ctx?.cwd ?? process.cwd();
1072	
1073				// validateInput (same order as Claude Code)
1074				if (params.pages !== undefined) {
1075					const error = validatePages(params.pages);
1076					if (error) throw new Error(error);
1077				}
1078				let absPath = resolvePath(cwd, params.file_path);
1079				if (hasBinaryExtension(absPath)) {
1080					throw new Error(
1081						`This tool cannot read binary files. The file appears to be a binary ${extname(absPath).toLowerCase()} file. Use a skill for this file type if one is available, or a shell command or script that can read the format.`,
1082					);
1083				}
1084				if (isBlockingDevice(absPath)) throw new Error(`Cannot read '${params.file_path}': this device file would block or produce infinite output.`);
1085	
1086				const ext = extname(absPath).toLowerCase().slice(1);
1087				const isNotebook = ext === "ipynb";
1088				let offset = params.offset ?? 1;
1089				let limit = params.limit;
1090				if (isNotebook) {
1091					offset = 1;
1092					limit = undefined;
1093				}
1094	
1095				// Unchanged since the last Read of the same range: point back to that result.
1096				const rec = cc.fileState.get(absPath);
1097				if (rec && rec.source === "read" && !rec.truncated && !rec.contentNotInModelContext && rec.offset !== undefined && rec.offset === offset && rec.limit === limit) {
1098					try {
1099						const st = await stat(absPath);
1100						if (Math.floor(st.mtimeMs) === rec.timestamp) {
1101							return { content: [{ type: "text", text: WASTED_CALL_MESSAGE }], details: { filePath: absPath, kind: "file_unchanged" } };
1102						}
1103					} catch {
1104						// fall through to a normal read
1105					}
1106				}
1107	
1108				let st;
1109				try {
1110					st = await stat(absPath);
1111				} catch (err: any) {
1112					if (err?.code !== "ENOENT" && err?.code !== "ENOTDIR") throw err;
1113					const alt = alternateScreenshotPath(absPath);
1114					if (alt && existsSync(alt)) {
1115						absPath = alt;
1116						st = await stat(absPath);
1117					} else {
1118						throw await missingFileError(absPath, cwd);
1119					}
1120				}
1121				if (st.isDirectory()) throw new Error(`EISDIR: illegal operation on a directory, read '${absPath}'`);
1122				throwIfAborted(signal);
1123	
1124				if (isNotebook) {
1125					if (!st.isFile()) throw new Error("Notebook path is not a regular file (device, FIFO, or socket).");
1126					const { result, raw } = await readNotebook(absPath, st.size);
1127					try {
1128						cc.fileState.recordRead(absPath, raw, { offset, limit });
1129					} catch {
1130						// vanished meanwhile
1131					}
1132					return result;
1133				}
1134	
1135				let looksLikeImage = IMAGE_EXTENSIONS.has(ext);
1136				if (!looksLikeImage && ext === "" && st.isFile()) {
1137					const fh = await open(absPath, "r");
1138					try {
1139						const head = Buffer.alloc(16);
1140						const { bytesRead } = await fh.read(head, 0, 16, 0);
1141						looksLikeImage = sniffImageMimeType(head.subarray(0, bytesRead)) !== undefined;
1142					} finally {
1143						await fh.close();
1144					}
1145				}
1146				if (looksLikeImage) return readImage(absPath, st.size);
1147				if (ext === "pdf") return readPdf(absPath, st.size, params.pages, signal);
1148				if (!st.isFile()) throw new Error(`${absPath} is not a regular file.`);
1149				return readTextFile(cc, ctx, absPath, st.size, { offset, limit, allowLarge: params.allow_large === true }, signal);
1150			},
1151		});
1152	}
