51	// ---------------------------------------------------------------------------------------------
52	// String matching (ported from Claude Code)
53	// ---------------------------------------------------------------------------------------------
54	
55	const LSQ = "‘";
56	const RSQ = "’";
57	const LDQ = "“";
58	const RDQ = "”";
59	const ESCAPE_RE = /\\u[0-9a-fA-F]{4}/;
60	const NON_ASCII_RE = /[\u0080-￿]/;
61	
62	export function normalizeQuotes(s: string): string {
63		return s.replaceAll(LSQ, "'").replaceAll(RSQ, "'").replaceAll(LDQ, '"').replaceAll(RDQ, '"');
64	}
65	
66	function decodeEscapes(s: string): string {
67		return s.replace(/(\\\\)|\\u([0-9a-fA-F]{4})/g, (m, bs, hex) => (bs !== undefined ? m : String.fromCharCode(parseInt(hex, 16))));
68	}
69	
70	function escapeRegexChar(c: string): string {
71		return c.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
72	}
73	
74	/** Regex source matching `s` with every non-ASCII char written as a \uXXXX escape (any hex case). */
75	function escapedPattern(s: string): string {
76		let out = "";
77		for (let i = 0; i < s.length; i++) {
78			const code = s.charCodeAt(i);
79			if (code >= 128) {
80				out += "\\\\u";
81				for (const h of code.toString(16).padStart(4, "0")) out += h >= "a" ? `[${h}${h.toUpperCase()}]` : h;
82			} else out += escapeRegexChar(s[i]);
83		}
84		return out;
85	}
86	
87	function escapedLength(s: string): number {
88		let n = 0;
89		for (let i = 0; i < s.length; i++) if (s.charCodeAt(i) >= 128) n++;
90		return s.length + 5 * n;
91	}
92	
93	function backslashesBefore(s: string, idx: number): number {
94		let n = 0;
95		while (s[idx - 1 - n] === "\\") n++;
96		return n;
97	}
98	
99	/** Find `needle` in `haystack` where the haystack spells its non-ASCII chars as \uXXXX escapes. */
100	function findEscapedForm(needle: string, haystack: string): string | null {
101		if (backslashesBefore(needle, needle.length) % 2 === 1) return null;
102		const escapeOffsets = needle[0] === "\\" ? [0] : [];
103		let pos = 0;
104		for (let i = 0; i < needle.length; i++) {
105			if (needle.charCodeAt(i) >= 128) {
106				escapeOffsets.push(pos);
107				pos += 6;
108			} else pos += 1;
109		}
110		try {
111			const re = new RegExp(escapedPattern(needle), "g");
112			for (let m = re.exec(haystack); m !== null; m = re.exec(haystack)) {
113				const at = m.index;
114				if (escapeOffsets.every((o) => backslashesBefore(haystack, at + o) % 2 === 0)) return haystack.indexOf(m[0]) === at ? m[0] : null;
115				re.lastIndex = at + 1;
116			}
117			return null;
118		} catch {
119			return null;
120		}
121	}
122	
123	/**
124	 * The string in `file` that `oldString` refers to: exact match, else the same text with curly
125	 * quotes, else with \uXXXX escapes decoded or applied. Null when nothing matches.
126	 */
127	export function findActualString(file: string, oldString: string): string | null {
128		if (file.includes(oldString)) return oldString;
129		const idx = normalizeQuotes(file).indexOf(normalizeQuotes(oldString));
130		if (idx !== -1) return file.substring(idx, idx + oldString.length);
131		if (ESCAPE_RE.test(oldString)) {
132			const decoded = decodeEscapes(oldString);
133			if (decoded !== oldString && file.includes(decoded)) return decoded;
134		}
135		if (NON_ASCII_RE.test(oldString)) {
136			if (escapedLength(oldString) > file.length || !file.includes("\\u")) return null;
137			return findEscapedForm(oldString, file);
138		}
139		return null;
140	}
141	
142	function isOpeningContext(chars: string[], i: number): boolean {
143		if (i === 0) return true;
144		const p = chars[i - 1];
145		return p === " " || p === "\t" || p === "\n" || p === "\r" || p === "(" || p === "[" || p === "{" || p === "—" || p === "–";
146	}
147	
148	function curlDoubleQuotes(s: string): string {
149		const chars = [...s];
150		return chars.map((c, i) => (c === '"' ? (isOpeningContext(chars, i) ? LDQ : RDQ) : c)).join("");
151	}
152	
153	function curlSingleQuotes(s: string): string {
154		const chars = [...s];
155		return chars
156			.map((c, i) => {
157				if (c !== "'") return c;
158				const prev = i > 0 ? chars[i - 1] : undefined;
159				const next = i < chars.length - 1 ? chars[i + 1] : undefined;
160				if (prev !== undefined && next !== undefined && /\p{L}/u.test(prev) && /\p{L}/u.test(next)) return RSQ;
161				return isOpeningContext(chars, i) ? LSQ : RSQ;
162			})
163			.join("");
164	}
165	
166	/** When old_string matched only via curly-quote normalization, give new_string the file's quote style. */
167	export function preserveQuoteStyle(oldString: string, actualOld: string, newString: string): string {
168		if (oldString === actualOld) return newString;
169		const hasDouble = actualOld.includes(LDQ) || actualOld.includes(RDQ);
170		const hasSingle = actualOld.includes(LSQ) || actualOld.includes(RSQ);
171		if (!hasDouble && !hasSingle) return newString;
172		let out = newString;
173		if (hasDouble) out = curlDoubleQuotes(out);
174		if (hasSingle) out = curlSingleQuotes(out);
175		return out;
176	}
177	
178	/** When old_string matched via \uXXXX escapes (either direction), spell new_string the same way. */
179	export function preserveEscapeStyle(oldString: string, actualOld: string, newString: string): string {
180		if (oldString === actualOld) return newString;
181		if (NON_ASCII_RE.test(oldString) && escapedLength(oldString) === actualOld.length && findEscapedForm(oldString, actualOld) !== null) {
182			const spelled = new Map<number, string>();
183			let upper = 0;
184			let lower = 0;
185			for (let i = 0, j = 0; i < oldString.length; i++) {
186				const code = oldString.charCodeAt(i);
187				if (code >= 128) {
188					const hex = actualOld.slice(j + 2, j + 6);
189					spelled.set(code, hex);
190					for (const h of hex) {
191						if (h >= "a" && h <= "f") lower++;
192						else if (h >= "A" && h <= "F") upper++;
193					}
194					j += 6;
195				} else j += 1;
196			}
197			return newString.replace(/[\u0080-￿]/g, (c) => {
198				const code = c.charCodeAt(0);
199				const known = spelled.get(code);
200				if (known !== undefined) return "\\u" + known;
201				const hex = code.toString(16).padStart(4, "0");
202				return "\\u" + (upper > lower ? hex.toUpperCase() : hex);
203			});
204		}
205		if (ESCAPE_RE.test(oldString) && decodeEscapes(oldString) === actualOld) return decodeEscapes(newString);
206		return newString;
207	}
208	
209	export type EditOutcome = "applies" | "ambiguous" | "no_match";
210	
211	export function editOutcome(file: string, oldString: string, replaceAll: boolean): EditOutcome {
212		if (oldString === "") return "no_match";
213		const actual = findActualString(file, oldString);
214		if (!actual) return "no_match";
215		if (!replaceAll) {
216			const first = file.indexOf(actual);
217			if (file.indexOf(actual, first + actual.length) !== -1) return "ambiguous";
218		}
219		return "applies";
220	}
221	
222	class EditApplyError extends Error {}
223	
224	/**
225	 * Replace `oldString` (already resolved to the file's spelling) with `newString`. Deleting text
226	 * that ends a line also removes that line's newline.
227	 */
228	export function applyEdit(content: string, oldString: string, newString: string, replaceAll = false): string {
229		if (oldString === "") {
230			if (newString === content) throw new EditApplyError("String not found in file. Failed to apply edit.");
231			return newString;
232		}
233		const rep = (s: string, find: string) => (replaceAll ? s.replaceAll(find, () => newString) : s.replace(find, () => newString));
234		const updated =
235			newString === "" && !oldString.endsWith("\n") && content.includes(oldString + "\n") ? rep(content, oldString + "\n") : rep(content, oldString);
236		if (updated === content) throw new EditApplyError("String not found in file. Failed to apply edit.");
237		return updated;
238	}
239	
240	function addBomLike(original: string | null | undefined, next: string): string {
241		return next !== "" && original?.charCodeAt(0) === 0xfeff && next.charCodeAt(0) !== 0xfeff ? `﻿${next}` : next;
242	}
243	
244	// ---------------------------------------------------------------------------------------------
245	// "File does not exist" suggestions
246	// ---------------------------------------------------------------------------------------------
247	
248	async function exists(p: string): Promise<boolean> {
249		try {
250			await stat(p);
251			return true;
252		} catch {
253			return false;
254		}
255	}
256	
257	/** A path outside cwd (but under its parent) that exists when re-rooted under cwd. */
258	async function suggestUnderCwd(absPath: string, cwd: string): Promise<string | undefined> {
259		const parent = dirname(cwd);
260		let p = absPath;
261		try {
262			p = join(await realpath(dirname(absPath)), basename(absPath));
263		} catch {}
264		const prefix = parent === sep ? sep : parent + sep;
265		if (!p.startsWith(prefix) || p.startsWith(cwd + sep) || p === cwd) return undefined;
266		const candidate = join(cwd, relative(parent, p));
267		return (await exists(candidate)) ? candidate : undefined;
268	}
269	
270	const EXT_RE = /^(\.[\p{L}\p{N}_+~#-]{1,32})?$/u;
271	
272	/** A sibling with the same name but another extension. */
273	async function suggestOtherExtension(absPath: string): Promise<string | undefined> {
274		try {
275			const dir = dirname(absPath);
276			const base = basename(absPath, extname(absPath));
277			const entries = await readdir(dir);
278			return entries.find((name) => EXT_RE.test(extname(name).normalize("NFC")) && basename(name, extname(name)) === base && join(dir, name) !== absPath);
279		} catch {
280			return undefined;
281		}
282	}
283	
284	async function fileNotFoundMessage(absPath: string, cwd: string): Promise<string> {
285		let msg = `File does not exist. ${CWD_NOTE} ${cwd}.`;
286		const suggestion = (await suggestUnderCwd(absPath, cwd)) ?? (await suggestOtherExtension(absPath));
287		if (suggestion) msg += ` Did you mean ${suggestion}?`;
288		return msg;
289	}
290	
291	function formatSize(bytes: number): string {
292		const units = ["bytes", "KB", "MB", "GB", "TB"];
293		let n = bytes;
294		let u = 0;
295		while (n >= 1024 && u < units.length - 1) {
296			n /= 1024;
297			u++;
298		}
299		return u === 0 ? `${bytes} bytes` : `${Number.isInteger(n) ? n : n.toFixed(1)}${units[u]}`;
300	}
