303	// Registration
304	// ---------------------------------------------------------------------------------------------
305	
306	export function registerEdit(pi: ExtensionAPI, cc: CCContext): void {
307		pi.registerTool({
308			name: "Edit",
309			label: "Edit",
310			description: DESCRIPTION,
311			promptSnippet: "Make exact string replacements in files",
312			parameters: editSchema,
313			async execute(_toolCallId, params, signal, _onUpdate, ctx): Promise<AgentToolResult<EditToolDetails>> {
314				if (signal?.aborted) throw new Error("Operation aborted");
315				const filePath = params.file_path;
316				const oldString = params.old_string;
317				const newStringIn = params.new_string;
318				const replaceAll = params.replace_all === true;
319				if (typeof filePath !== "string" || typeof oldString !== "string" || typeof newStringIn !== "string") {
320					throw new Error("file_path, old_string and new_string are required strings.");
321				}
322				const cwd = ctx?.cwd ?? process.cwd();
323				const absPath = resolvePath(cwd, filePath);
324	
325				return withFileMutationQueue(absPath, async () => {
326					if (signal?.aborted) throw new Error("Operation aborted");
327					// ---- validation (same order as Claude Code) ----
328					if (oldString === newStringIn) throw new Error("No changes to make: old_string and new_string are exactly the same.");
329					try {
330						const st = await stat(absPath);
331						if (st.size > MAX_EDIT_FILE_BYTES) {
332							throw new Error(`File is too large to edit (${formatSize(st.size)}). Maximum editable file size is ${formatSize(MAX_EDIT_FILE_BYTES)}.`);
333						}
334					} catch (err: any) {
335						if (err?.code !== "ENOENT") throw err;
336					}
337	
338					let existing: Awaited<ReturnType<typeof readExistingText>>;
339					try {
340						existing = await readExistingText(absPath);
341					} catch (err: any) {
342						throw new Error(`Error calling tool (Edit): ${err?.message ?? String(err)}`);
343					}
344					const rec = cc.fileState.get(absPath);
345	
346					if (existing === null) {
347						if (oldString !== "") throw new Error(await fileNotFoundMessage(absPath, cwd));
348					} else if (oldString === "") {
349						if (stripBom(existing.content).trim() !== "") throw new Error("Cannot create new file - file already exists.");
350					} else {
351						if (absPath.endsWith(".ipynb")) throw new Error(NOT_A_NOTEBOOK_TOOL);
352						const text = stripBom(existing.content);
353						if (rec && cc.fileState.isStale(absPath, text) && editOutcome(text, oldString, replaceAll) !== "applies") {
354							throw new Error(FILE_MODIFIED_SINCE_READ);
355						}
356						if (existing.notText) throw new Error(notTextMessage(existing.notText));
357						const actual = findActualString(text, oldString);
358						if (!actual) {
359							const note = ESCAPE_RE.test(oldString) || NON_ASCII_RE.test(oldString) ? ESCAPE_NOTE : "";
360							throw new Error(`String to replace not found in file.\nString: ${oldString}${note}`);
361						}
362						const matches = text.split(actual).length - 1;
363						if (matches > 1 && !replaceAll) {
364							throw new Error(
365								`Found ${matches} matches of the string to replace, but replace_all is false. To replace all occurrences, set replace_all to true. To replace only one occurrence, please provide more context to uniquely identify the instance.\nString: ${oldString}`,
366							);
367						}
368					}
369	
370					// ---- apply ----
371					const fileExists = existing !== null;
372					const content = existing?.content ?? "";
373					let staleRecovered = false;
374					if (fileExists && rec && cc.fileState.isStale(absPath, content)) {
375						if (editOutcome(content, oldString, replaceAll) !== "applies") throw new Error(FILE_CONTENT_CHANGED);
376						staleRecovered = true;
377					}
378					if (existing?.notText) throw new Error(notTextMessage(existing.notText));
379					const actualOld = findActualString(content, oldString) || oldString;
380					let newString = preserveEscapeStyle(oldString, actualOld, preserveQuoteStyle(oldString, actualOld, newStringIn));
381					if (oldString === "") newString = addBomLike(content, newString);
382					let updated: string;
383					try {
384						updated = applyEdit(content, actualOld, newString, replaceAll);
385					} catch (err) {
386						if (err instanceof EditApplyError) throw new Error(err.message);
387						throw err;
388					}
389					const contentNotInModelContext =
390						fileExists && (!FileStateTracker.inModelContext(rec) || staleRecovered || !FileStateTracker.sameContent(rec!, content));
391	
392					if (signal?.aborted) throw new Error("Operation aborted");
393					await writeText(absPath, updated, existing?.encoding ?? "utf8", existing?.lineEndings ?? "LF", !fileExists);
394					cc.fileState.recordWrite(absPath, updated, { contentNotInModelContext, truncated: fileExists && rec?.truncated === true });
395	
396					const suffix = staleRecovered ? STALE_RECOVERED_NOTE : contentNotInModelContext ? "" : FILE_STATE_CURRENT_NOTE;
397					const text = replaceAll
398						? `The file ${filePath} has been updated. All occurrences were successfully replaced.${suffix}`
399						: `The file ${filePath} has been updated successfully.${suffix}`;
400					return {
401						content: [{ type: "text", text }],
402						details: { filePath: absPath, oldString: actualOld, newString: newStringIn, originalFile: fileExists ? content : null, replaceAll, created: !fileExists },
403					};
404				});
405			},
406		});
407	}
408	
409	function stripBom(s: string): string {
410		return s.charCodeAt(0) === 0xfeff ? s.slice(1) : s;
411	}
