89		const m = id.match(/^cell-(\d+)$/);
90		if (!m?.[1]) return undefined;
91		const n = Number.parseInt(m[1], 10);
92		return Number.isNaN(n) ? undefined : n;
93	}
94	
95	function isNotebook(nb: any): nb is { cells: any[]; metadata?: any; nbformat?: number; nbformat_minor?: number } {
96		const cells = nb?.cells;
97		return (
98			Array.isArray(cells) &&
99			!cells.some((c) => c === null || typeof c !== "object" || (typeof c.source !== "string" && !(Array.isArray(c.source) && c.source.every((s: unknown) => typeof s === "string"))))
100		);
101	}
102	
103	function sourceText(source: string | string[]): string {
104		return Array.isArray(source) ? source.join("") : source;
105	}
106	
107	function lineEndings(text: string): "CRLF" | "LF" {
108		const crlf = text.split("\r\n").length - 1;
109		const lf = text.split("\n").length - 1 - crlf;
110		return crlf > lf ? "CRLF" : "LF";
111	}
112	
113	function resultText(mode: string, cellId: string | undefined, newSource: string): string {
114		switch (mode) {
115			case "replace":
116				return `Updated cell ${cellId} with ${newSource}`;
117			case "insert":
118				return `Inserted cell ${cellId} with ${newSource}`;
119			case "delete":
120				return `Deleted cell ${cellId}`;
121			default:
122				return "Unknown edit mode";
123		}
124	}
125	
126	export function registerNotebookEdit(pi: ExtensionAPI, cc: CCContext): void {
127		pi.registerTool({
128			name: NOTEBOOK_EDIT_TOOL_NAME,
129			label: "Edit Notebook",
130			description: NOTEBOOK_EDIT_DESCRIPTION,
131			promptSnippet: "NotebookEdit: replace, insert or delete a cell in a Jupyter notebook",
132			parameters: NotebookEditParams as any,
133			prepareArguments: claudeInputValidator<NotebookEditInput>(NOTEBOOK_EDIT_TOOL_NAME, NotebookEditSpec),
134			async execute(_toolCallId, params, signal, _onUpdate, ctx) {
135				if (signal?.aborted) throw new Error("Operation aborted");
136				const { notebook_path, new_source, cell_id, edit_mode } = params as NotebookEditInput;
137				let cellType = (params as NotebookEditInput).cell_type;
138				const cwd = ctx?.cwd ?? process.cwd();
139				const absPath = resolvePath(cwd, notebook_path);
140	
141				return withFileMutationQueue(absPath, async () => {
142					// ---- validation (Claude Code's validateInput order) ----
143					const mode = edit_mode ?? "replace";
144					if (extname(absPath) !== ".ipynb") throw new NotebookEditError(NOTEBOOK_MESSAGES.notNotebook);
145					if (mode === "insert" && !cellType) throw new NotebookEditError(NOTEBOOK_MESSAGES.cellTypeRequired);
146					if (!cc.fileState.has(absPath)) throw new NotebookEditError(NOTEBOOK_MESSAGES.notRead);
147					if (cc.fileState.isStale(absPath)) throw new NotebookEditError(NOTEBOOK_MESSAGES.modified);
148					let raw: string;
149					try {
150						const st = await stat(absPath);
151						if (st.size > MAX_NOTEBOOK_BYTES) throw new NotebookEditError(NOTEBOOK_MESSAGES.tooLarge);
152						raw = await readFile(absPath, "utf8");
153					} catch (err: any) {
154						if (err?.code === "ENOENT") throw new NotebookEditError(NOTEBOOK_MESSAGES.missing);
155						throw err;
156					}
157					let nb: any;
158					try {
159						nb = JSON.parse(raw);
160					} catch {
161						throw new NotebookEditError(NOTEBOOK_MESSAGES.invalidJson);
162					}
163					if (!isNotebook(nb)) throw new NotebookEditError(NOTEBOOK_MESSAGES.invalidNotebook);
164					if (!cell_id) {
165						if (mode !== "insert") throw new NotebookEditError(NOTEBOOK_MESSAGES.cellIdRequired);
166					} else if (!nb.cells.some((c) => c.id === cell_id)) {
167						const idx = cellIndexFromId(cell_id);
168						if (idx === undefined) throw new NotebookEditError(`Cell with ID "${cell_id}" not found in notebook.`);
169						if (!nb.cells[idx]) throw new NotebookEditError(`Cell with index ${idx} does not exist in notebook.`);
170					}
171	
172					// ---- edit (Claude Code's call) ----
173					let index = 0;
174					if (cell_id) {
175						index = nb.cells.findIndex((c) => c.id === cell_id);
176						if (index === -1) index = cellIndexFromId(cell_id) ?? -1;
177						if (edit_mode === "insert") index += 1;
178					}
179					let effectiveMode = edit_mode;
180					if (effectiveMode === "replace" && index === nb.cells.length) {
181						effectiveMode = "insert";
182						cellType ||= "code";
183					}
184					const language: string = nb.metadata?.language_info?.name ?? "python";
185					let newCellId: string | undefined;
186					if ((nb.nbformat ?? 0) > 4 || (nb.nbformat === 4 && (nb.nbformat_minor ?? 0) >= 5)) {
187						if (effectiveMode === "insert") newCellId = randomUUID().slice(0, 8);
188						else newCellId = cell_id;
189					}
190					let oldSource: string | undefined;
191					if (effectiveMode === "delete") {
192						oldSource = sourceText(nb.cells[index].source);
193						nb.cells.splice(index, 1);
194					} else if (effectiveMode === "insert") {
195						const cell =
196							cellType === "markdown"
197								? { cell_type: "markdown", id: newCellId, source: new_source, metadata: {} }
198								: { cell_type: "code", id: newCellId, source: new_source, metadata: {}, execution_count: null, outputs: [] };
199						nb.cells.splice(index, 0, cell);
200					} else {
201						const cell = nb.cells[index];
202						oldSource = sourceText(cell.source);
203						cell.source = new_source;
204						if (cell.cell_type === "code") {
205							cell.execution_count = null;
206							cell.outputs = [];
207						}
208						if (cellType && cellType !== cell.cell_type) cell.cell_type = cellType;
209					}
210					let out = JSON.stringify(nb, null, 1);
211					if (lineEndings(raw) === "CRLF") out = out.replace(/\n/g, "\r\n");
212					if (Buffer.byteLength(out, "utf8") > MAX_NOTEBOOK_BYTES) {
213						throw new NotebookEditError("Edit rejected: the updated notebook would exceed the maximum size this tool can read (100MB). The file was left unchanged.");
214					}
215					if (signal?.aborted) throw new Error("Operation aborted");
216					await writeFile(absPath, out, "utf8");
217					cc.fileState.recordWrite(absPath, out);
218					const resultMode = effectiveMode ?? "replace";
219					const resultCellId = newCellId || undefined;
220					return textResult<NotebookEditDetails>(resultText(resultMode, resultCellId, new_source), {
221						notebook_path: absPath,
222						cell_id: resultCellId,
223						cell_type: cellType ?? "code",
224						edit_mode: resultMode,
225						language,
226						new_source,
227						old_source: oldSource,
228					});
229				});
230			},
231		});
232	}
