10	// Mirrors Claude Code 2.1.302's Write tool (description, schema, validation order and messages).
11	
12	const DESCRIPTION = `Writes a file to the local filesystem.
13	
14	Usage:
15	- This tool will overwrite the existing file if there is one at the provided path.
16	- If this is an existing file, you MUST use the Read tool first to read the file's contents. This tool will fail if you did not read the file first.
17	- Prefer the Edit tool for modifying existing files — it only sends the diff. Only use this tool to create new files or for complete rewrites.
18	- NEVER create documentation files (*.md) or README files unless explicitly requested by the User.
19	- Only use emojis if the user explicitly requests it. Avoid writing emojis to files unless asked.`;
20	
21	const writeSchema = Type.Object(
22		{
23			file_path: Type.String({ description: "The absolute path to the file to write (must be absolute, not relative)" }),
24			content: Type.String({ description: "The content to write to the file" }),
25		},
26		{ additionalProperties: false },
27	);
28	
29	export interface WriteToolDetails {
30		filePath: string;
31		type: "create" | "update";
32		/** Previous content (null for new files). */
33		originalFile: string | null;
34		bytes: number;
35	}
36	
37	/** Appended to Write/Edit results when the model's view of the file is the file's current content. */
38	export const FILE_STATE_CURRENT_NOTE = " (file state is current in your context — no need to Read it back)";
39	
40	// ---------------------------------------------------------------------------------------------
41	// Text file I/O shared with Edit (Claude Code keeps the encoding; Edit also keeps CRLF)
42	// ---------------------------------------------------------------------------------------------
43	
44	export type NotTextKind = "not_utf8" | "nul" | "utf16be";
45	export type TextEncodingName = "utf8" | "utf16le";
46	
47	export interface ExistingText {
48		/** Decoded content with CRLF folded to LF (a BOM is kept as U+FEFF). */
49		content: string;
50		encoding: TextEncodingName;
51		lineEndings: "LF" | "CRLF";
52		notText?: NotTextKind;
53	}
54	
55	const NOT_TEXT_REASONS: Record<NotTextKind, string> = {
56		not_utf8: "is not valid UTF-8: it uses a legacy encoding such as Windows-1252, Shift-JIS or GBK, or it is binary",
57		nul: "has NUL bytes in its first 8 KB: binary data, UTF-16/UTF-32 without a byte-order mark, or text with embedded NULs",
58		utf16be: "is UTF-16 big-endian (it starts FE FF), which these tools cannot write",
59	};
60	
61	export function notTextMessage(kind: NotTextKind): string {
62		return `File ${NOT_TEXT_REASONS[kind]}. These tools write UTF-8 (or UTF-16LE behind its byte-order mark) and never convert a file's encoding on their own, so nothing was written. If the file is text, make the change with a shell command that reads and writes it in its own encoding (iconv, or PowerShell Get-Content/Set-Content -Encoding), or ask the user whether to convert it to UTF-8 first. To replace the whole file with new UTF-8 text anyway, delete it first, then Write it.`;
63	}
64	
65	const utf8Strict = new TextDecoder("utf-8", { fatal: true });
66	
67	function classify(buf: Buffer): { encoding: TextEncodingName; notText?: NotTextKind } {
68		if (buf.length >= 2 && buf[0] === 0xff && buf[1] === 0xfe) return { encoding: "utf16le" };
69		if (buf.length >= 2 && buf[0] === 0xfe && buf[1] === 0xff) return { encoding: "utf8", notText: "utf16be" };
70		if (buf.subarray(0, 8000).includes(0)) return { encoding: "utf8", notText: "nul" };
71		try {
72			utf8Strict.decode(buf);
73		} catch {
74			return { encoding: "utf8", notText: "not_utf8" };
75		}
76		return { encoding: "utf8" };
77	}
78	
79	/** CRLF when more lines of the sample end in CRLF than in a bare LF. */
80	export function detectLineEndings(sample: string): "LF" | "CRLF" {
81		let crlf = 0;
82		let lf = 0;
83		for (let i = 0; i < sample.length; i++) {
84			if (sample[i] === "\n") {
85				if (i > 0 && sample[i - 1] === "\r") crlf++;
86				else lf++;
87			}
88		}
89		return crlf > lf ? "CRLF" : "LF";
90	}
91	
92	/** Read an existing file as text; null when it does not exist. Other errors (EISDIR, ...) are thrown. */
93	export async function readExistingText(absPath: string): Promise<ExistingText | null> {
94		let buf: Buffer;
95		try {
96			buf = await readFile(absPath);
97		} catch (err: any) {
98			if (err?.code === "ENOENT") return null;
99			throw err;
100		}
101		const { encoding, notText } = classify(buf);
102		const raw = buf.toString(encoding);
103		return { content: raw.replaceAll("\r\n", "\n"), encoding, lineEndings: detectLineEndings(raw.slice(0, 4096)), ...(notText && { notText }) };
104	}
105	
106	/** Write text in the given encoding, converting LF to CRLF when the file used CRLF. */
107	export async function writeText(absPath: string, content: string, encoding: TextEncodingName, lineEndings: "LF" | "CRLF", createParents = true): Promise<void> {
108		const text = lineEndings === "CRLF" ? content.replaceAll("\r\n", "\n").split("\n").join("\r\n") : content;
109		if (createParents) await mkdir(dirname(absPath), { recursive: true });
110		await writeFile(absPath, Buffer.from(text, encoding));
111	}
112	
113	// ---------------------------------------------------------------------------------------------
114	// Registration
115	// ---------------------------------------------------------------------------------------------
116	
117	export function registerWrite(pi: ExtensionAPI, cc: CCContext): void {
118		pi.registerTool({
119			name: "Write",
120			label: "Write",
121			description: DESCRIPTION,
122			promptSnippet: "Create or overwrite files",
123			parameters: writeSchema,
124			async execute(_toolCallId, params, signal, _onUpdate, ctx): Promise<AgentToolResult<WriteToolDetails>> {
125				if (signal?.aborted) throw new Error("Operation aborted");
126				const filePath = params.file_path;
127				if (typeof filePath !== "string" || typeof params.content !== "string") throw new Error("file_path and content are required strings.");
128				const absPath = resolvePath(ctx?.cwd ?? process.cwd(), filePath);
129	
130				return withFileMutationQueue(absPath, async () => {
131					if (signal?.aborted) throw new Error("Operation aborted");
132					// ---- validation (same order as Claude Code) ----
133					if (cc.options.isSubagent && /^(REPORT|SUMMARY|FINDINGS|ANALYSIS).*\.md$/i.test(basename(absPath))) {
134						throw new Error("Subagents should return findings as text, not write report files. Include this content in your final response instead.");
135					}
136					let existedBefore = true;
137					try {
138						const st = await stat(absPath);
139						if (st.isDirectory()) throw new Error(`${filePath} is a directory, not a file. To create a file inside it, include the file name in file_path.`);
140						if (!st.isFile()) throw new Error(`${filePath} exists but is not a regular file (a device, FIFO or socket). Write only creates or overwrites regular files.`);
141					} catch (err: any) {
142						if (err?.code !== "ENOENT") throw err;
143						existedBefore = false;
144					}
145					if (existedBefore) {
146						const rec = cc.fileState.get(absPath);
147						if (!rec || rec.truncated) {
148							if (rec || absPath.toLowerCase().endsWith(".ipynb")) throw new Error(FILE_NOT_READ);
149						} else if (cc.fileState.isStale(absPath)) {
150							throw new Error(FILE_MODIFIED_SINCE_READ);
151						}
152					}
153	
154					// ---- write ----
155					const existing = await readExistingText(absPath);
156					if (existing?.notText) throw new Error(notTextMessage(existing.notText));
157					const original = existing?.content ?? null;
158					let content = params.content;
159					if (content !== "" && original?.charCodeAt(0) === 0xfeff && content.charCodeAt(0) !== 0xfeff) content = `﻿${content}`;
160					if (signal?.aborted) throw new Error("Operation aborted");
161					await writeText(absPath, content, existing?.encoding ?? "utf8", "LF");
162					cc.fileState.recordWrite(absPath, content);
163	
164					const text =
165						existing !== null
166							? `The file ${filePath} has been updated successfully.${FILE_STATE_CURRENT_NOTE}`
167							: `File created successfully at: ${filePath}${FILE_STATE_CURRENT_NOTE}`;
168					return {
169						content: [{ type: "text", text }],
170						details: { filePath: absPath, type: existing !== null ? "update" : "create", originalFile: original, bytes: Buffer.byteLength(content, existing?.encoding ?? "utf8") },
171					};
172				});
173			},
174		});
175	}
