1	import { createHash } from "node:crypto";
2	import { readFileSync, statSync } from "node:fs";
3	
4	/**
5	 * What the model has seen of a file, mirroring Claude Code's `readFileState` entries.
6	 *
7	 * - `timestamp` is `Math.floor(mtimeMs)` when the file was read or written by a tool.
8	 * - `hash` is the hash of the whole file's text as Claude Code compares it (UTF-8 BOM stripped,
9	 *   CRLF folded to LF), so a rewrite that leaves the text unchanged is not "a change".
10	 * - `partial` means the read did not cover the whole file (offset/limit); content comparisons and
11	 *   the "file state is current" note then do not apply. It does not block writes.
12	 * - `truncated` is Claude Code's `isPartialView`: the Read result was a cut-down excerpt. Write
13	 *   refuses such a file as "not read yet"; Edit keeps the flag on the record it writes.
14	 * - `contentNotInModelContext` marks an Edit that changed a file the model had not fully seen.
15	 */
16	export interface FileRecord {
17		timestamp: number;
18		hash: string;
19		partial: boolean;
20		truncated: boolean;
21		offset?: number;
22		limit?: number;
23		contentNotInModelContext: boolean;
24		source: "read" | "write";
25	}
26	
27	export interface RecordReadOptions {
28		/** The read covered only part of the file (offset > 1 or a limit that cut the file short). */
29		partial?: boolean;
30		/** The Read result was a truncated excerpt (Claude Code's isPartialView). */
31		truncated?: boolean;
32		offset?: number;
33		limit?: number;
34	}
35	
36	export interface RecordWriteOptions {
37		/** The model has not seen the whole resulting file (Edit of a file it never fully read). */
38		contentNotInModelContext?: boolean;
39		/** Keep the truncated (isPartialView) flag of the previous record. */
40		truncated?: boolean;
41	}
42	
43	export const FILE_MODIFIED_SINCE_READ =
44		"File has been modified since read, either by the user or by a linter. Read it again before attempting to write it.";
45	export const FILE_NOT_READ = "File has not been read yet. Read it first before writing to it.";
46	export const FILE_CONTENT_CHANGED =
47		"File content has changed since it was last read. This commonly happens when a linter or formatter run via Bash rewrites the file. Call Read on this file to refresh, then retry the edit.";
48	
49	export function hashContent(content: string | Buffer): string {
50		return createHash("sha256").update(content).digest("hex");
51	}
52	
53	function decodeForCompare(buf: Buffer): string {
54		if (buf.length >= 2 && buf[0] === 0xff && buf[1] === 0xfe) return buf.toString("utf16le");
55		return buf.toString("utf8");
56	}
57	
58	/** Text as Claude Code compares file contents: BOM stripped, CRLF folded to LF. */
59	export function normalizeText(content: string | Buffer): string {
60		let text = typeof content === "string" ? content : decodeForCompare(content);
61		if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
62		return text.replaceAll("\r\n", "\n");
63	}
64	
65	export function textHash(content: string | Buffer): string {
66		return hashContent(normalizeText(content));
67	}
68	
69	function mtimeOf(absPath: string): number {
70		return Math.floor(statSync(absPath).mtimeMs);
71	}
72	
73	/**
74	 * Tracks which files the model has read (or a tool has written) and their state at that time, so
75	 * Write/Edit can detect files that changed on disk since. Keys are absolute paths.
76	 */
77	export class FileStateTracker {
78		private records = new Map<string, FileRecord>();
79	
80		/** Record a read. Pass the whole file content (Buffer or text) so it can be hashed. */
81		recordRead(absPath: string, content: string | Buffer, opts: RecordReadOptions = {}): void {
82			this.records.set(absPath, {
83				timestamp: mtimeOf(absPath),
84				hash: textHash(content),
85				partial: !!opts.partial,
86				truncated: !!opts.truncated,
87				offset: opts.offset,
88				limit: opts.limit,
89				contentNotInModelContext: false,
90				source: "read",
91			});
92		}
93	
94		/** Record that a tool just wrote `content` to absPath. */
95		recordWrite(absPath: string, content: string | Buffer, opts: RecordWriteOptions = {}): void {
96			this.records.set(absPath, {
97				timestamp: mtimeOf(absPath),
98				hash: textHash(content),
99				partial: false,
100				truncated: !!opts.truncated,
101				contentNotInModelContext: !!opts.contentNotInModelContext,
102				source: "write",
103			});
104		}
105	
106		get(absPath: string): FileRecord | undefined {
107			return this.records.get(absPath);
108		}
109	
110		has(absPath: string): boolean {
111			return this.records.has(absPath);
112		}
113	
114		forget(absPath: string): void {
115			this.records.delete(absPath);
116		}
117	
118		/** Whether the record covers the whole file (Claude Code's "full view"). */
119		static isFullView(rec: FileRecord | undefined): rec is FileRecord {
120			return rec !== undefined && !rec.partial && !rec.truncated;
121		}
122	
123		/** Whether the model has the file's whole recorded text in context. */
124		static inModelContext(rec: FileRecord | undefined): boolean {
125			return FileStateTracker.isFullView(rec) && !rec.contentNotInModelContext;
126		}
127	
128		/** Whether `text` equals the recorded content (after BOM/CRLF normalization). */
129		static sameContent(rec: FileRecord, text: string | Buffer): boolean {
130			return rec.hash === textHash(text);
131		}
132	
133		/**
134		 * Whether the file changed on disk since it was recorded: its mtime moved past the record and,
135		 * for full views, its text differs. `currentText` avoids re-reading the file.
136		 */
137		isStale(absPath: string, currentText?: string | Buffer): boolean {
138			const rec = this.records.get(absPath);
139			if (!rec) return false;
140			let mtime: number;
141			try {
142				mtime = mtimeOf(absPath);
143			} catch {
144				return false;
145			}
146			if (mtime <= rec.timestamp) return false;
147			if (!FileStateTracker.isFullView(rec)) return true;
148			return !FileStateTracker.sameContent(rec, currentText ?? readFileSync(absPath));
149		}
150	
151		/**
152		 * Whether an existing file may be overwritten as a whole (Write's rules): never-read files are
153		 * fine, truncated views and files changed since they were read are not.
154		 * Returns undefined when OK, or an error message for the model.
155		 */
156		checkCanModify(absPath: string): string | undefined {
157			try {
158				statSync(absPath);
159			} catch {
160				return undefined; // new file
161			}
162			const rec = this.records.get(absPath);
163			if (rec?.truncated) return FILE_NOT_READ;
164			if (rec && this.isStale(absPath)) return FILE_MODIFIED_SINCE_READ;
165			return undefined;
166		}
167	
168		/** Paths recorded so far whose on-disk content changed since (for change reminders). */
169		changedSinceRead(): string[] {
170			const out: string[] = [];
171			for (const p of this.records.keys()) {
172				try {
173					if (this.isStale(p)) out.push(p);
174				} catch {
175					out.push(p);
176				}
177			}
178			return out;
179		}
180	}
