4	/** Resolve a user/model supplied path against cwd, expanding a leading "~". */
5	export function resolvePath(cwd: string, p: string): string {
6		let path = p.trim();
7		if (path === "~") path = homedir();
8		else if (path.startsWith("~/")) path = homedir() + path.slice(1);
9		return isAbsolute(path) ? resolve(path) : resolve(cwd, path);
